@dataclass(frozen=True)
class WorkflowRoutingInfo:
    """Transparent record of how a chat turn was routed.

    JVNAUTOSCI-825: Provides traceable reasoning for the routing decision:
    which workflow was selected, what the classifier verdict was, which
    discovered workflows were candidates, and how long routing took.

    JVNAUTOSCI-1424 Phase 3: Enriched with confidence_score and reasoning
    from the model-based selection.
    """

    workflow_id: str
    verdict: str
    prompt_id: str | None
    discovered_workflow_ids: tuple[str, ...]
    routing_duration_ms: float | None = None
    source: str = (
        "selector"  # "selector" | "selector_override" | "default" | "presenter_mode"
    )
    confidence_score: float = 0.0
    reasoning: str = ""
    selection_rationale: str = ""


def _resolve_identity_context(
    *,
    user_concept_id: str | None,
    org_concept_id: str | None,
    user_namespace: str | None,
) -> tuple[str | None, str | None]:
    """Resolve actor IDs from explicit inputs first, then canonical namespace components."""

    resolved_user = user_concept_id if isinstance(user_concept_id, str) else None
    resolved_org = org_concept_id if isinstance(org_concept_id, str) else None
    namespace_user, namespace_org = derive_actor_context_from_namespace(user_namespace)
    if not resolved_user:
        resolved_user = namespace_user
    if not resolved_org:
        resolved_org = namespace_org
    return resolved_user, resolved_org


def _coerce_conversation_turn_llm_timeout_override_sec(
    raw_timeout: Any,
) -> float | None:
    return coerce_conversation_turn_llm_advisory_sec(raw_timeout)


def _default_conversation_turn_llm_timeout_override_sec() -> float | None:
    return default_conversation_turn_llm_advisory_sec(
        os.getenv("VON_CONVERSATION_TURN_LLM_ADVISORY_SEC")
        or os.getenv("VON_CONVERSATION_TURN_LLM_TIMEOUT_SEC")
    )


def _without_elapsed_hard_timeout_params(
    parameters: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """Return provider parameters without repository-created wall-clock caps."""

    params = dict(parameters or {})
    params.pop("request_timeout_seconds", None)
    params.pop("timeout_seconds", None)
    params.pop("request_advisory_seconds", None)
    return params or None


def _provider_from_llm_client(llm_client: Any) -> str | None:
    class_name = type(llm_client).__name__.lower()
    if "ollama" in class_name:
        return "ollama"
    if "openrouter" in class_name:
        return "openrouter"
    if "openai" in class_name:
        return "openai"
    if "gemini" in class_name:
        return "gemini"
    if "metamuse" in class_name or "meta_muse" in class_name:
        return "meta"
    if "anthropic" in class_name or "claude" in class_name:
        return "anthropic"
    return None


def _truthy_env_value(value: Any) -> bool:
    return str(value or "").strip().lower() in {"1", "true", "yes", "on"}


def _is_agent_test_instance() -> bool:
    return _truthy_env_value(os.getenv("VON_AGENT_TEST_INSTANCE"))


def _model_identifier_looks_local_ollama(model: Any) -> bool:
    if not isinstance(model, str):
        return False
    cleaned = model.strip().lower().replace(": ", ":")
    if not cleaned:
        return False
    if cleaned.startswith("ollama:"):
        return True
    if cleaned.startswith(
        (
            "openai:",
            "openrouter:",
            "anthropic:",
            "gemini:",
            "meta:",
            "azure_openai:",
        )
    ):
        return False
    if cleaned.startswith(("gpt-", "o1-", "claude", "gemini")):
        return False
    return ":" in cleaned


def _explicit_model_request_uses_local_provider(
    *, llm_client: Any, model: str | None
) -> bool:
    if not isinstance(model, str) or not model.strip():
        return False
    provider = _provider_from_llm_client(llm_client)
    return provider == "ollama" or _model_identifier_looks_local_ollama(model)


def _conversation_turn_llm_timeout_override_sec_from_data(
    data: Mapping[str, Any] | None,
) -> float | None:
    if not isinstance(data, Mapping):
        return None
    return _coerce_conversation_turn_llm_timeout_override_sec(
        data.get(_CONVERSATION_TURN_LLM_TIMEOUT_CONTEXT_KEY)
    )


def _resolve_model_llm_timeout_override_sec(
    llm_client: Any,
    model: str | None,
    model_budget_policy: ModelExecutionBudgetPolicy | None = None,
) -> float | None:
    """Look up the per-model timeout from settings, env, or Vontology policy.

    The provider is inferred from the LLM client's class name so we avoid
    importing the concrete client classes here.
    """
    if isinstance(model, str) and model.strip():
        try:
            provider = _provider_from_llm_client(llm_client)
            if provider:
                saved = get_model_llm_timeout(provider, model.strip())
                if saved is not None:
                    return saved
        except Exception:
            logging.getLogger(__name__).debug(
                "Model LLM timeout lookup failed; using default timeout policy",
                exc_info=True,
            )

    if os.getenv("VON_CONVERSATION_TURN_LLM_TIMEOUT_SEC"):
        return _default_conversation_turn_llm_timeout_override_sec()

    if (
        model_budget_policy is not None
        and model_budget_policy.conversation_turn_llm_timeout_sec is not None
    ):
        return model_budget_policy.conversation_turn_llm_timeout_sec

    return _default_conversation_turn_llm_timeout_override_sec()


def _resolve_model_execution_budget_policy(
    *, llm_client: Any, model: str | None
) -> ModelExecutionBudgetPolicy | None:
    provider = _provider_from_llm_client(llm_client)
    try:
        return resolve_model_execution_budget_policy(provider=provider, model=model)
    except Exception:
        return None


@dataclass(frozen=True)
class OrchestratorResult:
    """Structured response from a tool-aware chat exchange."""

    response_text: str
    extra_messages: Sequence[Mapping[str, Any]]
    tool_invocations: Sequence[Mapping[str, Any]]
    aux_llm_calls: Sequence[Mapping[str, Any]]

    # Optional LLM interaction telemetry (JVNAUTOSCI-877). Append-only for backwards compatibility.
    llm_calls: Sequence[Mapping[str, Any]] = ()
    llm_usage: Mapping[str, Any] | None = None
    orchestrator_duration_ms: float | None = None
    # JVNAUTOSCI-825: Workflow routing transparency.
    workflow_routing: WorkflowRoutingInfo | None = None
    workflow_discovery_result: Mapping[str, Any] | None = None
    # JVNAUTOSCI-1140: Optional renderer routing/render-mode diagnostics.
    # Present only when renderer applicability routing is enabled and evaluated.
    render_plan: Mapping[str, Any] | None = None

    # JVNAUTOSCI-1768: Supervised workflow telemetry
    selected_workflow_trace: Mapping[str, Any] | None = None
    critic_verdict: Mapping[str, Any] | None = None
    completion_gate_verdict: Mapping[str, Any] | None = None
    completion_report: Mapping[str, Any] | None = None


