def _workflow_required_tools_from_contract(
    contract: Mapping[str, Any] | None,
) -> list[str]:
    return _workflow_required_tools_from_contract_support(contract)


_WORKFLOW_AMBIENT_INPUT_KEYS_KEY = "__workflow_ambient_input_keys"
_NAMESPACED_WORKFLOW_LAUNCH_INPUT_RESERVED_KEYS: frozenset[str] = frozenset(
    {
        "workflow_id",
        "failure_mode",
        "selected_workflow_id",
        "prompt",
        "user_prompt",
    }
)


def _normalise_workflow_input_key_set(value: Any) -> set[str]:
    if isinstance(value, str):
        cleaned = value.strip()
        return {cleaned} if cleaned else set()
    if not isinstance(value, (list, tuple, set)):
        return set()
    return {
        cleaned for item in value if isinstance(item, str) and (cleaned := item.strip())
    }


def _mark_workflow_launch_inputs_as_ambient(inputs: dict[str, Any]) -> None:
    ambient_keys = _normalise_workflow_input_key_set(
        inputs.get(_WORKFLOW_AMBIENT_INPUT_KEYS_KEY)
    )
    ambient_keys.update(
        key
        for key in inputs.keys()
        if isinstance(key, str) and key != _WORKFLOW_AMBIENT_INPUT_KEYS_KEY
    )
    if ambient_keys:
        inputs[_WORKFLOW_AMBIENT_INPUT_KEYS_KEY] = sorted(ambient_keys)


def _project_namespaced_workflow_launch_inputs(inputs: dict[str, Any]) -> None:
    raw_launch_inputs = inputs.get("workflow_launch_inputs")
    if not isinstance(raw_launch_inputs, Mapping):
        return

    applied_keys: list[str] = []
    for key, value in raw_launch_inputs.items():
        if not isinstance(key, str):
            continue
        key_text = key.strip()
        if (
            not key_text
            or key_text.startswith("__")
            or key_text in _NAMESPACED_WORKFLOW_LAUNCH_INPUT_RESERVED_KEYS
        ):
            continue
        inputs[key_text] = value
        applied_keys.append(key_text)
    if applied_keys:
        inputs["namespaced_workflow_launch_inputs_applied"] = sorted(
            dict.fromkeys(applied_keys)
        )


def _strip_excluded_ambient_workflow_launch_inputs(
    data: dict[str, Any],
    *,
    launch_input_contract: Mapping[str, Any] | None,
) -> list[str]:
    ambient_keys = _normalise_workflow_input_key_set(
        data.pop(_WORKFLOW_AMBIENT_INPUT_KEYS_KEY, None)
    )
    if not ambient_keys or not isinstance(launch_input_contract, Mapping):
        return []

    normalised_contract, _contract_error = normalise_workflow_launch_input_contract(
        launch_input_contract
    )
    if not isinstance(normalised_contract, Mapping):
        return []
    excluded_keys = [
        key.strip()
        for key in (
            normalised_contract.get(WORKFLOW_LAUNCH_INPUT_EXCLUDED_AMBIENT_INPUT_KEYS)
            or []
        )
        if isinstance(key, str) and key.strip()
    ]
    removed: list[str] = []
    for key in excluded_keys:
        if key in ambient_keys and key in data:
            data.pop(key, None)
            removed.append(key)
    return sorted(dict.fromkeys(removed))


def _merge_excluded_ambient_launch_diagnostics(
    diagnostics: dict[str, Any],
    removed_keys: Sequence[str],
) -> dict[str, Any]:
    clean_removed = [
        key.strip() for key in removed_keys if isinstance(key, str) and key.strip()
    ]
    if not clean_removed:
        return diagnostics
    existing = diagnostics.get("excluded_ambient_inputs_applied")
    existing_keys = [
        key.strip()
        for key in (existing if isinstance(existing, list) else [])
        if isinstance(key, str) and key.strip()
    ]
    diagnostics["excluded_ambient_inputs_applied"] = sorted(
        dict.fromkeys([*existing_keys, *clean_removed])
    )
    return diagnostics


def _evaluate_workflow_required_effects_tool_policy(
    workflow_def: Any | None,
) -> dict[str, Any]:
    return _evaluate_workflow_required_effects_tool_policy_support(workflow_def)


def _workflow_terminal_success_evaluation_from_result(
    workflow_result: Any,
) -> Mapping[str, Any] | None:
    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None
    evaluation = result_data.get("workflow_terminal_success_evaluation")
    if isinstance(evaluation, Mapping):
        return evaluation
    return None


def _derive_workflow_terminal_status(workflow_result: Any) -> str | None:
    result_data = getattr(workflow_result, "data", None)
    if isinstance(result_data, Mapping):
        result_envelope = result_data.get(WORKFLOW_RESULT_ENVELOPE_KEY)
        if isinstance(result_envelope, Mapping):
            envelope_status = _workflow_execution_summary_text(
                result_envelope.get("terminal_status")
            )
            if envelope_status:
                return envelope_status
    error_text = _workflow_execution_summary_text(
        getattr(workflow_result, "error", None)
    )
    final_state = _workflow_execution_summary_text(
        getattr(workflow_result, "final_state", None)
    )
    if not final_state:
        return None
    return derive_workflow_terminal_status(
        completed=bool(getattr(workflow_result, "completed", False)),
        final_state=final_state,
        error=error_text or None,
    )


def _workflow_result_effective_completed(workflow_result: Any) -> bool:
    if not bool(getattr(workflow_result, "completed", False)):
        return False
    if _workflow_execution_summary_text(getattr(workflow_result, "error", None)):
        return False
    final_state = _workflow_execution_summary_text(
        getattr(workflow_result, "final_state", None)
    )
    if _workflow_final_state_is_failure_like(final_state):
        return False
    terminal_success_evaluation = _workflow_terminal_success_evaluation_from_result(
        workflow_result
    )
    if isinstance(terminal_success_evaluation, Mapping):
        return bool(terminal_success_evaluation.get("success"))
    return True


def _workflow_execution_summary_mapping_list(value: Any) -> list[Mapping[str, Any]]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes, bytearray)):
        return []
    return [
        cast(Mapping[str, Any], item) for item in value if isinstance(item, Mapping)
    ]


def _extract_workflow_step_failure_detail(envelope: Any) -> str | None:
    if not isinstance(envelope, Mapping):
        return None

    diagnostics = envelope.get("diagnostics")
    if isinstance(diagnostics, Mapping):
        error_text = _workflow_execution_summary_text(diagnostics.get("error"))
        if error_text:
            return error_text

    for key in ("error", "action_error"):
        error_text = _workflow_execution_summary_text(envelope.get(key))
        if error_text:
            return error_text

    output_payload = envelope.get("output_payload")
    if isinstance(output_payload, Mapping):
        for payload_key in ("result", "mcp_result"):
            payload = output_payload.get(payload_key)
            if not isinstance(payload, Mapping):
                continue
            error_text = _workflow_execution_summary_text(payload.get("error"))
            if error_text:
                return error_text
            message_text = _workflow_execution_summary_text(payload.get("message"))
            if message_text:
                return message_text

    return None


def _extract_explicit_workflow_failure_detail(workflow_result: Any) -> str | None:
    if _workflow_result_effective_completed(workflow_result):
        return None

    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None

    for key in (
        "last_action_error",
        "workflow_error",
        "failure_detail",
        "termination_detail",
        "error",
    ):
        error_text = _workflow_execution_summary_text(result_data.get(key))
        if error_text:
            return _normalise_workflow_failure_detail_for_user(error_text)

    last_step_envelope = result_data.get(LAST_WORKFLOW_STEP_RESULT_ENVELOPE_KEY)
    step_error = _extract_workflow_step_failure_detail(last_step_envelope)
    if step_error:
        return _normalise_workflow_failure_detail_for_user(step_error)

    step_envelopes = _workflow_execution_summary_mapping_list(
        result_data.get(WORKFLOW_STEP_RESULT_ENVELOPES_KEY)
    )
    for envelope in reversed(step_envelopes):
        step_error = _extract_workflow_step_failure_detail(envelope)
        if step_error:
            return _normalise_workflow_failure_detail_for_user(step_error)

    result_envelope = result_data.get(WORKFLOW_RESULT_ENVELOPE_KEY)
    if isinstance(result_envelope, Mapping):
        diagnostics = result_envelope.get("diagnostics")
        if isinstance(diagnostics, Mapping):
            error_text = _workflow_execution_summary_text(diagnostics.get("error"))
            if error_text:
                return _normalise_workflow_failure_detail_for_user(error_text)

    return None


def _normalise_workflow_failure_detail_for_user(error_text: Any) -> str | None:
    cleaned_error = _workflow_execution_summary_text(error_text)
    if not cleaned_error:
        return None

    lowered = cleaned_error.lower()
    if "insufficient_quota" in lowered:
        return (
            "OpenAI quota exhausted (insufficient_quota). "
            "Please check provider billing or try again later."
        )

    return cleaned_error


def _safe_workflow_execution_aux_snapshot_value(
    value: Any,
    *,
    depth: int = 0,
    max_depth: int = 3,
    max_items: int = 20,
) -> Any:
    if depth >= max_depth:
        if isinstance(value, (str, int, float, bool)) or value is None:
            return value
        return str(type(value).__name__)
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    if isinstance(value, Mapping):
        snapshot: dict[str, Any] = {}
        for index, (key, item) in enumerate(value.items()):
            if index >= max_items:
                break
            if not isinstance(key, str) or callable(item):
                continue
            snapshot[key] = _safe_workflow_execution_aux_snapshot_value(
                item,
                depth=depth + 1,
                max_depth=max_depth,
                max_items=max_items,
            )
        return snapshot
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        items: list[Any] = []
        for index, item in enumerate(value):
            if index >= max_items:
                break
            items.append(
                _safe_workflow_execution_aux_snapshot_value(
                    item,
                    depth=depth + 1,
                    max_depth=max_depth,
                    max_items=max_items,
                )
            )
        return items
    return str(value)


def _build_workflow_execution_aux_result_snapshot(
    workflow_result: Any,
) -> dict[str, Any] | None:
    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None

    snapshot: dict[str, Any] = {}
    for key in _WORKFLOW_EXECUTION_AUX_RESULT_SNAPSHOT_KEYS:
        if key in result_data:
            raw_value = result_data.get(key)
        else:
            raw_value = None
            for (
                fallback_key
            ) in _WORKFLOW_EXECUTION_AUX_RESULT_SNAPSHOT_FALLBACK_KEYS.get(key, ()):
                if fallback_key in result_data:
                    raw_value = result_data.get(fallback_key)
                    break
            if raw_value is None:
                continue
        if key == _WORKFLOW_AUTHORITY_OUTPUT_SNAPSHOT_KEY:
            projected_output, projection_metadata = (
                _build_workflow_authority_output_snapshot(raw_value)
            )
            projection_metadata.update(_workflow_authority_prompt_lineage(result_data))
            workflow_execution_identity = getattr(
                workflow_result,
                _WORKFLOW_EXECUTION_IDENTITY_ATTRIBUTE,
                None,
            )
            if isinstance(workflow_execution_identity, Mapping):
                projection_metadata["workflow_execution_identity"] = (
                    _safe_workflow_execution_aux_snapshot_value(
                        workflow_execution_identity,
                        max_depth=4,
                        max_items=24,
                    )
                )
            snapshot[key] = projected_output
            snapshot[_WORKFLOW_AUTHORITY_OUTPUT_SNAPSHOT_METADATA_KEY] = (
                projection_metadata
            )
            continue
        snapshot[key] = _safe_workflow_execution_aux_snapshot_value(raw_value)
    return snapshot or None


def _extract_workflow_execution_identifier_values(value: Any) -> list[str]:
    candidate_values: list[str] = []
    seen: set[str] = set()

    def _append(raw_value: Any) -> None:
        if len(candidate_values) >= _WORKFLOW_EXECUTION_SUMMARY_MAX_IDS_PER_EFFECT:
            return
        cleaned = _workflow_execution_summary_text(raw_value)
        if not cleaned:
            return
        lowered = cleaned.lower()
        if lowered in seen:
            return
        seen.add(lowered)
        candidate_values.append(cleaned)

    if isinstance(value, str):
        _append(value)
        return candidate_values

    if isinstance(value, Mapping):
        for candidate_key in ("concept_id", "workflow_id", "id", "instance_id"):
            if candidate_key in value:
                _append(value.get(candidate_key))
        return candidate_values

    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        for item in value:
            if isinstance(item, Mapping):
                for candidate_key in ("concept_id", "workflow_id", "id", "instance_id"):
                    if candidate_key in item:
                        _append(item.get(candidate_key))
                        break
            else:
                _append(item)
        return candidate_values

    return candidate_values


def _normalise_workflow_mutation_kind(value: str) -> str:
    cleaned = str(value or "").strip().lower()
    if cleaned == "materialized":
        return "materialised"
    return cleaned


def _normalise_workflow_artefact_type(value: str) -> str:
    cleaned = str(value or "").strip().lower().strip("_")
    return re.sub(r"_+", "_", cleaned)


def _collect_workflow_durable_side_effects(
    payload: Any,
    *,
    path: tuple[str, ...] = (),
    depth: int = 0,
    collected: list[dict[str, Any]] | None = None,
    seen: set[tuple[str, str, str, tuple[str, ...]]] | None = None,
) -> list[dict[str, Any]]:
    if collected is None:
        collected = []
    if seen is None:
        seen = set()
    if (
        not isinstance(payload, Mapping)
        or depth > _WORKFLOW_EXECUTION_SUMMARY_MAX_SCAN_DEPTH
    ):
        return collected

    for key, value in payload.items():
        if len(collected) >= _WORKFLOW_EXECUTION_SUMMARY_MAX_SIDE_EFFECTS:
            break
        if not isinstance(key, str):
            continue
        key_text = key.strip()
        if not key_text:
            continue
        lowered_key = key_text.lower()
        if lowered_key in _WORKFLOW_EXECUTION_SUMMARY_IGNORED_KEYS:
            continue

        match = _WORKFLOW_MUTATION_ID_FIELD_PATTERN.match(lowered_key)
        if match:
            artefact_ids = _extract_workflow_execution_identifier_values(value)
            if artefact_ids:
                mutation_kind = _normalise_workflow_mutation_kind(match.group(1))
                artefact_type = _normalise_workflow_artefact_type(match.group(2))
                source_path = ".".join((*path, key_text))
                fingerprint = (
                    mutation_kind,
                    artefact_type,
                    source_path,
                    tuple(artefact_ids),
                )
                if fingerprint not in seen:
                    seen.add(fingerprint)
                    collected.append(
                        {
                            "mutation_kind": mutation_kind,
                            "artefact_type": artefact_type,
                            "source_key": key_text,
                            "source_path": source_path,
                            "artefact_count": len(artefact_ids),
                            "artefact_ids": artefact_ids,
                        }
                    )
            continue

        if isinstance(value, Mapping):
            _collect_workflow_durable_side_effects(
                value,
                path=(*path, key_text),
                depth=depth + 1,
                collected=collected,
                seen=seen,
            )
            continue

        if isinstance(value, Sequence) and not isinstance(
            value, (str, bytes, bytearray)
        ):
            for index, item in enumerate(value):
                if len(collected) >= _WORKFLOW_EXECUTION_SUMMARY_MAX_SIDE_EFFECTS:
                    break
                if not isinstance(item, Mapping):
                    continue
                _collect_workflow_durable_side_effects(
                    item,
                    path=(*path, f"{key_text}[{index}]"),
                    depth=depth + 1,
                    collected=collected,
                    seen=seen,
                )

    return collected


def _build_workflow_execution_summary(
    *,
    workflow_id: str,
    workflow_result: Any,
) -> dict[str, Any]:
    result_data = getattr(workflow_result, "data", None)
    workflow_data: Mapping[str, Any] = (
        result_data if isinstance(result_data, Mapping) else {}
    )

    step_envelopes = _workflow_execution_summary_mapping_list(
        workflow_data.get(WORKFLOW_STEP_RESULT_ENVELOPES_KEY)
    )
    success_count = 0
    failure_count = 0
    unknown_count = 0
    first_failing_state_id: str | None = None
    first_failing_action_id: str | None = None
    successful_action_ids: list[str] = []
    failed_action_ids: list[str] = []
    action_observations: list[dict[str, Any]] = []
    seen_successful_action_ids: set[str] = set()
    seen_failed_action_ids: set[str] = set()

    def _append_action_id_once(
        values: list[str],
        seen: set[str],
        action_id: Any,
    ) -> None:
        cleaned_action_id = _workflow_execution_summary_text(action_id)
        if (
            not cleaned_action_id
            or len(values) >= _WORKFLOW_EXECUTION_SUMMARY_MAX_ACTION_OBSERVATIONS
        ):
            return
        lowered = cleaned_action_id.lower()
        if lowered in seen:
            return
        seen.add(lowered)
        values.append(cleaned_action_id)

    for envelope in step_envelopes:
        action_outcome = _workflow_execution_summary_text(
            envelope.get("action_outcome")
        ) or _workflow_execution_summary_text(envelope.get("action_status"))
        action_id = _workflow_execution_summary_text(envelope.get("action_id"))
        state_id = _workflow_execution_summary_text(envelope.get("state_id"))
        lowered_outcome = (action_outcome or "").lower()
        if lowered_outcome == "success":
            success_count += 1
            _append_action_id_once(
                successful_action_ids,
                seen_successful_action_ids,
                action_id,
            )
        elif lowered_outcome in {"failed", "failure"}:
            failure_count += 1
            if first_failing_state_id is None:
                first_failing_state_id = _workflow_execution_summary_text(
                    envelope.get("state_id")
                )
            if first_failing_action_id is None:
                first_failing_action_id = _workflow_execution_summary_text(
                    envelope.get("action_id")
                )
            _append_action_id_once(
                failed_action_ids,
                seen_failed_action_ids,
                action_id,
            )
        else:
            unknown_count += 1
        if (
            action_id
            and lowered_outcome in {"success", "failed", "failure"}
            and len(action_observations)
            < _WORKFLOW_EXECUTION_SUMMARY_MAX_ACTION_OBSERVATIONS
        ):
            action_observations.append(
                {
                    "action_id": action_id,
                    "state_id": state_id,
                    "action_status": (
                        "success" if lowered_outcome == "success" else "failed"
                    ),
                    "outcome": (
                        "success" if lowered_outcome == "success" else "failure"
                    ),
                }
            )

    launch_resolution = workflow_data.get("workflow_launch_input_resolution")
    if isinstance(launch_resolution, Mapping):
        if first_failing_state_id is None:
            first_failing_state_id = _workflow_execution_summary_text(
                launch_resolution.get("failing_state_id")
            )
        if first_failing_action_id is None:
            first_failing_action_id = _workflow_execution_summary_text(
                launch_resolution.get("failing_action_id")
            )

    terminal_effect_events = _workflow_execution_summary_mapping_list(
        workflow_data.get(WORKFLOW_TERMINAL_EFFECT_EVENTS_KEY)
    )
    terminal_effects: list[dict[str, Any]] = []
    for event in terminal_effect_events[
        :_WORKFLOW_EXECUTION_SUMMARY_MAX_TERMINAL_EFFECTS
    ]:
        terminal_effects.append(
            {
                "state_id": _workflow_execution_summary_text(event.get("state_id")),
                "symbol": _workflow_execution_summary_text(event.get("symbol")),
                "alias": _workflow_execution_summary_text(event.get("alias")),
                "applied": bool(event.get("applied")),
            }
        )

    runtime_event_count = len(
        _workflow_execution_summary_mapping_list(
            workflow_data.get(WORKFLOW_RUNTIME_EVENTS_KEY)
        )
    )
    durable_side_effects = _collect_workflow_durable_side_effects(workflow_data)
    durable_side_effect_count = sum(
        int(entry.get("artefact_count") or 0) for entry in durable_side_effects
    )

    final_state = _workflow_execution_summary_text(
        getattr(workflow_result, "final_state", None)
    )
    reported_completed = bool(getattr(workflow_result, "completed", False))
    effective_completed = _workflow_result_effective_completed(workflow_result)
    terminal_status = _derive_workflow_terminal_status(workflow_result)
    completion_gate_summary = _workflow_completion_gate_summary(workflow_result)
    terminal_success_contract = _workflow_terminal_success_contract_from_result(
        workflow_result
    )
    terminal_success_evaluation = _workflow_terminal_success_evaluation_from_result(
        workflow_result
    )
    workflow_required_effects_contract = (
        _workflow_required_effects_contract_from_result(workflow_result)
    )
    workflow_required_effects_contract_source = (
        _workflow_required_effects_contract_source_from_result(workflow_result)
    )
    workflow_required_effects_required_tools = _workflow_required_tools_from_contract(
        workflow_required_effects_contract
    )

    summary: dict[str, Any] = {
        "schema_version": _WORKFLOW_EXECUTION_SUMMARY_SCHEMA_VERSION,
        "workflow_id": workflow_id,
        # `completed` is the verdict callers should trust; preserve the raw executor
        # flag separately because some workflows historically reported `completed=True`
        # even when their terminal state or error made the outcome failure-like.
        "completed": effective_completed,
        "effective_completed": effective_completed,
        "reported_completed": reported_completed,
        "terminal_status": terminal_status,
        "final_state": final_state,
        "step_result_envelope_count": len(step_envelopes),
        "action_started_count": len(step_envelopes),
        "action_completed_count": len(step_envelopes),
        "action_success_count": success_count,
        "action_failure_count": failure_count,
        "action_unknown_count": unknown_count,
        "successful_action_ids": successful_action_ids,
        "failed_action_ids": failed_action_ids,
        "action_observations": action_observations,
        "first_failing_state_id": first_failing_state_id,
        "first_failing_action_id": first_failing_action_id,
        "runtime_event_count": runtime_event_count,
        "terminal_effect_count": len(terminal_effect_events),
        "terminal_effects": terminal_effects,
        "durable_side_effect_count": durable_side_effect_count,
        "durable_side_effects": durable_side_effects,
    }
    if isinstance(completion_gate_summary, Mapping):
        summary["completion_gate_safe_to_claim_completion"] = bool(
            completion_gate_summary.get("safe_to_claim_completion", False)
        )
        summary["completion_gate_blocking_reason_codes"] = list(
            completion_gate_summary.get("blocking_reason_codes") or []
        )
    if isinstance(terminal_success_contract, Mapping):
        summary["terminal_success_contract"] = dict(terminal_success_contract)
    if isinstance(terminal_success_evaluation, Mapping):
        summary["terminal_success_evaluation"] = dict(terminal_success_evaluation)
    if isinstance(workflow_required_effects_contract, Mapping):
        summary["workflow_required_effects_contract_id"] = (
            _workflow_execution_summary_text(
                workflow_required_effects_contract.get("contract_id")
            )
        )
        summary["workflow_required_effects_declared_count"] = len(
            workflow_required_effects_contract.get("required_effects") or []
        )
        summary["workflow_required_effects_required_tools"] = list(
            workflow_required_effects_required_tools
        )
        summary["workflow_required_effects_required_tool_count"] = len(
            workflow_required_effects_required_tools
        )
        if workflow_required_effects_contract_source:
            summary["workflow_required_effects_contract_source"] = (
                workflow_required_effects_contract_source
            )
    return summary


def _build_workflow_execution_aux_entry(
    *,
    workflow_id: str,
    workflow_result: Any,
) -> dict[str, Any]:
    result_data = getattr(workflow_result, "data", None)
    execution_summary = (
        result_data.get("workflow_execution_summary")
        if isinstance(result_data, Mapping)
        else None
    )
    if not isinstance(execution_summary, Mapping):
        execution_summary = _build_workflow_execution_summary(
            workflow_id=workflow_id,
            workflow_result=workflow_result,
        )

    payload = {
        "type": "workflow_execution",
        "workflow_id": workflow_id,
        "final_state": _workflow_execution_summary_text(
            getattr(workflow_result, "final_state", None)
        ),
        "completed": _workflow_result_effective_completed(workflow_result),
        "execution_summary": dict(execution_summary),
    }
    result_snapshot = _build_workflow_execution_aux_result_snapshot(workflow_result)
    if isinstance(result_snapshot, Mapping):
        payload["result_snapshot"] = dict(result_snapshot)
    return payload


def _build_awaited_workflow_execute_aux_entry(
    *,
    tool_payload: Mapping[str, Any],
    tool_result_payload: Any,
    parent_data: Mapping[str, Any],
    user_namespace: str | None,
    instance_loader: Callable[[str], Any] | None = None,
) -> dict[str, Any]:
    """Project exact awaited child authority into the parent TER, fail closed."""

    return _build_awaited_workflow_execute_aux_entry_support(
        tool_payload=tool_payload,
        tool_result_payload=tool_result_payload,
        parent_data=parent_data,
        user_namespace=user_namespace,
        aux_entry_builder=_build_workflow_execution_aux_entry,
        instance_loader=instance_loader,
    )


def _derive_workflow_selection_rationale(
    *,
    selected_workflow_id: str | None,
    selector_verdict: str | None,
    selector_source: str | None,
    candidate_workflow_ids: Sequence[str],
    explicit_reasoning: str | None = None,
) -> str:
    """Return a stable machine-readable workflow-selection rationale code."""

    explicit = str(explicit_reasoning or "").strip()
    source = (selector_source or "default").strip().lower() or "default"
    selected = (selected_workflow_id or "").strip()
    verdict = (selector_verdict or "").strip()
    candidate_set = {
        str(item).strip().lower()
        for item in candidate_workflow_ids
        if isinstance(item, str) and str(item).strip()
    }

    if source == "selector_override":
        if explicit:
            return f"selector_override:{explicit}"
        if verdict:
            return f"selector_override_verdict:{verdict}"
        return "selector_override"
    if source == "selector":
        if selected and selected.lower() in candidate_set:
            return "selector_selected_discovered_candidate"
        if verdict:
            return f"selector_verdict:{verdict}"
        return "selector_route_without_explicit_verdict"
    if source == "presenter_mode":
        return "presenter_mode_route"
    if source == "default":
        if explicit:
            return f"default_reason:{explicit}"
        return "default_routing_fallback"
    if explicit:
        return f"routing_source:{source}:{explicit}"
    return f"routing_source:{source}"


def _normalise_selector_candidate_role(candidate: Mapping[str, Any]) -> str | None:
    raw_role = candidate.get("routing_profile_role")
    if isinstance(raw_role, str) and raw_role.strip():
        return raw_role.strip().lower()
    routing_profile = candidate.get("routing_profile")
    if isinstance(routing_profile, Mapping):
        nested_role = routing_profile.get("role")
        if isinstance(nested_role, str) and nested_role.strip():
            return nested_role.strip().lower()
    return None


def _workflow_execute_required(required_tools: Sequence[str] | None) -> bool:
    return any(
        isinstance(tool_name, str) and tool_name.strip().lower() == "workflow_execute"
        for tool_name in (required_tools or ())
    )


def _eligible_discovered_workflow_execute_candidates(
    discovered_matches: Sequence[Mapping[str, Any]] | None,
) -> list[dict[str, Any]]:
    """Return discovered workflows safe to use as explicit workflow_execute targets."""

    candidates: list[dict[str, Any]] = []
    for candidate in discovered_matches or ():
        if not isinstance(candidate, Mapping):
            continue
        concept_id = str(candidate.get("concept_id") or "").strip()
        if not concept_id or concept_id in _SELECTOR_GENERIC_WORKFLOW_IDS:
            continue
        if candidate.get("routing_eligible") is False:
            continue
        if candidate.get("is_executable") is False:
            continue
        if candidate.get("is_policy_safe") is False:
            continue
        if candidate.get("turn_launchable") is False:
            continue
        role = _normalise_selector_candidate_role(candidate)
        if role not in {None, "", "execution", "authoring"}:
            continue
        candidates.append(
            {
                "workflow_id": concept_id,
                "name": str(candidate.get("name") or "").strip() or concept_id,
                "role": role or "execution",
            }
        )
    return candidates


def _build_workflow_execute_candidate_review_payload(
    *,
    selected_workflow_id: str | None,
    required_tools: Sequence[str] | None,
    discovered_matches: Sequence[Mapping[str, Any]] | None,
) -> dict[str, Any] | None:
    """Describe whether a generic route can recover required workflow execution."""

    selected_workflow_id_text = (
        str(selected_workflow_id).strip()
        if isinstance(selected_workflow_id, str) and str(selected_workflow_id).strip()
        else None
    )
    if selected_workflow_id_text not in _SELECTOR_GENERIC_WORKFLOW_IDS:
        return None
    if not _workflow_execute_required(required_tools):
        return None

    candidates = _eligible_discovered_workflow_execute_candidates(discovered_matches)
    if not candidates:
        return None

    status = "single_candidate" if len(candidates) == 1 else "ambiguous_candidates"
    return {
        "status": status,
        "selected_workflow_id": selected_workflow_id_text,
        "required_tools": [
            tool_name
            for tool_name in (required_tools or ())
            if isinstance(tool_name, str) and tool_name.strip()
        ],
        "eligible_workflow_execute_candidate_count": len(candidates),
        "eligible_workflow_execute_candidate_ids": [
            candidate["workflow_id"] for candidate in candidates
        ],
        "eligible_workflow_execute_candidates": candidates,
    }


