class AuthoritativePromptUnavailableError(RuntimeError):
    """Raised when a Vontology-governed prompt required for orchestration is unavailable."""


class InternalMCPChatOrchestrator:
    """Runtime support for explicit workflows that call internal MCP tools."""

    _ACTION_FIELD = "action"
    _CALL_ACTION = "call_tool"
    _TOOL_FIELD = "tool"
    _PAYLOAD_FIELD = "payload"
    _MISSING_TOOL_CALL_ACTION_ID = "#V#detect_missing_tool_call_action"
    _MISSING_TOOL_CALL_RETRY_ACTION_ID = "#V#retry_missing_tool_call_action"
    _SPECIALISED_PREFLIGHT_SOURCE_PATH = "specialised_preflight_workflow"
    _SPECIALISED_PREFLIGHT_MAX_SUGGESTIONS = 6
    _TOOL_CALL_REPAIR_PROMPTS = ("#V#tool_call_repair_prompt",)
    _WORKFLOW_STEP_STRUCTURED_OUTPUT_BACKFILL_PROMPTS = (
        "#V#workflow_step_structured_output_backfill_prompt",
    )
    _TODO_REFRESH_EXTRACT_TASKS_PROMPTS = ("#V#todo_refresh_extract_tasks_prompt",)
    _TODO_REFRESH_EXTRACT_TASKS_SYSTEM_PROMPTS = (
        "#V#todo_refresh_extract_tasks_system_prompt",
    )
    _TODO_REFRESH_PRIORITISE_PROMPTS = ("#V#todo_refresh_prioritise_prompt",)
    _TODO_REFRESH_PRIORITISE_SYSTEM_PROMPTS = (
        "#V#todo_refresh_prioritise_system_prompt",
    )

    PHASE_TOOL_PLAN = "tool_plan"
    PHASE_TOOL_EXECUTE = "tool_execute"
    _MISSING_TOOL_RETRY_PROMPTS = ("#V#missing_tool_call_retry_prompt",)
    _PROMPT_EXPLICIT_TOOL_CALL_PATTERN = re.compile(
        r"\b(?:call|use|run|invoke|execute)\s+`?([a-z_][a-z0-9_]*(?:_[a-z0-9_]+)+)`?\b",
        flags=re.IGNORECASE,
    )
    _AGENT_TEST_LOCAL_RELATION_TOOLS: tuple[str, ...] = (
        "get_text_relations_summary",
        "get_text_relations",
    )
    # NOTE: Concept verification intent (verify/check/confirm/exist) is now
    # workflow/LLM-owned — the selector and LLM decide when to call
    # concept_exists or fetch_concept.  The former Python regex pattern
    # (_PROMPT_CONCEPT_VERIFICATION_HINT_PATTERN) was removed as part of
    # the JVNAUTOSCI-1613 authority refactor (Phase 9).
    # NOTE: Scholarly representation intent (represent the paper / paper
    # representation) and paper/representation intent patterns are now
    # workflow/LLM-owned — the selector and LLM decide when scholarly
    # representation is needed. The former Python regex patterns
    # (_PROMPT_SCHOLARLY_REPRESENTATION_INTENT_PATTERN,
    # _PROMPT_PAPER_INTENT_PATTERN, _PROMPT_REPRESENTATION_INTENT_PATTERN)
    # were removed as part of the JVNAUTOSCI-1613 authority refactor
    # (Phase 9).
    _FILE_COPY_CONCEPT_ID_PATTERN = re.compile(
        r"^#V#[A-Za-z0-9][A-Za-z0-9._-]*file_copy[A-Za-z0-9._-]*$",
        flags=re.IGNORECASE,
    )
    # Structured tool-call candidate baseline and provider constraints.
    #
    # Keep this baseline minimal: it should preserve core recovery and lookup
    # pathways without reintroducing the full uncapped catalogue when filtering
    # yields no candidates.
    _STRUCTURED_TOOL_SAFE_BASELINE: tuple[str, ...] = (
        "search_concepts",
        "fetch_concept",
        "concept_exists",
        "search_knowledge_base",
        "search_web",
        "qna_search",
        "extract_url",
        "resilient_extract_url",
    )
    _STRUCTURED_TOOL_PROVIDER_LIMITS: Mapping[str, int] = {
        # OpenAI enforces a hard tool-list ceiling; keep this authoritative.
        "openai": 128,
        # Gemini limits may vary by model. We keep a conservative default.
        "gemini": 128,
    }
    _STRUCTURED_TOOL_PLANNER_SHORTLIST_CAP = 16
    # Deterministic concept-id fields for write-category tools.
    #
    # We normalise these before execution so writable operations are robust to
    # close-but-wrong guessed IDs (for example #V#gill_dobbie vs
    # #V#gillian_dobbie) without relying on non-deterministic LLM retries.
    _WRITE_TOOL_CONCEPT_ID_FIELDS: Mapping[str, tuple[str, ...]] = {
        "add_relationship": ("source_id", "predicate", "target"),
        "remove_relationship": ("source_id", "predicate", "target"),
        "add_names": ("concept_id",),
        "update_concept": ("concept_id",),
        "delete_concept": ("concept_id",),
        "merge_concepts": ("source_id", "target_id"),
        "upsert_text_relation": ("concept_id",),
        "upsert_singleton_text_relation": ("concept_id",),
        "delete_text_relation": ("concept_id",),
        "update_text_relation": ("concept_id",),
        "create_concepts": ("parent_id",),
    }
    _ADD_RELATIONSHIP_MISSING_REFERENCE_FIELDS: Mapping[str, tuple[str, ...]] = {
        # Target recovery still allows fallback attempts on source/predicate
        # because upstream payloads may surface a target-not-found envelope even
        # when a neighbouring field is the real drifted identifier.
        "target_not_found": ("target", "source_id", "predicate"),
        "target_concept_not_found": ("target",),
        "source_not_found": ("source_id",),
        "source_concept_not_found": ("source_id",),
        "predicate_concept_not_found": ("predicate",),
    }

    def __init__(
        self,
        *,
        gateway: InternalMCPGateway,
        logger: logging.Logger | None = None,
        max_tool_invocations: int = INTERNAL_MCP_MAX_TOOL_INVOCATIONS_DEFAULT,
        tool_batch_cap: int = INTERNAL_MCP_TOOL_BATCH_CAP_DEFAULT,
        default_gmail_profile: str | None = None,
        max_context_chars: int | None = None,
        max_tool_result_chars: int | None = None,
        max_tool_result_field_chars: int | None = None,
    ) -> None:
        self._gateway = gateway
        self._logger = logger or logging.getLogger(__name__)
        self._max_tool_invocations = max(
            INTERNAL_MCP_MAX_TOOL_INVOCATIONS_MIN,
            min(INTERNAL_MCP_MAX_TOOL_INVOCATIONS_MAX, int(max_tool_invocations)),
        )
        self._tool_batch_cap = max(
            INTERNAL_MCP_TOOL_BATCH_CAP_MIN,
            min(INTERNAL_MCP_TOOL_BATCH_CAP_MAX, int(tool_batch_cap)),
        )
        # Per-turn retry budget for missing-tool-call recovery.
        # Keep this bounded to avoid retry thrashing when multiple malformed
        # tool-call responses occur in the same turn.
        self._max_missing_tool_call_retries_per_turn = self._coerce_int(
            None,
            env_var="VON_MCP_MAX_MISSING_TOOL_CALL_RETRIES_PER_TURN",
            default=2,
            min_value=0,
            max_value=20,
        )
        self._default_gmail_profile = default_gmail_profile

        # Vontology-backed missing-tool-call detector (lazy loaded)
        self._missing_tool_call_detector: Optional[_MissingToolCallDetectorSpec] = None
        self._missing_tool_call_detector_loaded: bool = False

        # Provider reachability probe cache used to throttle repeated failing probes.
        self._provider_probe_cache: dict[str, dict[str, Any]] = {}
        self._provider_probe_cache_max_entries = self._coerce_int(
            None,
            env_var="VON_INTERNAL_MCP_PROVIDER_PROBE_CACHE_MAX_ENTRIES",
            default=64,
            min_value=8,
            max_value=512,
        )
        self._provider_probe_cooldown_seconds = self._coerce_int(
            None,
            env_var="VON_INTERNAL_MCP_PROVIDER_PROBE_COOLDOWN_SEC",
            default=20,
            min_value=0,
            max_value=600,
        )

        # Workflow model policy cache (single policy instance).
        self._workflow_model_policy_cache: dict[str, Any] = {}
        self._workflow_model_policy_cache_ttl_seconds = self._coerce_int(
            None,
            env_var="VON_WORKFLOW_MODEL_POLICY_CACHE_SECONDS",
            default=120,
            min_value=10,
            max_value=3600,
        )

        # Guardrails against context/tool-result bloat.
        # These are expressed in characters (not tokens) to avoid model-specific tokenisers.
        self._max_context_chars = self._coerce_int(
            max_context_chars,
            env_var="VON_MCP_MAX_CONTEXT_CHARS",
            default=120_000,
            min_value=4_000,
            max_value=2_000_000,
        )
        self._max_tool_result_chars = self._coerce_int(
            max_tool_result_chars,
            env_var="VON_MCP_MAX_TOOL_RESULT_CHARS",
            default=20_000,
            min_value=2_000,
            max_value=1_000_000,
        )
        self._max_tool_result_field_chars = self._coerce_int(
            max_tool_result_field_chars,
            env_var="VON_MCP_MAX_TOOL_RESULT_FIELD_CHARS",
            default=8_000,
            min_value=1_000,
            max_value=200_000,
        )
        self._follow_up_context_chars = self._coerce_int(
            None,
            env_var="VON_MCP_FOLLOW_UP_CONTEXT_CHARS",
            default=40_000,
            min_value=4_000,
            max_value=200_000,
        )
        # Structured tool-calling candidate caps.
        self._structured_tool_provider_default_limit = self._coerce_int(
            None,
            env_var="VON_MCP_STRUCTURED_TOOL_PROVIDER_LIMIT_DEFAULT",
            default=128,
            min_value=16,
            max_value=512,
        )
        self._structured_tool_cap_headroom = self._coerce_int(
            None,
            env_var="VON_MCP_STRUCTURED_TOOL_CAP_HEADROOM",
            default=8,
            min_value=0,
            max_value=64,
        )
        # Optional hard override. 0 disables override and uses provider-limit headroom.
        self._structured_tool_candidate_cap_override = self._coerce_int(
            None,
            env_var="VON_MCP_STRUCTURED_TOOL_CANDIDATE_CAP",
            default=0,
            min_value=0,
            max_value=512,
        )

        self._prompt_templates = PromptTemplateService()
        # Unified registries: single source of truth for both conversation-turn
        # and durable workflows/actions. Reuse the shared read-only workflow
        # registry here so request-time orchestrator construction does not
        # trigger the heavyweight authoritative parity rebuild path.
        # See JVNAUTOSCI-922 Phase 1 and JVNAUTOSCI-1566.
        self._workflow_registry = get_shared_workflow_registry_read_only(
            defer_parity_work=True
        )
        self._action_registry = self._build_action_registry()
        self._workflow_executor = WorkflowExecutor(
            registry=self._action_registry, max_transitions=50
        )
        # Dead-candidate cache shared by explicit workflow LLM steps within a
        # request thread. Callers may install the parent workflow's cache on
        # this thread-local before invoking ``_run_llm_with_fallbacks``.
        self._turn_model_failures_local = threading.local()

    def configure_execution_caps(
        self,
        *,
        max_tool_invocations: int | None = None,
        tool_batch_cap: int | None = None,
        max_missing_tool_call_retries_per_turn: int | None = None,
    ) -> None:
        """Update execution caps in-place.

        This is intentionally lightweight so callers (e.g., /von/generate) can
        apply persisted Settings without requiring a server restart.
        """

        if max_tool_invocations is not None:
            try:
                coerced = int(max_tool_invocations)
            except Exception:
                coerced = self._max_tool_invocations
            # Safety clamp.
            self._max_tool_invocations = max(
                INTERNAL_MCP_MAX_TOOL_INVOCATIONS_MIN,
                min(INTERNAL_MCP_MAX_TOOL_INVOCATIONS_MAX, coerced),
            )

        if tool_batch_cap is not None:
            try:
                coerced = int(tool_batch_cap)
            except Exception:
                coerced = self._tool_batch_cap
            self._tool_batch_cap = max(
                INTERNAL_MCP_TOOL_BATCH_CAP_MIN,
                min(INTERNAL_MCP_TOOL_BATCH_CAP_MAX, coerced),
            )

        if max_missing_tool_call_retries_per_turn is not None:
            self._max_missing_tool_call_retries_per_turn = (
                self._coerce_non_negative_int(
                    max_missing_tool_call_retries_per_turn,
                    default=self._max_missing_tool_call_retries_per_turn,
                    max_value=20,
                )
            )

    def _ensure_workflow_runtime_surfaces(self) -> None:
        """Materialise workflow runtime helpers for partially initialised instances.

        Some unit tests patch ``__init__`` to construct a minimal orchestrator with
        only a gateway and logger. Keep workflow execution entry points resilient by
        lazily restoring the shared workflow registry and executor when those tests
        invoke workflow-backed tool actions directly.
        """

        if getattr(self, "_workflow_registry", None) is None:
            self._workflow_registry = get_shared_workflow_registry_read_only(
                defer_parity_work=True
            )
        if getattr(self, "_action_registry", None) is None:
            self._action_registry = self._build_action_registry()
        if getattr(self, "_workflow_executor", None) is None:
            self._workflow_executor = WorkflowExecutor(
                registry=self._action_registry,
                max_transitions=50,
            )
        if not hasattr(self, "_default_gmail_profile"):
            self._default_gmail_profile = None
        if not hasattr(self, "_max_tool_invocations"):
            self._max_tool_invocations = 0
        if not hasattr(self, "_max_tool_result_chars"):
            self._max_tool_result_chars = 20_000
        if not hasattr(self, "_max_tool_result_field_chars"):
            self._max_tool_result_field_chars = 8_000

    def _resolve_workflow_registration_and_definition(
        self,
        workflow_id: str | None,
        *,
        register_authoritative_fallback: bool = True,
        actor_user_id: str | None = None,
        actor_org_id: str | None = None,
    ) -> tuple[WorkflowRegistration | None, Any | None]:
        """Resolve a workflow definition from runtime registry or Vontology.

        Selector-time launchability checks and execution handoff both need the
        authoritative workflow definition even when a registry snapshot has
        been invalidated or rebuilt. Delegate to the shared runtime resolver so
        submission, durable workers, and orchestrator execution observe the
        same Vontology-backed support path.
        """

        self._ensure_workflow_runtime_surfaces()
        workflow_id_text = (
            str(workflow_id).strip()
            if isinstance(workflow_id, str) and str(workflow_id).strip()
            else None
        )
        if not workflow_id_text:
            return None, None

        resolution = resolve_workflow_definition_from_authority(
            workflow_id_text,
            registry=self._workflow_registry,
            use_current_shared_registry=True,
            promote_to_registry=(
                self._workflow_registry if register_authoritative_fallback else None
            ),
            register_authoritative_fallback=register_authoritative_fallback,
            actor_user_id=actor_user_id,
            actor_org_id=actor_org_id,
        )
        if resolution.registry is not None:
            self._workflow_registry = resolution.registry
        return resolution.registration, resolution.definition

    def get_execution_caps(self) -> dict[str, int]:
        return {
            "max_tool_invocations": int(self._max_tool_invocations),
            "tool_batch_cap": int(self._tool_batch_cap),
            "max_missing_tool_call_retries_per_turn": int(
                self._max_missing_tool_call_retries_per_turn
            ),
        }

    def _resolve_environment_max_tool_invocations(self, env: Any) -> int:
        """Resolve the per-turn tool cap without reviving retired fallback values.

        A configured ``0`` must remain ``0`` so callers can intentionally disable
        tool execution. Falling back with ``or 8`` reintroduced the legacy cap and
        made the runtime disagree with Settings/JVNAUTOSCI-1392 diagnostics.
        """

        raw_value = getattr(env, "max_tool_invocations", None)
        if raw_value is None:
            return int(self._max_tool_invocations)
        try:
            return max(
                INTERNAL_MCP_MAX_TOOL_INVOCATIONS_MIN,
                min(INTERNAL_MCP_MAX_TOOL_INVOCATIONS_MAX, int(raw_value)),
            )
        except Exception:
            return int(self._max_tool_invocations)

    @staticmethod
    def _ensure_tool_limit_notice(
        response_text: str,
        *,
        tool_calls_done: int,
        tool_calls_cap: int,
        pending_follow_up_tool_call_count: int | None = None,
    ) -> str:
        """Ensure cap exhaustion is visible even if the finaliser omits it."""

        clean_response = response_text.strip()
        if "internal_mcp_max_tool_invocations" in clean_response:
            return clean_response
        pending_fragment = ""
        if (
            isinstance(pending_follow_up_tool_call_count, int)
            and pending_follow_up_tool_call_count > 0
        ):
            pending_fragment = (
                f" {pending_follow_up_tool_call_count} pending required or follow-up "
                "tool call(s) were blocked by that setting."
            )
        notice = (
            "Tool-use limit reached: this turn reached "
            f"`internal_mcp_max_tool_invocations={int(tool_calls_cap)}` after "
            f"{int(tool_calls_done)} tool call(s)."
            f"{pending_fragment} Raise that setting or narrow the request to allow "
            "more tool calls."
        )
        if not clean_response:
            return notice
        return f"{notice}\n\n{clean_response}"

    @staticmethod
    def _build_tool_progress_argument_summary(
        payload: Mapping[str, Any] | None,
    ) -> dict[str, Any]:
        if not isinstance(payload, Mapping):
            return {}

        allowed_keys = (
            "concept_id",
            "instance_of",
            "source_id",
            "target_id",
            "predicate_filter",
            "argument_index",
            "relation_kind",
            "limit",
            "offset",
            "sort_by",
            "uncertainty_mode",
            "include_uncertain",
            "direct_instances_only",
        )
        summary: dict[str, Any] = {}
        for key in allowed_keys:
            if key not in payload:
                continue
            value = payload.get(key)
            if isinstance(value, str):
                cleaned = value.strip()
                if cleaned:
                    summary[key] = cleaned[:200]
            elif isinstance(value, bool):
                summary[key] = value
            elif isinstance(value, int):
                summary[key] = value
            elif isinstance(value, Sequence) and not isinstance(
                value, (str, bytes, bytearray)
            ):
                cleaned_values = [
                    str(item).strip()[:200]
                    for item in value
                    if isinstance(item, (str, int, float)) and str(item).strip()
                ]
                if cleaned_values:
                    summary[key] = cleaned_values[:5]
        if "concept_id" in summary:
            summary.setdefault("target_concept_id", summary["concept_id"])
        if "instance_of" in summary:
            summary.setdefault("target_type_id", summary["instance_of"])
        return summary

    @staticmethod
    def _coerce_int(
        value: int | None,
        *,
        env_var: str,
        default: int,
        min_value: int,
        max_value: int,
    ) -> int:
        if value is None:
            raw = os.environ.get(env_var)
            if raw is not None:
                try:
                    value = int(raw)
                except Exception:
                    value = None
        if value is None:
            value = default
        return max(min_value, min(max_value, int(value)))

    @staticmethod
    def _coerce_non_negative_int(
        value: Any,
        *,
        default: int = 0,
        max_value: int | None = None,
    ) -> int:
        """Coerce arbitrary numeric-like input into a bounded non-negative int."""
        try:
            coerced = int(value)
        except Exception:
            coerced = int(default)
        coerced = max(0, coerced)
        if max_value is not None:
            coerced = min(int(max_value), coerced)
        return coerced

    def _build_action_registry(self) -> ActionRegistry:
        """Build a unified action registry for all workflow execution.

        Starts from the shared durable action registry (rag_sync,
        considerations) and adds conversation-turn handlers (narration,
        missing-tool-call, write-policy, todo-refresh). The result is a single
        registry usable by both WorkflowExecutor and DurableWorkflowExecutor.

        Copy the durable registry into a fresh ActionRegistry so each
        orchestrator instance can attach self-bound handlers and fallback
        routing without mutating the shared durable runtime cache.

        See JVNAUTOSCI-922 Phase 1.1 — unified ActionRegistry.
        """
        # Start with durable handlers as the base.
        registry = ActionRegistry()
        registry.merge(get_shared_durable_action_registry())

        # Conversation-turn handlers — these reference ``self`` methods.
        registry.register(
            ActionSpec(
                action_id="missing_tool_call.assess",
                handler=self._action_missing_tool_call_assess,
                description="Classify and log missing tool-call verdicts.",
                concept_id=self._MISSING_TOOL_CALL_ACTION_ID,
            )
        )
        registry.register(
            ActionSpec(
                action_id="missing_tool_call.retry",
                handler=self._action_missing_tool_call_retry,
                description="Run retry prompt to elicit tool-call JSON.",
                concept_id=self._MISSING_TOOL_CALL_RETRY_ACTION_ID,
            )
        )
        registry.register(
            ActionSpec(
                action_id="narration.classify",
                handler=self._action_narration_classify,
                description="Determine whether narration should run.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="narration.select_prompts",
                handler=self._action_narration_select_prompts,
                description="Resolve narration prompt fragments from Vontology.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="narration.render",
                handler=self._action_narration_render,
                description="Generate narration text via LLM.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="narration.emit_audio",
                handler=self._action_narration_emit_audio,
                description="Attach narration output to presenter channels.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="buttonify.assess_input",
                handler=self._action_buttonify_assess_input,
                description="Assess whether buttonify output transformation should run.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="buttonify.select_prompt",
                handler=self._action_buttonify_select_prompt,
                description="Resolve buttonify prompt from Vontology.",
            )
        )
        # Todo-refresh workflow actions (JVNAUTOSCI-922 Phase 2.3).
        registry.register(
            ActionSpec(
                action_id="todo_refresh.check_cache",
                handler=self._action_todo_refresh_check_cache,
                description="Check task cache freshness; skip Gmail if recent.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="todo_refresh.fetch_gmail",
                handler=self._action_todo_refresh_fetch_gmail,
                description="Fetch recent Gmail messages via MCP gateway.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="todo_refresh.extract_tasks",
                handler=self._action_todo_refresh_extract_tasks,
                description="LLM extraction of actionable tasks from emails.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="todo_refresh.prioritise",
                handler=self._action_todo_refresh_prioritise,
                description="Assign priority to extracted tasks via LLM.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="todo_refresh.summarise",
                handler=self._action_todo_refresh_summarise,
                description="Persist tasks and produce human-readable summary.",
            )
        )

        registry.register(
            ActionSpec(
                action_id="write_policy.decide",
                handler=self._action_write_policy_decide,
                description="Decide which write-category tools are allowed for this prompt.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="preflight.specialised_suggest",
                handler=self._action_preflight_specialised_suggest,
                description=(
                    "Specialised fallback concept suggestion stage for sparse "
                    "ontology preflight contexts."
                ),
            )
        )
        # Tool-calling workflow actions (JVNAUTOSCI-922 Phase 2).
        # Real handlers that wrap the procedural tool-calling logic;
        # driven by #V#tool_calling_workflow state machine.
        registry.register(
            ActionSpec(
                action_id="tool_calling.preflight_requirements",
                handler=self._action_tool_calling_preflight_requirements,
                description="Derive prompt requirements before tool planning.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="tool_calling.respond",
                handler=self._action_tool_calling_respond,
                description=(
                    "Composite tool-calling contract action for authoritative "
                    "workflow steps that expect a single response phase."
                ),
            )
        )
        registry.register(
            ActionSpec(
                action_id="tool_calling.plan",
                handler=self._action_tool_calling_plan,
                description="Initial LLM call + missing-tool-call recovery.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="tool_calling.validate",
                handler=self._action_tool_calling_validate,
                description="Preflight validation, coercion, and repair.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="tool_calling.repair",
                handler=self._action_tool_calling_repair,
                description="Run one Vontology-prompted repair attempt for invalid tool calls.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="tool_calling.execute",
                handler=self._action_tool_calling_execute,
                description="Execute tool-call batch against MCP gateway.",
            )
        )
        registry.register(
            ActionSpec(
                action_id="tool_calling.backfill",
                handler=self._action_tool_calling_backfill,
                description="Summariser LLM call; detect chained tool calls.",
            )
        )
        override_registry = ActionRegistry()
        override_registry.register(
            ActionSpec(
                action_id="turn_execution.critic",
                handler=self._action_turn_execution_critic,
                description="Evaluate required effects and postcondition checks for the turn.",
            )
        )
        registry.merge(override_registry, overwrite=True)
        # The shared durable registry's subworkflow handler closes over the
        # shared registry. Rebind it here so selected-workflow child execution
        # sees the orchestrator's tool-calling and turn-control action handlers.
        register_subworkflow_actions(
            registry,
            definition_loader=load_workflow_definition_from_vontology,
            overwrite=True,
        )

        # JVNAUTOSCI-922 Phase 3.1: Fallback handler for Vontology-defined
        # MCP tool actions.  Any action_id not explicitly registered is
        # routed through the MCP gateway via _action_mcp_tool_invoke.
        registry.set_fallback_handler(self._action_mcp_tool_invoke)
        return registry

    # -------------------------------------------------------------------
    # Generic MCP tool invocation action (Phase 3.1)
    # -------------------------------------------------------------------

    def _action_mcp_tool_invoke(self, request: Any) -> WorkflowActionResult:
        """Invoke an MCP tool by name via the gateway.

        JVNAUTOSCI-922 Phase 3.1: Generic fallback handler for
        Vontology-defined workflow steps whose ``invokes_action`` points
        to an MCP tool name rather than a registered Python handler.

        The ``action_id`` on the request is used as the MCP tool name.
        ``request.inputs`` (populated from the step's hasInputMap) are
        merged with defaults (namespace, gmail_profile) and passed as the
        gateway payload.

        Outputs on success:
            mcp_result (dict): The workflow-visible gateway payload; when a
                represented tool evidence projection exists, this is the
                compact projected payload rather than raw source-specific data.
            mcp_tool (str): The tool name that was invoked.
            mcp_duration_ms (float): Execution time in milliseconds.
            result (Any): Alias of mcp_result for condition evaluation.
        """
        self._ensure_workflow_runtime_surfaces()
        tool_name = request.action_id
        env = request.environment
        gateway = self._gateway

        if gateway is None or not gateway.enabled:
            return WorkflowActionResult(
                status="failed",
                error=f"gateway_unavailable_for:{tool_name}",
            )

        # Build payload from inputs + context overrides.
        payload: dict[str, Any] = dict(request.inputs) if request.inputs else {}

        # Apply standard defaults (namespace, gmail_profile, session_id).
        try:
            method_catalogue = gateway.describe_methods()
            schema = self._tool_schema_for_name(tool_name, method_catalogue)
        except Exception:
            method_catalogue = {}
            schema = None

        tool_category = ""
        method_definition = None
        if isinstance(method_catalogue, Mapping):
            tool_meta = method_catalogue.get(tool_name)
            if isinstance(tool_meta, Mapping):
                tool_category = str(tool_meta.get("category") or "").strip().lower()
        try:
            method_definition = gateway.get_method_definition(tool_name)
        except Exception:
            method_definition = None

        self._apply_payload_defaults(
            tool_name,
            payload,
            schema=schema,
            user_namespace=env.user_namespace,
            selected_gmail_profile=env.default_gmail_profile,
            conversation_session_id=request.data.get("conversation_session_id"),
            turn_id=request.data.get("turn_id"),
        )

        workflow_execution_policy_authorised = False
        if tool_category == "write":
            execution_side_effect_policy = (
                resolve_workflow_execution_side_effect_policy(
                    workflow_context=(
                        request.data if isinstance(request.data, Mapping) else None
                    ),
                    workflow_state_metadata=(
                        request.workflow_state_metadata
                        if isinstance(request.workflow_state_metadata, Mapping)
                        else None
                    ),
                )
            )
            if execution_side_effect_policy is not None:
                blocked_result = enforce_workflow_mcp_write_guardrails(
                    request=request,
                    resolved_tool_name=tool_name,
                    method_definition=method_definition,
                )
                if blocked_result is not None:
                    return blocked_result
                workflow_execution_policy_authorised = True

        if tool_category == "write" and not workflow_execution_policy_authorised:
            resolved_write_policy = self._resolve_allowed_write_tools(
                prompt=(
                    str(request.data.get("prompt") or "").strip()
                    if isinstance(request.data, Mapping)
                    else ""
                ),
                requested_write_tools=[tool_name],
                requested_write_payloads={tool_name: dict(payload)},
                recent_user_prompts=(
                    [
                        str(item).strip()
                        for item in (request.data.get("recent_user_prompts") or [])
                        if isinstance(item, str) and str(item).strip()
                    ]
                    if isinstance(request.data, Mapping)
                    else []
                ),
                llm_client=env.llm_client,
                model=env.model,
                user_namespace=env.user_namespace,
                auxiliary_system_prompt=env.auxiliary_system_prompt,
                trace=request.trace,
                conversation_session_id=request.data.get("conversation_session_id"),
                turn_id=request.data.get("turn_id"),
                aux_llm_calls=request.data.get("aux_llm_calls"),
                caller_workflow_id=request.workflow_id,
                caller_workflow_step_id=request.workflow_state_id,
                caller_workflow_step_metadata=request.workflow_state_metadata,
                turn_expected_outcome_contract_state=(
                    request.data.get("turn_expected_outcome_contract_state")
                    if isinstance(request.data, Mapping)
                    and isinstance(
                        request.data.get("turn_expected_outcome_contract_state"),
                        Mapping,
                    )
                    else None
                ),
                activated_conditional_required_tools=(
                    request.data.get("activated_conditional_required_tools")
                    if isinstance(request.data, Mapping)
                    and isinstance(
                        request.data.get("activated_conditional_required_tools"),
                        Sequence,
                    )
                    and not isinstance(
                        request.data.get("activated_conditional_required_tools"),
                        (str, bytes, bytearray),
                    )
                    else None
                ),
                guardrail_surface="workflow_action_fallback",
                guardrail_stage="workflow_action",
            )
            self._record_mutation_guardrail_events(
                events=resolved_write_policy.guardrail_events,
                context=(
                    request.data if isinstance(request.data, MutableMapping) else None
                ),
                aux_llm_calls=request.data.get("aux_llm_calls"),
            )
            write_override_reason = None
            if tool_name not in resolved_write_policy.allowed_tools:
                write_override_reason = self._resolve_write_guardrail_override_reason(
                    tool_name=tool_name,
                    payload=payload,
                    method_catalogue=method_catalogue,
                    blocked_reason=resolved_write_policy.blocked_reasons.get(tool_name),
                    workflow_id=request.workflow_id,
                    workflow_step_id=request.workflow_state_id,
                )
            if (
                tool_name not in resolved_write_policy.allowed_tools
                and not write_override_reason
            ):
                message = self._build_blocked_write_message(
                    tool_name=tool_name,
                    reason=resolved_write_policy.blocked_reasons.get(tool_name),
                    payload=payload,
                )
                return WorkflowActionResult(
                    status="failed",
                    error=message,
                    outputs={
                        "mutation_guardrail_blocked": True,
                        "write_policy_reason": resolved_write_policy.reason,
                        "write_policy_decision_basis": (
                            resolved_write_policy.decision_basis
                        ),
                        "write_policy_outcome": resolved_write_policy.outcome,
                        "write_policy_blocked_reason": (
                            resolved_write_policy.blocked_reasons.get(tool_name)
                        ),
                    },
                )

        try:
            result = gateway.invoke(tool_name, payload)
            try:
                from ...workflows.workflow_baseline_telemetry import (
                    record_generic_fallback_mcp_invocation,
                )

                record_generic_fallback_mcp_invocation(success=True)
            except Exception:
                pass
            if tool_category == "write" and isinstance(result.payload, Mapping):
                tool_surface_guardrail_event = self._build_tool_surface_guardrail_event(
                    tool_name=tool_name,
                    payload=cast(Mapping[str, Any], result.payload),
                    stage="workflow_action",
                    workflow_id=request.workflow_id,
                    workflow_step_id=request.workflow_state_id,
                    action_id=request.action_id,
                    conversation_session_id=request.data.get("conversation_session_id"),
                    turn_id=request.data.get("turn_id"),
                    effective_mutation_authority=(
                        resolved_write_policy.effective_mutation_authority
                        if "resolved_write_policy" in locals()
                        else None
                    ),
                    authority_sources=(
                        resolved_write_policy.authority_sources
                        if "resolved_write_policy" in locals()
                        else {}
                    ),
                )
                if isinstance(tool_surface_guardrail_event, Mapping):
                    self._record_mutation_guardrail_events(
                        events=(tool_surface_guardrail_event,),
                        context=(
                            request.data
                            if isinstance(request.data, MutableMapping)
                            else None
                        ),
                        aux_llm_calls=request.data.get("aux_llm_calls"),
                    )
            return workflow_action_result_from_mcp_payload(
                tool_name=tool_name,
                payload=result.payload,
                duration_ms=result.duration_ms,
                transport_metadata=(
                    result.telemetry_metadata()
                    if callable(getattr(result, "telemetry_metadata", None))
                    else None
                ),
            )
        except Exception as exc:
            try:
                from ...workflows.workflow_baseline_telemetry import (
                    record_generic_fallback_mcp_invocation,
                )

                record_generic_fallback_mcp_invocation(success=False)
            except Exception:
                pass
            self._logger.warning(
                "[mcp_orchestrator] Generic MCP invoke failed for %s: %s",
                tool_name,
                exc,
            )
            return WorkflowActionResult(
                status="failed",
                error=f"mcp_invoke_failed:{tool_name}:{exc}",
            )

    def _action_missing_tool_call_assess(self, request: Any) -> WorkflowActionResult:
        data = request.data
        aux_log = data.setdefault("aux_llm_calls", [])
        assessor = data.get("missing_tool_assessor")
        if not callable(assessor):
            return WorkflowActionResult(
                status="failed", error="missing_assessor_callable"
            )

        retry_attempts = self._coerce_non_negative_int(
            data.get("missing_tool_call_retry_attempts"),
            default=0,
            max_value=20,
        )
        retry_budget = self._coerce_non_negative_int(
            data.get("missing_tool_call_retry_budget"),
            default=self._max_missing_tool_call_retries_per_turn,
            max_value=20,
        )
        # Keep heuristic/classifier retry available for ordinary "I'll do it
        # now" tool promises as well as explicit prompt-requirement failures.
        allow_semantic_retry = True
        retries_remaining_before = max(0, retry_budget - retry_attempts)
        data["missing_tool_call_retry_attempts"] = retry_attempts
        data["missing_tool_call_retry_budget"] = retry_budget

        override_retry_reason_raw = data.get("missing_tool_call_retry_reason_override")
        override_retry_reason = (
            override_retry_reason_raw.strip()
            if isinstance(override_retry_reason_raw, str)
            else ""
        )
        if override_retry_reason:
            interpretation = data.get("interpretation")
            use_structured = bool(data.get("use_structured"))
            response_text = (
                data.get("response_text", "")
                if isinstance(data.get("response_text", ""), str)
                else str(data.get("response_text", ""))
            )
            is_json_action = (
                interpretation.is_json_action
                if (
                    not use_structured
                    and isinstance(interpretation, _ModelTurnInterpretation)
                )
                else self._is_json_action_response(response_text)
            )
            fenced_detected = (
                interpretation.fenced_tool_call_json
                if (
                    not use_structured
                    and isinstance(interpretation, _ModelTurnInterpretation)
                )
                else self._contains_fenced_tool_call_json(response_text)
            )
            assessment = _MissingToolCallAssessment(
                path="structured" if use_structured else "legacy",
                is_json_action=bool(is_json_action),
                fenced_json=bool(fenced_detected),
                classifier_invoked=False,
                classifier_has_verdict=False,
                classifier_used=False,
                classifier_verdict=None,
                retry_reason=override_retry_reason,
                tool_call_parse_error=data.get("tool_call_parse_error"),
            )
        else:
            assessment = cast(
                _MissingToolCallAssessment,
                assessor(
                    response_text=data.get("response_text", ""),
                    use_structured=bool(data.get("use_structured")),
                    interpretation=data.get("interpretation"),
                    llm_client=request.environment.llm_client,
                    model=request.environment.model,
                    classifier_model=data.get("classifier_model"),
                    aux_log=aux_log,
                    tool_call_parse_error=data.get("tool_call_parse_error"),
                    allow_semantic_retry=allow_semantic_retry,
                ),
            )

        try:
            aux_log.append(
                annotate_python_decision_event(
                    {
                        "type": "missing_tool_call_detection",
                        "path": assessment.path,
                        "is_json_action": assessment.is_json_action,
                        "fenced_json": assessment.fenced_json,
                        "classifier_invoked": assessment.classifier_invoked,
                        "classifier_has_verdict": assessment.classifier_has_verdict,
                        "classifier_used": assessment.classifier_used,
                        "classifier_verdict": (
                            "yes"
                            if assessment.classifier_verdict is True
                            else (
                                "no"
                                if assessment.classifier_verdict is False
                                else "unavailable"
                            )
                        ),
                        "retry_reason": assessment.retry_reason or "",
                        "retry_reason_override_applied": bool(override_retry_reason),
                        "parse_error": (
                            str(assessment.tool_call_parse_error)
                            if assessment.tool_call_parse_error is not None
                            else ""
                        ),
                        "retry_attempts": retry_attempts,
                        "retry_budget": retry_budget,
                        "retries_remaining": retries_remaining_before,
                        "allow_semantic_retry": allow_semantic_retry,
                    },
                    stage="tool_recovery",
                    component="internal_mcp_orchestrator",
                    function="_action_missing_tool_call_assess",
                    decision_class="missing_tool_call_detection",
                    decision_source="response_structure_check",
                    changed_outcome=bool(assessment.retry_reason),
                    reason_code=assessment.retry_reason or "no_retry_needed",
                    possible_inappropriate_python_code_use=bool(
                        assessment.classifier_used
                    ),
                )
            )
        except Exception:
            pass

        retry_needed = bool(assessment.retry_reason) and retries_remaining_before > 0
        retry_suppressed = bool(assessment.retry_reason) and not retry_needed
        recovery_outcome = (
            "retry_needed"
            if retry_needed
            else "retry_suppressed"
            if retry_suppressed
            else "no_retry_required"
        )
        if retry_suppressed:
            try:
                aux_log.append(
                    annotate_python_decision_event(
                        {
                            "type": "missing_tool_call_retry",
                            "mechanism": "budget",
                            "stage": "skipped",
                            "retry_reason": assessment.retry_reason or "",
                            "retry_attempts": retry_attempts,
                            "retry_budget": retry_budget,
                            "retries_remaining": retries_remaining_before,
                        },
                        stage="tool_recovery",
                        component="internal_mcp_orchestrator",
                        function="_action_missing_tool_call_assess",
                        decision_class="missing_tool_call_retry",
                        decision_source="retry_budget_check",
                        changed_outcome=True,
                        reason_code="retry_budget_exhausted",
                        possible_inappropriate_python_code_use=False,
                    )
                )
            except Exception:
                pass

        outputs = {
            "missing_tool_call_assessment": asdict(assessment),
            "missing_tool_call_retry_needed": retry_needed,
            "missing_tool_call_retry_reason": assessment.retry_reason,
            "missing_tool_call_retry_attempts": retry_attempts,
            "missing_tool_call_retry_budget": retry_budget,
            "missing_tool_call_retry_remaining": retries_remaining_before,
            "missing_tool_call_retry_suppressed": retry_suppressed,
            "missing_tool_call_recovery_outcome": recovery_outcome,
            "tool_call_parse_error": data.get("tool_call_parse_error"),
            "result": retry_needed,
        }
        if isinstance(aux_log, list):
            outputs["aux_llm_calls"] = aux_log

        if request.trace is not None:
            request.trace.metadata.setdefault("missing_tool_call", {})
            request.trace.metadata["missing_tool_call"].update(
                {
                    "retry_reason": assessment.retry_reason,
                    "classifier_verdict": assessment.classifier_verdict,
                    "retry_attempts": retry_attempts,
                    "retry_budget": retry_budget,
                    "retries_remaining": retries_remaining_before,
                    "retry_suppressed": retry_suppressed,
                }
            )

        return WorkflowActionResult(outputs=outputs)

    def _action_write_policy_decide(self, request: Any) -> WorkflowActionResult:
        prompt = request.data.get("prompt")
        requested_tools = request.data.get("requested_write_tools")
        recent_user_prompts = request.data.get("recent_user_prompts")
        data = request.data if isinstance(request.data, MutableMapping) else {}
        aux_log = (
            data.setdefault("aux_llm_calls", [])
            if isinstance(data, MutableMapping)
            else None
        )
        if not isinstance(prompt, str):
            prompt = ""
        if not isinstance(requested_tools, list):
            requested_tools = []
        if not isinstance(recent_user_prompts, list):
            recent_user_prompts = []
        requested_tool_payloads = request.data.get("requested_tool_payloads")
        if not isinstance(requested_tool_payloads, Mapping):
            requested_tool_payloads = {}
        caller_workflow_id = request.data.get("caller_workflow_id")
        caller_workflow_step_id = request.data.get("caller_workflow_step_id")
        caller_workflow_step_metadata = request.data.get(
            "caller_workflow_step_metadata"
        )
        guardrail_surface = (
            str(
                request.data.get("write_policy_guardrail_surface") or "write_policy"
            ).strip()
            or "write_policy"
        )
        guardrail_stage = (
            str(
                request.data.get("write_policy_guardrail_stage")
                or "write_policy.decide"
            ).strip()
            or "write_policy.decide"
        )
        conversation_session_id = request.data.get("conversation_session_id")
        turn_id = request.data.get("turn_id")
        try:
            runtime_profile, runtime_profile_diagnostics = (
                load_minimal_imposition_runtime_profile(
                    workflow_id=WRITE_TOOL_POLICY_WORKFLOW_ID
                )
            )
        except Exception as exc:
            runtime_profile = None
            runtime_profile_diagnostics = {
                "status": "runtime_profile_unavailable",
                "error": str(exc),
                "workflow_id": WRITE_TOOL_POLICY_WORKFLOW_ID,
            }

        requested_tool_list = [str(tool) for tool in requested_tools if tool]
        request_evidence: dict[str, dict[str, Any]] = {}
        request_evidence_diagnostics: dict[str, Any] = {
            "schema_version": "write_tool_request_evidence.v1",
            "status": "skipped_no_requested_tools",
            "requested_tool_count": len(requested_tool_list),
        }
        turn_contract_request_evidence_diagnostics: dict[str, Any] = {}
        if requested_tool_list:
            request_evidence, request_evidence_diagnostics = (
                infer_write_tool_request_evidence(
                    llm_client=request.environment.llm_client,
                    model=request.environment.model,
                    prompt=prompt,
                    recent_user_prompts=[
                        str(item)
                        for item in recent_user_prompts
                        if isinstance(item, str)
                    ],
                    requested_tools=requested_tool_list,
                    requested_tool_payloads={
                        str(tool_name): dict(payload)
                        for tool_name, payload in requested_tool_payloads.items()
                        if isinstance(tool_name, str) and isinstance(payload, Mapping)
                    },
                )
            )
            (
                request_evidence,
                turn_contract_request_evidence_diagnostics,
            ) = augment_write_tool_request_evidence_with_turn_contract(
                request_evidence=request_evidence,
                requested_tools=requested_tool_list,
                requested_tool_payloads={
                    str(tool_name): dict(payload)
                    for tool_name, payload in requested_tool_payloads.items()
                    if isinstance(tool_name, str) and isinstance(payload, Mapping)
                },
                turn_expected_outcome_contract=(
                    data.get("turn_expected_outcome_contract_state")
                    if isinstance(
                        data.get("turn_expected_outcome_contract_state"), Mapping
                    )
                    else (
                        data.get("turn_expected_outcome_contract")
                        if isinstance(
                            data.get("turn_expected_outcome_contract"), Mapping
                        )
                        else None
                    )
                ),
                activated_conditional_required_tools=(
                    data.get("activated_conditional_required_tools")
                    if isinstance(
                        data.get("activated_conditional_required_tools"), Sequence
                    )
                    and not isinstance(
                        data.get("activated_conditional_required_tools"),
                        (str, bytes, bytearray),
                    )
                    else None
                ),
            )
            if turn_contract_request_evidence_diagnostics:
                request_evidence_diagnostics = dict(request_evidence_diagnostics)
                request_evidence_diagnostics["turn_contract_request_evidence"] = dict(
                    turn_contract_request_evidence_diagnostics
                )
            if isinstance(aux_log, list):
                aux_log.append(
                    {
                        "type": "write_tool_request_evidence",
                        "status": (
                            str(
                                request_evidence_diagnostics.get("status") or ""
                            ).strip()
                            or "unknown"
                        ),
                        "requested_tool_count": len(requested_tool_list),
                        "parse_mode": (
                            str(
                                request_evidence_diagnostics.get("parse_mode") or ""
                            ).strip()
                            or None
                        ),
                        "resolved_prompt_concept_id": (
                            str(
                                request_evidence_diagnostics.get(
                                    "resolved_prompt_concept_id"
                                )
                                or ""
                            ).strip()
                            or None
                        ),
                        "loaded_prompt_concept_id": (
                            str(
                                request_evidence_diagnostics.get(
                                    "loaded_prompt_concept_id"
                                )
                                or ""
                            ).strip()
                            or None
                        ),
                        "tool_names": list(request_evidence.keys()),
                        "request_evidence": {
                            str(tool_name): dict(evidence)
                            for tool_name, evidence in request_evidence.items()
                            if isinstance(tool_name, str)
                            and isinstance(evidence, Mapping)
                        },
                        "request_evidence_diagnostics": dict(
                            request_evidence_diagnostics
                        ),
                        "turn_contract_request_evidence": dict(
                            turn_contract_request_evidence_diagnostics
                        ),
                    }
                )

        decision = compute_allowed_write_tools(
            prompt=prompt,
            requested_tools=requested_tool_list,
            requested_tool_payloads={
                str(tool_name): dict(payload)
                for tool_name, payload in requested_tool_payloads.items()
                if isinstance(tool_name, str) and isinstance(payload, Mapping)
            },
            request_evidence=request_evidence,
            request_evidence_diagnostics=request_evidence_diagnostics,
            recent_user_prompts=[
                str(item) for item in recent_user_prompts if isinstance(item, str)
            ],
            user_mutation_authority=self._resolve_user_mutation_authority_level(
                user_namespace=request.environment.user_namespace
            ),
            workflow_mutation_authority=(
                caller_workflow_step_metadata.get("mutation_authority")
                if isinstance(caller_workflow_step_metadata, Mapping)
                else None
            ),
            global_mutation_authority=self._resolve_global_mutation_authority_level(),
            runtime_profile=runtime_profile,
            runtime_profile_diagnostics=runtime_profile_diagnostics,
        )
        try:
            from ...workflows.workflow_baseline_telemetry import (
                record_write_policy_decision,
            )

            record_write_policy_decision(
                stage="write_policy.decide",
                allowed_tools_count=len(decision.allowed_tools),
            )
        except Exception:
            pass

        mutation_guardrail_events = build_mutation_guardrail_events(
            policy_decision=decision,
            guardrail_surface=guardrail_surface,
            stage=guardrail_stage,
            workflow_id=(
                str(caller_workflow_id).strip()
                if isinstance(caller_workflow_id, str) and caller_workflow_id.strip()
                else None
            ),
            workflow_step_id=(
                str(caller_workflow_step_id).strip()
                if isinstance(caller_workflow_step_id, str)
                and caller_workflow_step_id.strip()
                else None
            ),
            action_id=(
                str(request.action_id).strip()
                if isinstance(request.action_id, str) and request.action_id.strip()
                else None
            ),
            conversation_session_id=(
                str(conversation_session_id).strip()
                if isinstance(conversation_session_id, str)
                and conversation_session_id.strip()
                else None
            ),
            turn_id=(
                str(turn_id).strip()
                if isinstance(turn_id, str) and turn_id.strip()
                else None
            ),
        )

        outputs = {
            "allowed_write_tools": sorted(decision.allowed_tools),
            "write_policy_reason": decision.reason,
            "write_policy_decision_basis": decision.decision_basis,
            "write_policy_outcome": decision.outcome,
            "write_policy_user_denial_detected": decision.user_denial_detected,
            "write_policy_effective_mutation_authority": (
                decision.effective_mutation_authority
            ),
            "write_policy_authority_sources": dict(decision.authority_sources),
            "write_policy_risk_classes": {
                item.tool_name: item.risk_class for item in decision.tool_decisions
            },
            "write_policy_tool_outcomes": {
                item.tool_name: item.outcome for item in decision.tool_decisions
            },
            "write_policy_blocked_reasons": {
                item.tool_name: item.blocked_reason
                for item in decision.tool_decisions
                if isinstance(item.blocked_reason, str) and item.blocked_reason
            },
            "write_policy_authority_block_sources": {
                item.tool_name: item.authority_block_source
                for item in decision.tool_decisions
                if isinstance(item.authority_block_source, str)
                and item.authority_block_source
            },
            "write_policy_scenario_ids": {
                item.tool_name: item.scenario_id
                for item in decision.tool_decisions
                if isinstance(item.scenario_id, str) and item.scenario_id
            },
            "write_policy_risk_features": {
                item.tool_name: dict(item.risk_features or {})
                for item in decision.tool_decisions
                if isinstance(item.risk_features, Mapping)
            },
            "write_policy_unresolved_risk_factors": {
                item.tool_name: list(item.unresolved_risk_factors)
                for item in decision.tool_decisions
                if item.unresolved_risk_factors
            },
            "write_policy_intervention_kinds": {
                item.tool_name: item.intervention_kind
                for item in decision.tool_decisions
                if isinstance(item.intervention_kind, str) and item.intervention_kind
            },
            "write_policy_confidence_states": {
                item.tool_name: item.confidence_state
                for item in decision.tool_decisions
                if isinstance(item.confidence_state, str) and item.confidence_state
            },
            "write_policy_request_evidence": {
                str(tool_name): dict(evidence)
                for tool_name, evidence in decision.request_evidence.items()
                if isinstance(tool_name, str) and isinstance(evidence, Mapping)
            },
            "write_policy_request_evidence_diagnostics": dict(
                decision.request_evidence_diagnostics or {}
            ),
            "write_policy_profile_concept_id": decision.profile_concept_id,
            "write_policy_profile_diagnostics": dict(
                decision.profile_diagnostics or {}
            ),
            "write_policy_requires_confirmation": [
                item.tool_name
                for item in decision.tool_decisions
                if item.requires_confirmation
            ],
            "mutation_guardrail_events": list(mutation_guardrail_events),
            "approval_required": any(
                item.requires_confirmation and not item.allowed
                for item in decision.tool_decisions
            ),
        }
        if isinstance(aux_log, list):
            outputs["aux_llm_calls"] = aux_log
        return WorkflowActionResult(outputs=outputs)

    def _action_preflight_specialised_suggest(
        self, request: Any
    ) -> WorkflowActionResult:
        """Stage-5 specialised fallback for sparse ontology preflight suggestions."""

        data = request.data if isinstance(request.data, Mapping) else {}
        prompt_raw = data.get("prompt")
        prompt = str(prompt_raw).strip() if isinstance(prompt_raw, str) else ""
        if not prompt:
            return WorkflowActionResult(
                outputs={
                    "specialised_suggestions_available": False,
                    "specialised_type_suggestions": [],
                    "specialised_predicate_suggestions": [],
                    "specialised_workflow_skip_reason": "missing_prompt",
                }
            )

        max_suggestions = self._coerce_non_negative_int(
            data.get("max_suggestions"),
            default=self._SPECIALISED_PREFLIGHT_MAX_SUGGESTIONS,
            max_value=16,
        )
        if max_suggestions <= 0:
            max_suggestions = self._SPECIALISED_PREFLIGHT_MAX_SUGGESTIONS

        baseline_type_suggestions = self._normalise_specialised_preflight_suggestions(
            data.get("baseline_type_suggestions"),
            fallback_source_path="baseline_preflight",
            max_items=max_suggestions,
        )
        baseline_predicate_suggestions = (
            self._normalise_specialised_preflight_suggestions(
                data.get("baseline_predicate_suggestions"),
                fallback_source_path="baseline_preflight",
                max_items=max_suggestions,
            )
        )
        need_types = not baseline_type_suggestions
        need_predicates = not baseline_predicate_suggestions

        if not need_types and not need_predicates:
            return WorkflowActionResult(
                outputs={
                    "specialised_suggestions_available": False,
                    "specialised_type_suggestions": [],
                    "specialised_predicate_suggestions": [],
                    "specialised_workflow_skip_reason": "baseline_already_sufficient",
                }
            )

        candidate_type_pool = self._normalise_specialised_preflight_suggestions(
            data.get("candidate_type_pool"),
            fallback_source_path="specialised_candidate_pool",
            max_items=max_suggestions * 3,
        )
        candidate_predicate_pool = self._normalise_specialised_preflight_suggestions(
            data.get("candidate_predicate_pool"),
            fallback_source_path="specialised_candidate_pool",
            max_items=max_suggestions * 3,
        )

        def _seed_from_pool(
            pool: Sequence[Mapping[str, Any]],
            *,
            limit: int,
        ) -> list[dict[str, Any]]:
            selected: list[dict[str, Any]] = []
            seen: set[str] = set()
            for item in pool:
                if not isinstance(item, Mapping):
                    continue
                concept_id = item.get("concept_id")
                if not isinstance(concept_id, str):
                    continue
                cleaned = concept_id.strip()
                if not self._looks_like_concept_id(cleaned):
                    continue
                lowered = cleaned.lower()
                if lowered in seen:
                    continue
                seen.add(lowered)
                selected.append(dict(item))
                if len(selected) >= limit:
                    break
            return selected

        specialised_type_suggestions = (
            _seed_from_pool(candidate_type_pool, limit=max_suggestions)
            if need_types
            else []
        )
        specialised_predicate_suggestions = (
            _seed_from_pool(candidate_predicate_pool, limit=max_suggestions)
            if need_predicates
            else []
        )

        search_invoked = False
        search_errors: list[str] = []

        try:
            from src.backend.services.concept_search_service import search_concepts
        except Exception:
            search_concepts = None

        def _append_similarity_results(
            *,
            bucket: list[dict[str, Any]],
            filter_kind: str,
        ) -> None:
            nonlocal search_invoked
            if len(bucket) >= max_suggestions:
                return
            if not callable(search_concepts):
                search_errors.append("specialised_similarity_search_unavailable")
                return
            try:
                search_invoked = True
                result = search_concepts(
                    query=prompt,
                    filter_kind=[filter_kind],
                    match_type="similarity",
                    min_similarity=0.45,
                    limit=max(max_suggestions * 3, 8),
                )
            except Exception as exc:
                search_errors.append(f"specialised_similarity_search_failed:{exc}")
                return

            entries = result.get("results") if isinstance(result, Mapping) else None
            if not isinstance(entries, Sequence) or isinstance(
                entries, (str, bytes, bytearray)
            ):
                return

            normalised_inputs: list[dict[str, Any]] = []
            for entry in entries:
                if not isinstance(entry, Mapping):
                    continue
                candidate = entry.get("concept_id")
                if not isinstance(candidate, str):
                    continue
                payload: dict[str, Any] = {
                    "concept_id": candidate,
                    "source_path": self._SPECIALISED_PREFLIGHT_SOURCE_PATH,
                }
                candidate_name = entry.get("name")
                if isinstance(candidate_name, str) and candidate_name.strip():
                    payload["name"] = candidate_name.strip()
                similarity = entry.get("similarity_score")
                if isinstance(similarity, (int, float)):
                    payload["score"] = round(float(similarity), 6)
                normalised_inputs.append(payload)

            normalised_entries = self._normalise_specialised_preflight_suggestions(
                normalised_inputs,
                fallback_source_path=self._SPECIALISED_PREFLIGHT_SOURCE_PATH,
                max_items=max_suggestions,
            )

            seen_bucket_ids = {
                str(item.get("concept_id", "")).strip().lower()
                for item in bucket
                if isinstance(item, Mapping)
            }
            for item in normalised_entries:
                concept_id = str(item.get("concept_id", "")).strip()
                lowered = concept_id.lower()
                if not concept_id or lowered in seen_bucket_ids:
                    continue
                seen_bucket_ids.add(lowered)
                bucket.append(dict(item))
                if len(bucket) >= max_suggestions:
                    break

        if need_types and len(specialised_type_suggestions) < max_suggestions:
            _append_similarity_results(
                bucket=specialised_type_suggestions, filter_kind="type"
            )

        if need_predicates and len(specialised_predicate_suggestions) < max_suggestions:
            _append_similarity_results(
                bucket=specialised_predicate_suggestions, filter_kind="predicate"
            )

        return WorkflowActionResult(
            outputs={
                "specialised_suggestions_available": bool(
                    specialised_type_suggestions or specialised_predicate_suggestions
                ),
                "specialised_type_suggestions": specialised_type_suggestions[
                    :max_suggestions
                ],
                "specialised_predicate_suggestions": specialised_predicate_suggestions[
                    :max_suggestions
                ],
                "specialised_search_invoked": search_invoked,
                "specialised_search_errors": search_errors,
                "specialised_workflow_skip_reason": None,
            }
        )

    def _action_missing_tool_call_retry(self, request: Any) -> WorkflowActionResult:
        data = cast(MutableMapping[str, Any], request.data)
        aux_log = data.setdefault("aux_llm_calls", [])
        augmented_context = data.get("augmented_context") or []
        tool_invocation_sequence = cast(
            Sequence[Mapping[str, Any]] | None,
            (
                data.get("invocations")
                if isinstance(data.get("invocations"), Sequence)
                and not isinstance(data.get("invocations"), (str, bytes, bytearray))
                else None
            ),
        )
        successful_tool_names = self._extract_successful_tool_names(
            tool_invocation_sequence
        )
        missing_required_tools = data.get("missing_prompt_tools")
        if not isinstance(missing_required_tools, list):
            missing_required_tools = []
        missing_required_tools = [
            str(item).strip()
            for item in missing_required_tools
            if isinstance(item, str) and item.strip()
        ]
        missing_required_fetch_concept_ids = data.get(
            "missing_prompt_fetch_concept_ids"
        )
        if not isinstance(missing_required_fetch_concept_ids, list):
            missing_required_fetch_concept_ids = []
        missing_required_fetch_concept_ids = [
            str(item).strip()
            for item in missing_required_fetch_concept_ids
            if isinstance(item, str) and item.strip()
        ]
        missing_required_read_file_copy_ids = data.get(
            "missing_prompt_read_file_copy_ids"
        )
        if not isinstance(missing_required_read_file_copy_ids, list):
            missing_required_read_file_copy_ids = []
        missing_required_read_file_copy_ids = [
            str(item).strip()
            for item in missing_required_read_file_copy_ids
            if isinstance(item, str) and item.strip()
        ]
        missing_required_scholarly_file_copy_ids = data.get(
            "missing_prompt_scholarly_representation_for_file_copy_ids"
        )
        if not isinstance(missing_required_scholarly_file_copy_ids, list):
            missing_required_scholarly_file_copy_ids = []
        missing_required_scholarly_file_copy_ids = [
            str(item).strip()
            for item in missing_required_scholarly_file_copy_ids
            if isinstance(item, str) and item.strip()
        ]
        required_create_type_name_raw = data.get("required_prompt_create_type_name")
        required_create_type_name = (
            str(required_create_type_name_raw).strip()
            if isinstance(required_create_type_name_raw, str)
            else None
        )
        required_url_extraction_url_raw = data.get("required_prompt_url_extraction_url")
        required_url_extraction_url = (
            str(required_url_extraction_url_raw).strip()
            if isinstance(required_url_extraction_url_raw, str)
            and str(required_url_extraction_url_raw).strip()
            else None
        )
        emit_progress_raw = data.get("emit_progress")
        emit_progress_cb: Callable[[Mapping[str, Any]], None] | None = (
            cast(Callable[[Mapping[str, Any]], None], emit_progress_raw)
            if callable(emit_progress_raw)
            else None
        )
        record_llm_call = data.get("record_llm_call")
        llm_calls_log = data.get("llm_calls")
        calling_path = "legacy"
        method_catalogue_for_retry = self._resolve_method_catalogue_for_workflow_data(
            data
        )
        assessment = data.get("missing_tool_call_assessment")
        if isinstance(assessment, dict) and isinstance(assessment.get("path"), str):
            calling_path = str(assessment.get("path") or "legacy")

        retry_attempts = self._coerce_non_negative_int(
            data.get("missing_tool_call_retry_attempts"),
            default=0,
            max_value=20,
        )
        retry_budget = self._coerce_non_negative_int(
            data.get("missing_tool_call_retry_budget"),
            default=self._max_missing_tool_call_retries_per_turn,
            max_value=20,
        )
        retries_remaining_before = max(0, retry_budget - retry_attempts)
        data["missing_tool_call_retry_attempts"] = retry_attempts
        data["missing_tool_call_retry_budget"] = retry_budget

        if retries_remaining_before <= 0:
            budget_exhausted_response = self._sanitise_user_visible_action_output(
                data.get("response_text"),
                aux_log=aux_log if isinstance(aux_log, list) else None,
                source_stage="missing_tool_call.retry",
            )
            if emit_progress_cb is not None:
                emit_progress_cb(
                    {
                        "status": "retry_end",
                        "stage": "tool_recovery",
                        "retry_attempts": retry_attempts,
                        "retry_budget": retry_budget,
                        "retry_remaining": 0,
                        "success": False,
                        "skipped": True,
                    }
                )
            try:
                aux_log.append(
                    annotate_python_decision_event(
                        {
                            "type": "missing_tool_call_retry",
                            "path": calling_path,
                            "mechanism": "budget",
                            "stage": "skipped",
                            "retry_reason": data.get("missing_tool_call_retry_reason")
                            or "",
                            "retry_attempts": retry_attempts,
                            "retry_budget": retry_budget,
                            "retries_remaining": retries_remaining_before,
                        },
                        stage="tool_recovery",
                        component="internal_mcp_orchestrator",
                        function="_action_missing_tool_call_retry",
                        decision_class="missing_tool_call_retry",
                        decision_source="retry_budget_check",
                        changed_outcome=True,
                        reason_code="retry_budget_exhausted",
                        possible_inappropriate_python_code_use=False,
                    )
                )
            except Exception:
                pass
            return WorkflowActionResult(
                outputs={
                    "response_text": budget_exhausted_response,
                    "tool_calls": data.get("tool_calls"),
                    "missing_tool_call_retry_success": False,
                    "tool_call_parse_error": data.get("tool_call_parse_error"),
                    "missing_tool_call_retry_attempts": retry_attempts,
                    "missing_tool_call_retry_budget": retry_budget,
                    "missing_tool_call_retry_remaining": 0,
                    "missing_tool_call_retry_suppressed": True,
                    "missing_tool_call_retry_stop_reason": "retry_budget_exhausted",
                    "missing_tool_call_recovery_outcome": "retry_budget_exhausted",
                    "result": False,
                },
                duration_ms=0.0,
            )

        retry_attempts += 1
        retries_remaining_after = max(0, retry_budget - retry_attempts)
        data["missing_tool_call_retry_attempts"] = retry_attempts

        if emit_progress_cb is not None:
            emit_progress_cb(
                {
                    "status": "retry_start",
                    "stage": "tool_recovery",
                    "retry_attempts": retry_attempts,
                    "retry_budget": retry_budget,
                    "retry_remaining": retries_remaining_after,
                    "retry_reason": data.get("missing_tool_call_retry_reason") or "",
                }
            )

        retry_context: list[Mapping[str, Any]] = []
        user_prompt_text = data.get("user_prompt")
        if isinstance(user_prompt_text, str) and user_prompt_text.strip():
            retry_context.append({"role": "user", "content": user_prompt_text.strip()})
        prior_response_text = data.get("response_text")
        if isinstance(prior_response_text, str) and prior_response_text.strip():
            retry_context.append(
                {"role": "assistant", "content": prior_response_text.strip()}
            )
        if not retry_context:
            retry_context = list(augmented_context)

        turn_expected_outcome_contract_object = (
            self._build_turn_expected_outcome_contract_object(data)
        )
        missing_surface_notes: list[str] = []
        turn_contract_required_tools = {
            str(tool_name).strip().lower()
            for tool_name in turn_expected_outcome_contract_object.required_tools
            if isinstance(tool_name, str) and str(tool_name).strip()
        }
        turn_contract_required_surface_families = set(
            self._infer_required_tool_surface_families(
                required_tools=tuple(turn_contract_required_tools)
            )
        )
        if (
            "jira" in turn_contract_required_surface_families
            and "jira_search" not in successful_tool_names
            and "jira_get_issue" not in successful_tool_names
        ):
            missing_surface_notes.append(
                "A Jira retrieval step required by the turn contract has not been completed yet."
            )
        if (
            "arxiv" in turn_contract_required_surface_families
            and "search_arxiv" not in successful_tool_names
            and "download_paper" not in successful_tool_names
        ):
            missing_surface_notes.append(
                "An arXiv retrieval step required by the turn contract has not been completed yet."
            )
        if (
            "knowledge_base" in turn_contract_required_surface_families
            and "search_knowledge_base" not in successful_tool_names
            and "search_concepts" not in successful_tool_names
        ):
            missing_surface_notes.append(
                "A represented-knowledge retrieval step required by the turn contract has not been completed yet."
            )
        if (
            "task_create" in turn_contract_required_tools
            and "task_create" not in successful_tool_names
        ):
            missing_surface_notes.append(
                "A task creation step required by the turn contract has not been completed yet."
            )
        if successful_tool_names or missing_required_tools or missing_surface_notes:
            retry_guidance_lines = ["Tool recovery context:"]
            if successful_tool_names:
                retry_guidance_lines.append(
                    "- Already invoked successfully this turn: "
                    + ", ".join(successful_tool_names)
                )
            if missing_required_tools:
                retry_guidance_lines.append(
                    "- Explicitly missing required tools: "
                    + ", ".join(missing_required_tools)
                )
            retry_guidance_lines.extend(f"- {note}" for note in missing_surface_notes)
            retry_guidance_lines.append(
                "- Prefer emitting only the still-missing tool calls rather than repeating earlier successful retrieval steps."
            )
            retry_context = [
                {"role": "system", "content": "\n".join(retry_guidance_lines)},
                *retry_context,
            ]

        forced = self._infer_missing_tool_call_retry_tool_calls(
            retry_context,
            user_prompt=data.get("user_prompt"),
            turn_expected_outcome_contract=turn_expected_outcome_contract_object,
            workflow_required_effects_contract=(
                data.get("workflow_required_effects_contract")
                if isinstance(data.get("workflow_required_effects_contract"), Mapping)
                else None
            ),
            workflow_required_effects_contract_source=(
                str(data.get("workflow_required_effects_contract_source")).strip()
                if isinstance(
                    data.get("workflow_required_effects_contract_source"), str
                )
                and str(data.get("workflow_required_effects_contract_source")).strip()
                else None
            ),
            missing_required_tools=missing_required_tools,
            missing_required_fetch_concept_ids=missing_required_fetch_concept_ids,
            missing_required_read_file_copy_ids=missing_required_read_file_copy_ids,
            missing_required_scholarly_representation_file_copy_ids=missing_required_scholarly_file_copy_ids,
            required_create_type_name=required_create_type_name,
            required_url_extraction_url=required_url_extraction_url,
            tool_invocations=tool_invocation_sequence,
            tool_argument_defaults=(
                data.get("tool_argument_defaults")
                if isinstance(data.get("tool_argument_defaults"), Mapping)
                else None
            ),
            invoked_tool_names=successful_tool_names,
            user_concept_id=(
                data.get("user_concept_id")
                if isinstance(data.get("user_concept_id"), str)
                else getattr(request.environment, "user_concept_id", None)
            ),
            workflow_discovery_result=(
                data.get("workflow_discovery_result")
                if isinstance(data.get("workflow_discovery_result"), Mapping)
                else None
            ),
            workflow_execute_inputs=self._build_turn_launchability_probe_inputs(
                prompt_text=str(
                    data.get("user_prompt") or data.get("prompt") or ""
                ).strip(),
                augmented_context=retry_context,
                workflow_discovery_result=(
                    data.get("workflow_discovery_result")
                    if isinstance(data.get("workflow_discovery_result"), Mapping)
                    else None
                ),
                continuation_context=(
                    data.get("continuation_context")
                    if isinstance(data.get("continuation_context"), Mapping)
                    else None
                ),
                user_namespace=getattr(request.environment, "user_namespace", None),
                user_concept_id=(
                    data.get("user_concept_id")
                    if isinstance(data.get("user_concept_id"), str)
                    else getattr(request.environment, "user_concept_id", None)
                ),
                org_concept_id=(
                    data.get("org_concept_id")
                    if isinstance(data.get("org_concept_id"), str)
                    else getattr(request.environment, "org_concept_id", None)
                ),
                gmail_profile=(
                    data.get("gmail_profile")
                    if isinstance(data.get("gmail_profile"), str)
                    else None
                ),
                base_data=data if isinstance(data, Mapping) else None,
            ),
            method_catalogue=method_catalogue_for_retry,
            selected_gmail_profile=self._selected_gmail_profile_for_workflow_data(
                data,
                request.environment,
            ),
            user_namespace=getattr(request.environment, "user_namespace", None),
            conversation_session_id=(
                str(data.get("conversation_session_id")).strip()
                if isinstance(data.get("conversation_session_id"), str)
                and str(data.get("conversation_session_id")).strip()
                else None
            ),
            turn_id=(
                str(data.get("turn_id")).strip()
                if isinstance(data.get("turn_id"), str)
                and str(data.get("turn_id")).strip()
                else None
            ),
        )
        if forced:
            import json

            retry_binding_sources = self._summarise_retry_tool_call_binding_sources(
                forced
            )
            forced = self._strip_retry_tool_call_internal_metadata(forced)
            try:
                aux_log.append(
                    annotate_python_decision_event(
                        {
                            "type": "missing_tool_call_retry",
                            "path": calling_path,
                            "mechanism": "structured_replay",
                            "stage": "response",
                            "retry_reason": data.get("missing_tool_call_retry_reason")
                            or "",
                            "retry_attempts": retry_attempts,
                            "retry_budget": retry_budget,
                            "retries_remaining": retries_remaining_after,
                            "response_preview": "(forced tool call)",
                            "retry_binding_sources": retry_binding_sources,
                        },
                        stage="tool_recovery",
                        component="internal_mcp_orchestrator",
                        function="_action_missing_tool_call_retry",
                        decision_class="missing_tool_call_retry",
                        decision_source="structured_retry_replay",
                        changed_outcome=True,
                        reason_code="structured_tool_call_replayed",
                        possible_inappropriate_python_code_use=False,
                    )
                )
            except Exception:
                pass

            response_text = (
                json.dumps(forced[0]) if len(forced) == 1 else json.dumps(forced)
            )
            if emit_progress_cb is not None:
                emit_progress_cb(
                    {
                        "status": "retry_end",
                        "stage": "tool_recovery",
                        "retry_attempts": retry_attempts,
                        "retry_budget": retry_budget,
                        "retry_remaining": retries_remaining_after,
                        "success": True,
                        "result_summary": "forced_tool_call",
                    }
                )

            return WorkflowActionResult(
                outputs={
                    "response_text": response_text,
                    "tool_calls": forced,
                    "missing_tool_call_retry_success": True,
                    "tool_call_parse_error": None,
                    "missing_tool_call_retry_attempts": retry_attempts,
                    "missing_tool_call_retry_budget": retry_budget,
                    "missing_tool_call_retry_remaining": retries_remaining_after,
                    "missing_tool_call_retry_suppressed": False,
                    "missing_tool_call_retry_stop_reason": None,
                    "missing_tool_call_recovery_outcome": "retry_succeeded_forced",
                    "result": True,
                },
                duration_ms=0.0,
            )

        rendered_prompt = self._render_authoritative_prompt(
            self._MISSING_TOOL_RETRY_PROMPTS,
            variables={},
            max_chars=4000,
            error_context="missing_tool_call_retry",
        )
        if rendered_prompt is None:
            if emit_progress_cb is not None:
                emit_progress_cb(
                    {
                        "status": "retry_end",
                        "stage": "tool_recovery",
                        "retry_attempts": retry_attempts,
                        "retry_budget": retry_budget,
                        "retry_remaining": retries_remaining_after,
                        "success": False,
                        "result_summary": "authoritative_prompt_unavailable",
                    }
                )
            return WorkflowActionResult(
                outputs={
                    "response_text": data.get("response_text"),
                    "tool_calls": data.get("tool_calls"),
                    "missing_tool_call_retry_success": False,
                    "tool_call_parse_error": data.get("tool_call_parse_error"),
                    "missing_tool_call_retry_attempts": retry_attempts,
                    "missing_tool_call_retry_budget": retry_budget,
                    "missing_tool_call_retry_remaining": retries_remaining_after,
                    "missing_tool_call_retry_suppressed": True,
                    "missing_tool_call_retry_stop_reason": "prompt_unavailable",
                    "missing_tool_call_recovery_outcome": "retry_prompt_unavailable",
                    "result": False,
                },
                duration_ms=0.0,
            )
        prompt_text = rendered_prompt.text
        if request.trace is not None:
            request.trace.record_prompt(
                prompt_id=rendered_prompt.prompt_id,
                resolved_prompt=prompt_text,
                variables={},
            )

        try:
            aux_log.append(
                annotate_python_decision_event(
                    {
                        "type": "missing_tool_call_retry",
                        "path": calling_path,
                        "mechanism": "workflow",
                        "stage": "prompt",
                        "retry_reason": data.get("missing_tool_call_retry_reason")
                        or "",
                        "retry_attempts": retry_attempts,
                        "retry_budget": retry_budget,
                        "retries_remaining": retries_remaining_after,
                        "prompt_preview": prompt_text[:800],
                    },
                    stage="tool_recovery",
                    component="internal_mcp_orchestrator",
                    function="_action_missing_tool_call_retry",
                    decision_class="missing_tool_call_retry",
                    decision_source="workflow_retry_prompt",
                    changed_outcome=True,
                    reason_code="retry_prompt_issued",
                    possible_inappropriate_python_code_use=False,
                )
            )
        except Exception:
            pass

        policy_state = data.get("policy_state")
        default_model = data.get("default_model")
        user_concept_id = data.get("user_concept_id")
        org_concept_id = data.get("org_concept_id")
        registry_snapshot = data.get("registry_snapshot")
        resolved_user_concept_id, resolved_org_concept_id = _resolve_identity_context(
            user_concept_id=(
                user_concept_id if isinstance(user_concept_id, str) else None
            ),
            org_concept_id=(
                org_concept_id if isinstance(org_concept_id, str) else None
            ),
            user_namespace=request.environment.user_namespace,
        )

        retry_response = None
        duration_ms = 0.0

        if isinstance(policy_state, _WorkflowModelPolicyState) and callable(
            record_llm_call
        ):
            llm_start = time.perf_counter()
            retry_response, _, _ = self._run_llm_with_fallbacks(
                stage="tool_recovery",
                prompt=prompt_text,
                context=retry_context,
                default_client=request.environment.llm_client,
                default_model=default_model or request.environment.model,
                policy_state=policy_state,
                registry_snapshot=(
                    registry_snapshot
                    if isinstance(registry_snapshot, Mapping)
                    else None
                ),
                user_concept_id=resolved_user_concept_id,
                org_concept_id=resolved_org_concept_id,
                llm_calls_log=(
                    llm_calls_log
                    if isinstance(llm_calls_log, list)
                    else data.get("llm_calls_log") or []
                ),
                aux_log=aux_log,
                record_llm_call=record_llm_call,
                emit_progress=emit_progress_cb,
                prefer_default_model=bool(data.get("prefer_default_model")),
                workflow_stage_id="tool_plan",
            )
            duration_ms = (time.perf_counter() - llm_start) * 1000.0
        else:
            llm_start = time.perf_counter()
            retry_response = request.environment.llm_client.generate(
                prompt_text, context=retry_context, model=request.environment.model
            )
            duration_ms = (time.perf_counter() - llm_start) * 1000.0

            if callable(record_llm_call):
                record_llm_call(
                    call_type="llm.generate",
                    model_name=request.environment.model,
                    duration_ms=duration_ms,
                    usage=None,
                    note="Missing tool call retry prompt (workflow).",
                    stage="tool_recovery",
                )

        try:
            aux_log.append(
                annotate_python_decision_event(
                    {
                        "type": "missing_tool_call_retry",
                        "path": calling_path,
                        "mechanism": "workflow",
                        "stage": "response",
                        "retry_reason": data.get("missing_tool_call_retry_reason")
                        or "",
                        "retry_attempts": retry_attempts,
                        "retry_budget": retry_budget,
                        "retries_remaining": retries_remaining_after,
                        "response_preview": (
                            retry_response[:800]
                            if isinstance(retry_response, str)
                            else str(retry_response)[:800]
                        ),
                    },
                    stage="tool_recovery",
                    component="internal_mcp_orchestrator",
                    function="_action_missing_tool_call_retry",
                    decision_class="missing_tool_call_retry",
                    decision_source="workflow_retry_response",
                    changed_outcome=False,
                    reason_code="retry_response_received",
                    possible_inappropriate_python_code_use=False,
                )
            )
        except Exception:
            pass

        extract_fn = data.get("extract_tool_calls_fn") or self._extract_tool_calls
        retry_calls = None
        parse_error = None
        try:
            retry_calls = extract_fn(retry_response)
        except ToolCallParsingError as exc:
            parse_error = exc

        success = bool(retry_calls)
        retry_response_text = (
            retry_response
            if isinstance(retry_response, str)
            else str(retry_response or "")
        )
        prior_response_clean = (
            prior_response_text.strip() if isinstance(prior_response_text, str) else ""
        )
        retry_response_clean = retry_response_text.strip()
        no_state_change_guard_triggered = (
            not success
            and parse_error is None
            and bool(prior_response_clean)
            and retry_response_clean == prior_response_clean
        )
        retry_stop_reason: str | None = None
        retry_suppressed = False
        if no_state_change_guard_triggered:
            retry_stop_reason = "no_state_change_guard_triggered"
            retry_suppressed = True
            retry_attempts = max(retry_attempts, retry_budget)
            retries_remaining_after = 0
            cast(MutableMapping[str, Any], data)["missing_tool_call_retry_attempts"] = (
                retry_attempts
            )
            try:
                aux_log.append(
                    annotate_python_decision_event(
                        {
                            "type": "missing_tool_call_retry",
                            "path": calling_path,
                            "mechanism": "no_progress_guard",
                            "stage": "skipped",
                            "retry_reason": data.get("missing_tool_call_retry_reason")
                            or "",
                            "retry_attempts": retry_attempts,
                            "retry_budget": retry_budget,
                            "retries_remaining": retries_remaining_after,
                            "stop_reason": retry_stop_reason,
                        },
                        stage="tool_recovery",
                        component="internal_mcp_orchestrator",
                        function="_action_missing_tool_call_retry",
                        decision_class="missing_tool_call_retry",
                        decision_source="stall_detection",
                        changed_outcome=True,
                        reason_code="no_state_change_guard_triggered",
                        possible_inappropriate_python_code_use=False,
                    )
                )
            except Exception:
                pass

        if no_state_change_guard_triggered:
            response_text_output = (
                "I couldn't execute the requested tool action because repeated "
                "recovery produced no executable tool call."
            )
        elif success:
            response_text_output = retry_response_text
        else:
            response_text_output = self._sanitise_user_visible_action_output(
                retry_response_text,
                aux_log=aux_log if isinstance(aux_log, list) else None,
                source_stage="missing_tool_call.retry",
            )
        recovery_outcome = (
            "retry_succeeded"
            if success
            else (
                retry_stop_reason
                if retry_stop_reason
                else (
                    "retry_failed_parse_error"
                    if parse_error is not None
                    else "retry_failed_no_tool_call"
                )
            )
        )

        outputs = {
            "response_text": response_text_output,
            "tool_calls": retry_calls,
            "missing_tool_call_retry_success": success,
            "tool_call_parse_error": parse_error or data.get("tool_call_parse_error"),
            "missing_tool_call_retry_attempts": retry_attempts,
            "missing_tool_call_retry_budget": retry_budget,
            "missing_tool_call_retry_remaining": retries_remaining_after,
            "missing_tool_call_retry_suppressed": retry_suppressed,
            "missing_tool_call_retry_stop_reason": retry_stop_reason,
            "missing_tool_call_recovery_outcome": recovery_outcome,
            "result": success,
        }
        if isinstance(aux_log, list):
            outputs["aux_llm_calls"] = aux_log

        if emit_progress_cb is not None:
            emit_progress_cb(
                {
                    "status": "retry_end",
                    "stage": "tool_recovery",
                    "retry_attempts": retry_attempts,
                    "retry_budget": retry_budget,
                    "retry_remaining": retries_remaining_after,
                    "success": bool(success),
                    "duration_ms": int(duration_ms),
                    "tool_calls_found": bool(retry_calls),
                    "suppressed": retry_suppressed,
                    "stop_reason": retry_stop_reason,
                }
            )

        return WorkflowActionResult(
            outputs=outputs,
            duration_ms=duration_ms,
        )

    def _run_missing_tool_call_recovery_workflow(
        self,
        *,
        request: Any,
        environment: WorkflowEnvironment,
        data: Mapping[str, Any],
        response_text: str,
        interpretation: _ModelTurnInterpretation | None,
        use_structured: bool,
        tool_call_parse_error: ToolCallParsingError | None,
        tool_calls: Sequence[Mapping[str, Any]] | None,
        default_model: str | None,
    ) -> Mapping[str, Any] | None:
        """Execute the shared missing-tool-call recovery workflow.

        This keeps plan/backfill recovery behaviour aligned and avoids
        duplicating workflow bootstrap logic.
        """

        workflow_def = self._workflow_registry.get(MISSING_TOOL_CALL_WORKFLOW_ID)
        if workflow_def is None:
            return None

        model_for_stage = data.get("model_for_stage")
        if not callable(model_for_stage):
            return None

        shared_aux_llm_calls = data.get("aux_llm_calls")
        turn_expected_outcome_payload = (
            self._build_turn_expected_outcome_context_payload(data)
        )
        workflow_context = {
            "user_prompt": data.get("prompt") or "",
            "response_text": (
                response_text if isinstance(response_text, str) else str(response_text)
            ),
            "interpretation": interpretation,
            "use_structured": use_structured,
            "tool_call_parse_error": tool_call_parse_error,
            "aux_llm_calls": (
                shared_aux_llm_calls if isinstance(shared_aux_llm_calls, list) else []
            ),
            "augmented_context": self._build_follow_up_llm_context(
                cast(Sequence[Mapping[str, Any]], data.get("augmented_context") or []),
                max_chars=self._follow_up_context_chars,
            ),
            "tool_calls": tool_calls,
            "missing_tool_assessor": self._assess_missing_tool_call,
            "extract_tool_calls_fn": self._extract_tool_calls,
            "record_llm_call": data.get("record_llm_call"),
            "classifier_model": model_for_stage("classifier"),
            "policy_state": data.get("policy_state"),
            "default_model": default_model,
            "prefer_default_model": bool(data.get("prefer_default_model")),
            "registry_snapshot": data.get("registry_snapshot"),
            "user_concept_id": data.get("user_concept_id"),
            "org_concept_id": data.get("org_concept_id"),
            "missing_tool_call_retry_attempts": data.get(
                "missing_tool_call_retry_attempts"
            ),
            "missing_tool_call_retry_budget": data.get(
                "missing_tool_call_retry_budget"
            ),
            "invocations": data.get("invocations"),
            "required_prompt_tools": data.get("required_prompt_tools"),
            "required_prompt_fetch_concept_ids": data.get(
                "required_prompt_fetch_concept_ids"
            ),
            "required_prompt_read_file_copy_ids": data.get(
                "required_prompt_read_file_copy_ids"
            ),
            "required_prompt_scholarly_representation_for_file_copy_ids": data.get(
                "required_prompt_scholarly_representation_for_file_copy_ids"
            ),
            "required_prompt_create_type_name": data.get(
                "required_prompt_create_type_name"
            ),
            "missing_prompt_tools": data.get("missing_prompt_tools"),
            "missing_prompt_fetch_concept_ids": data.get(
                "missing_prompt_fetch_concept_ids"
            ),
            "missing_prompt_read_file_copy_ids": data.get(
                "missing_prompt_read_file_copy_ids"
            ),
            "missing_prompt_scholarly_representation_for_file_copy_ids": data.get(
                "missing_prompt_scholarly_representation_for_file_copy_ids"
            ),
            "missing_tool_call_retry_reason_override": data.get(
                "missing_tool_call_retry_reason_override"
            ),
            "emit_progress": data.get("emit_progress"),
        }
        workflow_context.update(turn_expected_outcome_payload)

        recovery_model_raw = model_for_stage("tool_recovery")
        recovery_model = (
            recovery_model_raw if isinstance(recovery_model_raw, str) else None
        )
        recovery_env = WorkflowEnvironment(
            llm_client=environment.llm_client,
            gateway=self._gateway,
            model=recovery_model,
            user_namespace=environment.user_namespace,
            auxiliary_system_prompt=environment.auxiliary_system_prompt,
            max_tool_invocations=environment.max_tool_invocations,
            max_tool_result_chars=environment.max_tool_result_chars,
            max_tool_result_field_chars=environment.max_tool_result_field_chars,
            default_gmail_profile=(
                data.get("gmail_profile") or environment.default_gmail_profile
            ),
            user_concept_id=environment.user_concept_id,
            org_concept_id=environment.org_concept_id,
        )
        workflow_context.setdefault(
            "conversation_session_id", data.get("conversation_session_id")
        )
        workflow_context.setdefault("turn_id", data.get("turn_id"))
        workflow_context.setdefault("workflow_episode_source", "chat_turn_workflow")
        workflow_context.setdefault("workflow_episode_stage", "missing_tool_recovery")

        workflow_result = self.execute_workflow(
            MISSING_TOOL_CALL_WORKFLOW_ID,
            data=workflow_context,
            llm_client=environment.llm_client,
            model=recovery_model,
            user_namespace=environment.user_namespace,
            auxiliary_system_prompt=environment.auxiliary_system_prompt,
            trace=request.trace,
            environment=recovery_env,
            conversation_session_id=(
                data.get("conversation_session_id")
                if isinstance(data.get("conversation_session_id"), str)
                else None
            ),
            turn_id=(
                data.get("turn_id") if isinstance(data.get("turn_id"), str) else None
            ),
            episode_source="chat_turn_workflow",
        )
        if workflow_result is None:
            return None
        outer_aux_llm_calls = data.get("aux_llm_calls")
        self._project_missing_tool_call_aux_telemetry(
            outer_aux_llm_calls if isinstance(outer_aux_llm_calls, list) else None,
            workflow_result.data,
        )
        return workflow_result.data

    @staticmethod
    def _project_missing_tool_call_aux_telemetry(
        aux_log: list[Mapping[str, Any]] | None,
        recovery_data: Mapping[str, Any] | None,
    ) -> None:
        """Project missing-tool-call telemetry into the outer aux stream.

        Nested workflow execution does not always preserve shared list identity
        for `aux_llm_calls`. Reconstruct the canonical missing-tool-call
        telemetry from the returned recovery state when the nested entries are
        absent so the top-level turn remains observable.
        """

        if not isinstance(aux_log, list) or not isinstance(recovery_data, Mapping):
            return

        existing_types = {
            str(entry.get("type") or "")
            for entry in aux_log
            if isinstance(entry, Mapping)
        }
        assessment = recovery_data.get("missing_tool_call_assessment")
        path = ""
        if isinstance(assessment, Mapping):
            path = str(assessment.get("path") or "").strip()
            classifier_verdict = assessment.get("classifier_verdict")
            classifier_verdict_text = (
                "yes"
                if classifier_verdict is True
                else "no"
                if classifier_verdict is False
                else "unavailable"
            )
            if "missing_tool_call_detection" not in existing_types:
                aux_log.append(
                    {
                        "type": "missing_tool_call_detection",
                        "path": path,
                        "is_json_action": bool(assessment.get("is_json_action")),
                        "fenced_json": bool(assessment.get("fenced_json")),
                        "classifier_invoked": bool(
                            assessment.get("classifier_invoked")
                        ),
                        "classifier_has_verdict": bool(
                            assessment.get("classifier_has_verdict")
                        ),
                        "classifier_used": bool(assessment.get("classifier_used")),
                        "classifier_verdict": classifier_verdict_text,
                        "retry_reason": str(
                            recovery_data.get("missing_tool_call_retry_reason") or ""
                        ),
                        "retry_attempts": int(
                            recovery_data.get("missing_tool_call_retry_attempts", 0)
                        ),
                        "retry_budget": int(
                            recovery_data.get("missing_tool_call_retry_budget", 0)
                        ),
                        "retries_remaining": int(
                            recovery_data.get("missing_tool_call_retry_remaining", 0)
                        ),
                    }
                )
                existing_types.add("missing_tool_call_detection")

            if (
                bool(assessment.get("classifier_invoked"))
                and "missing_tool_call_classifier" not in existing_types
            ):
                aux_log.append(
                    {
                        "type": "missing_tool_call_classifier",
                        "path": path,
                        "model": "",
                        "model_raw": "",
                        "model_resolved": "",
                        "prompt_placeholder_response": True,
                        "prompt_injection_mode": "replace",
                        "prompt_preview": "",
                        "response_preview": classifier_verdict_text,
                        "truncated": False,
                    }
                )
                existing_types.add("missing_tool_call_classifier")

        if "missing_tool_call_retry" in existing_types:
            return

        retry_success = bool(recovery_data.get("missing_tool_call_retry_success"))
        retry_suppressed = bool(recovery_data.get("missing_tool_call_retry_suppressed"))
        retry_stage = (
            "completed"
            if retry_success
            else "skipped"
            if retry_suppressed
            else "failed"
        )
        aux_log.append(
            {
                "type": "missing_tool_call_retry",
                "path": path,
                "mechanism": "workflow_projection",
                "stage": retry_stage,
                "retry_reason": str(
                    recovery_data.get("missing_tool_call_retry_reason") or ""
                ),
                "retry_attempts": int(
                    recovery_data.get("missing_tool_call_retry_attempts", 0)
                ),
                "retry_budget": int(
                    recovery_data.get("missing_tool_call_retry_budget", 0)
                ),
                "retries_remaining": int(
                    recovery_data.get("missing_tool_call_retry_remaining", 0)
                ),
                "stop_reason": str(
                    recovery_data.get("missing_tool_call_retry_stop_reason") or ""
                ),
                "recovery_outcome": str(
                    recovery_data.get("missing_tool_call_recovery_outcome") or ""
                ),
            }
        )

    def _action_narration_classify(self, request: Any) -> WorkflowActionResult:
        required = bool(
            request.data.get("presenter_mode_requested")
            or request.data.get("force_narration")
        )
        return WorkflowActionResult(
            outputs={
                "narration_required": required,
                "result": required,
            }
        )

    def _action_narration_select_prompts(self, request: Any) -> WorkflowActionResult:
        prompt_ids = request.data.get("narration_prompt_ids") or ()
        fallback_text = request.data.get("narration_prompt_text")
        rendered = self._prompt_templates.render_prompt(
            prompt_ids,
            fallback=fallback_text,
            variables={},
            max_chars=6000,
        )
        prompt_text = rendered.text if rendered else fallback_text
        outputs = {
            "narration_prompt_text": prompt_text,
            "narration_prompt_id": rendered.prompt_id if rendered else None,
            "narration_prompts_resolved": bool(prompt_text),
        }
        if request.trace is not None and prompt_text:
            request.trace.record_prompt(
                prompt_id=rendered.prompt_id if rendered else None,
                resolved_prompt=prompt_text,
                variables={},
            )
        return WorkflowActionResult(outputs=outputs)

    @staticmethod
    def _coerce_spoken_text(text: object) -> str | None:
        if text is None:
            return None
        raw = str(text).strip()
        if not raw:
            return None

        import re

        match = re.search(
            r"<spoken>\s*(.*?)\s*</spoken>", raw, flags=re.DOTALL | re.IGNORECASE
        )
        if match:
            raw = match.group(1)

        raw = re.sub(r"</?spoken>", "", raw, flags=re.IGNORECASE)
        raw = re.sub(r"</?screen>", "", raw, flags=re.IGNORECASE)
        raw = re.sub(r"```.*?```", "", raw, flags=re.DOTALL)
        raw = raw.replace("`", "").strip()
        if not raw:
            return None
        try:
            max_chars = int(os.getenv("VON_NARRATION_SPOKEN_MAX_CHARS", "4000"))
        except ValueError:
            max_chars = 4000
        max_chars = max(200, min(max_chars, 50000))

        if len(raw) > max_chars:
            clipped = raw[:max_chars].rstrip()
            # Prefer clipping at a sentence boundary.
            for sep in (". ", "! ", "? "):
                cut = clipped.rfind(sep)
                if cut > 200:
                    clipped = clipped[: cut + 1]
                    break
            else:
                # Fall back to the last whitespace so we don't chop words.
                cut = clipped.rfind(" ")
                if cut > 200:
                    clipped = clipped[:cut]
            raw = clipped.strip()
        return raw or None

    @staticmethod
    def _coerce_non_empty_text(value: object) -> str | None:
        if value is None:
            return None
        text = value if isinstance(value, str) else str(value)
        text = text.strip()
        return text or None

    def _action_narration_render(self, request: Any) -> WorkflowActionResult:
        prompt_text = request.data.get("narration_prompt_text") or ""
        screen_text = request.data.get("screen_text") or ""
        user_prompt = request.data.get("user_prompt") or ""

        narration_system = (
            "You are Von. Produce a short talk track for text-to-speech. "
            "Return ONLY one block: <spoken>...</spoken>. "
            "Do not include <screen>. Do not include code blocks. "
            "Use New Zealand English spelling."
        )

        timing_hint = self._build_client_capabilities_narration_timing_hint()
        if timing_hint:
            narration_system += "\n" + timing_hint
        if prompt_text:
            narration_system += "\n\nVON CHAT NARRATION PROMPT (from Vontology):\n"
            narration_system += prompt_text

        narration_user = (
            "User message:\n"
            f"{user_prompt}\n\n"
            "On-screen content (do not read verbatim if long; summarise):\n"
            f"{screen_text}\n"
        )

        policy_state = request.data.get("policy_state")
        default_model = request.data.get("default_model")
        emit_progress_raw = request.data.get("emit_progress")
        emit_progress_cb: Callable[[Mapping[str, Any]], None] | None = (
            cast(Callable[[Mapping[str, Any]], None], emit_progress_raw)
            if callable(emit_progress_raw)
            else None
        )
        record_llm_call = request.data.get("record_llm_call")
        aux_llm_calls = request.data.get("aux_llm_calls")
        user_concept_id = request.data.get("user_concept_id")
        org_concept_id = request.data.get("org_concept_id")
        registry_snapshot = request.data.get("registry_snapshot")
        resolved_user_concept_id, resolved_org_concept_id = _resolve_identity_context(
            user_concept_id=(
                user_concept_id if isinstance(user_concept_id, str) else None
            ),
            org_concept_id=(
                org_concept_id if isinstance(org_concept_id, str) else None
            ),
            user_namespace=request.environment.user_namespace,
        )

        if (
            isinstance(policy_state, _WorkflowModelPolicyState)
            and callable(record_llm_call)
            and isinstance(aux_llm_calls, list)
        ):
            narration_response, _, _ = self._run_llm_with_fallbacks(
                stage="narration",
                prompt="Generate <spoken> talk track",
                context=[
                    {"role": "system", "content": narration_system},
                    {"role": "user", "content": narration_user},
                ],
                default_client=request.environment.llm_client,
                default_model=default_model or request.environment.model,
                policy_state=policy_state,
                registry_snapshot=(
                    registry_snapshot
                    if isinstance(registry_snapshot, Mapping)
                    else None
                ),
                user_concept_id=resolved_user_concept_id,
                org_concept_id=resolved_org_concept_id,
                llm_calls_log=request.data.get("llm_calls_log") or [],
                aux_log=aux_llm_calls,
                record_llm_call=record_llm_call,
                emit_progress=emit_progress_cb,
                prefer_default_model=bool(request.data.get("prefer_default_model")),
                workflow_stage_id="narration",
            )
        else:
            narration_response = request.environment.llm_client.generate(
                prompt="Generate <spoken> talk track",
                context=[
                    {"role": "system", "content": narration_system},
                    {"role": "user", "content": narration_user},
                ],
                model=request.environment.model,
            )

        spoken = self._coerce_spoken_text(narration_response)
        if not spoken:
            spoken = self._coerce_spoken_text(screen_text)

        outputs = {
            "narration_rendered": bool(spoken),
            "narration_spoken": spoken,
            "narration_raw_response": narration_response,
            "result": bool(spoken),
        }
        return WorkflowActionResult(outputs=outputs)

    def _action_narration_emit_audio(self, request: Any) -> WorkflowActionResult:
        spoken = request.data.get("narration_spoken")
        presenter_channels = request.data.get("presenter_channels") or {}
        if not isinstance(presenter_channels, dict):
            presenter_channels = {}
        screen_text = request.data.get("screen_text")
        if screen_text and "screen" not in presenter_channels:
            presenter_channels["screen"] = screen_text
        if spoken:
            presenter_channels["spoken"] = spoken
        return WorkflowActionResult(
            outputs={
                "presenter_channels": presenter_channels,
                "narration_emitted": bool(spoken),
            }
        )

    def _action_buttonify_assess_input(self, request: Any) -> WorkflowActionResult:
        buttonify_enabled = bool(request.data.get("buttonify_enabled"))
        buttonify_allowed = bool(request.data.get("buttonify_allowed"))
        screen_text = request.data.get("screen_text")

        suppression_reason: str | None = None
        should_run = True
        if not buttonify_enabled:
            should_run = False
            suppression_reason = "buttonify_disabled"
        elif not buttonify_allowed:
            should_run = False
            suppression_reason = "buttonify_not_allowed"
        elif not isinstance(screen_text, str) or not screen_text.strip():
            should_run = False
            suppression_reason = "empty_response"

        return WorkflowActionResult(
            outputs={
                "buttonify_should_run": should_run,
                "buttonify_status": "no_op" if should_run else "skipped",
                "buttonify_source": "none",
                "buttonify_suppression_reason": suppression_reason,
                "buttonify_error_class": None,
                "buttonify_model_attempted": False,
                "buttonify_model_used": request.data.get("default_model")
                or request.environment.model,
                "buttonify_options": [],
            }
        )

    def _action_buttonify_select_prompt(self, request: Any) -> WorkflowActionResult:
        prompt_ids_raw = request.data.get("buttonify_prompt_ids")
        prompt_ids = tuple(
            item.strip()
            for item in (
                prompt_ids_raw
                if isinstance(prompt_ids_raw, (list, tuple))
                else BUTTONIFY_PROMPT_IDS
            )
            if isinstance(item, str) and item.strip()
        )
        if not prompt_ids:
            prompt_ids = BUTTONIFY_PROMPT_IDS

        variables = {
            "user_message": request.data.get("user_prompt") or "",
            "assistant_response": request.data.get("screen_text") or "",
        }
        rendered = None
        prompt_error: str | None = None
        try:
            rendered = self._prompt_templates.render_prompt(
                prompt_ids,
                variables=variables,
                max_chars=6000,
            )
        except Exception as exc:
            rendered = None
            prompt_error = type(exc).__name__

        if rendered:
            prompt_text = rendered.text
            prompt_id = rendered.prompt_id
            prompt_truncated = rendered.truncated
            prompt_available = True
        else:
            prompt_text = ""
            prompt_id = None
            prompt_truncated = False
            prompt_available = False
            if not prompt_error:
                prompt_error = "prompt_not_found_or_unavailable"

        if prompt_available:
            prompt_text = enforce_buttonify_prompt_contract(prompt_text)

        if request.trace is not None and prompt_text:
            request.trace.record_prompt(
                prompt_id=prompt_id,
                resolved_prompt=prompt_text,
                variables=variables,
            )

        return WorkflowActionResult(
            outputs={
                "buttonify_prompt_text": prompt_text,
                "buttonify_prompt_id": prompt_id,
                "buttonify_prompt_truncated": prompt_truncated,
                "buttonify_prompt_available": prompt_available,
                "buttonify_prompt_error": prompt_error,
            }
        )

    # ------------------------------------------------------------------
    # Todo-refresh workflow handlers (JVNAUTOSCI-922 Phase 2.3)
    #
    # Five handlers that replace the ``_noop_action`` stubs registered for
    # the ``#V#todo_refresh_workflow`` state machine:
    #   check_cache -> maybe_fetch_gmail -> extract_tasks -> prioritise
    #   -> summarise -> completed
    #
    # Key data-dict fields consumed/produced:
    #   user_namespace, gmail_profile (inputs from caller),
    #   todo_refresh_needed (flag: cache stale?), raw_gmail_messages,
    #   extracted_tasks (list[dict]), prioritised_tasks (list[dict]),
    #   persisted_tasks (list[dict]), todo_summary (str).
    # ------------------------------------------------------------------

    # Configurable via env var; how many seconds before tasks are
    # considered stale and a refresh from Gmail is warranted.
    _TODO_CACHE_TTL_SECONDS: int = int(
        os.environ.get("VON_TODO_CACHE_TTL_SECONDS", "3600")
    )

    def _action_todo_refresh_check_cache(self, request: Any) -> WorkflowActionResult:
        """Check whether the user's task list is fresh enough to skip Gmail.

        Looks at the most recently created ``#V#task_specification`` for the
        current user.  If it was created less than ``_TODO_CACHE_TTL_SECONDS``
        ago, sets ``todo_refresh_needed=False`` and the workflow short-circuits
        to *completed*.
        """
        from ...services.task_management_service import get_tasks_for_user

        data = request.data
        user_ns = data.get("user_namespace") or getattr(
            request.environment, "user_namespace", None
        )

        if not user_ns:
            # No user context - nothing to cache-check; proceed with refresh.
            self._logger.debug("[todo_refresh] No user namespace; skipping cache check")
            return WorkflowActionResult(
                outputs={"todo_refresh_needed": True, "result": True}
            )

        try:
            existing_tasks = get_tasks_for_user(user_ns)
        except Exception as exc:
            self._logger.warning(
                "[todo_refresh] Cache check failed: %s - proceeding with refresh",
                exc,
            )
            return WorkflowActionResult(
                outputs={"todo_refresh_needed": True, "result": True}
            )

        if not existing_tasks:
            return WorkflowActionResult(
                outputs={"todo_refresh_needed": True, "result": True}
            )

        # Find most recent updated_at / created_at.
        from datetime import datetime, timezone

        now = datetime.now(timezone.utc)
        newest_ts: datetime | None = None
        for task in existing_tasks:
            for key in ("updated_at", "created_at"):
                raw = task.get(key)
                if raw is None:
                    continue
                if isinstance(raw, str):
                    try:
                        raw = datetime.fromisoformat(raw)
                    except (ValueError, TypeError):
                        continue
                if isinstance(raw, datetime):
                    if raw.tzinfo is None:
                        raw = raw.replace(tzinfo=timezone.utc)
                    if newest_ts is None or raw > newest_ts:
                        newest_ts = raw

        if newest_ts is None:
            return WorkflowActionResult(
                outputs={"todo_refresh_needed": True, "result": True}
            )

        age_seconds = (now - newest_ts).total_seconds()
        stale = age_seconds > self._TODO_CACHE_TTL_SECONDS
        self._logger.info(
            "[todo_refresh] Cache age %.0fs, TTL %ds -> %s",
            age_seconds,
            self._TODO_CACHE_TTL_SECONDS,
            "stale" if stale else "fresh",
        )
        return WorkflowActionResult(
            outputs={"todo_refresh_needed": stale, "result": stale}
        )

    def _action_todo_refresh_fetch_gmail(self, request: Any) -> WorkflowActionResult:
        """Fetch recent Gmail messages via the MCP gateway.

        Retrieves up to 10 recent messages using ``gmail_list_messages`` and
        then fetches full bodies for messages that look actionable (contain
        common task/todo keywords in the snippet).
        """
        data = request.data
        gateway = request.environment.gateway
        gmail_profile = data.get("gmail_profile") or getattr(
            request.environment, "default_gmail_profile", None
        )

        if not gateway:
            self._logger.warning("[todo_refresh] No gateway available")
            return WorkflowActionResult(
                outputs={"raw_gmail_messages": [], "gmail_fetch_ok": False}
            )

        if not gmail_profile:
            self._logger.warning(
                "[todo_refresh] No gmail_profile configured; skipping fetch"
            )
            return WorkflowActionResult(
                outputs={"raw_gmail_messages": [], "gmail_fetch_ok": False}
            )

        # List recent messages.
        try:
            list_result = gateway.invoke(
                "gmail_list_messages",
                {
                    "profile": gmail_profile,
                    "max_results": 10,
                    "query": "newer_than:3d",
                },
            )
            messages_list = (list_result.payload or {}).get("messages", [])
        except Exception as exc:
            self._logger.warning("[todo_refresh] gmail_list_messages failed: %s", exc)
            return WorkflowActionResult(
                outputs={"raw_gmail_messages": [], "gmail_fetch_ok": False}
            )

        if not messages_list:
            self._logger.info("[todo_refresh] No recent Gmail messages found")
            return WorkflowActionResult(
                outputs={"raw_gmail_messages": [], "gmail_fetch_ok": True}
            )

        full_messages: list[dict[str, Any]] = []
        for msg_summary in messages_list[:10]:
            msg_id = msg_summary.get("id")
            if not msg_id:
                continue
            try:
                detail_result = gateway.invoke(
                    "gmail_get_message",
                    {"profile": gmail_profile, "message_id": msg_id},
                )
                if detail_result.payload:
                    full_messages.append(detail_result.payload)
            except Exception as exc:
                self._logger.debug(
                    "[todo_refresh] gmail_get_message(%s) failed: %s", msg_id, exc
                )

        self._logger.info(
            "[todo_refresh] Fetched %d/%d Gmail messages",
            len(full_messages),
            len(messages_list),
        )
        return WorkflowActionResult(
            outputs={
                "raw_gmail_messages": full_messages,
                "gmail_fetch_ok": True,
            }
        )

    def _action_todo_refresh_extract_tasks(self, request: Any) -> WorkflowActionResult:
        """Use the LLM to extract actionable tasks from Gmail message bodies.

        Reads ``raw_gmail_messages`` from the workflow context, builds a prompt
        asking the model to identify tasks, and parses the structured JSON
        response.  Outputs ``extracted_tasks`` - a list of dicts with keys
        ``title``, ``description``, ``source_email_id``.
        """
        data = request.data
        raw_messages: list[dict[str, Any]] = data.get("raw_gmail_messages") or []

        if not raw_messages:
            self._logger.info("[todo_refresh] No messages to extract tasks from")
            return WorkflowActionResult(outputs={"extracted_tasks": []})

        # Build a digest of email contents for the LLM.
        digest_parts: list[str] = []
        for idx, msg in enumerate(raw_messages, 1):
            subject = msg.get("subject") or msg.get("headers", {}).get(
                "Subject", "(no subject)"
            )
            sender = msg.get("from") or msg.get("headers", {}).get("From", "unknown")
            body = msg.get("body") or msg.get("snippet") or ""
            # Truncate very long bodies.
            if len(body) > 2000:
                body = body[:2000] + "..."
            digest_parts.append(
                f"### Email {idx}\nFrom: {sender}\nSubject: {subject}\n\n{body}\n"
            )

        email_digest = "\n---\n".join(digest_parts)

        extraction_prompt = self._render_authoritative_prompt(
            self._TODO_REFRESH_EXTRACT_TASKS_PROMPTS,
            variables={"email_digest": email_digest},
            max_chars=12000,
            error_context="todo_refresh_extract_tasks",
            required=False,
        )
        extraction_system_prompt = self._render_authoritative_prompt(
            self._TODO_REFRESH_EXTRACT_TASKS_SYSTEM_PROMPTS,
            variables={},
            max_chars=2000,
            error_context="todo_refresh_extract_tasks_system",
            required=False,
        )
        if extraction_prompt is None or extraction_system_prompt is None:
            self._logger.warning(
                "[todo_refresh] Authoritative extraction prompt unavailable"
            )
            return WorkflowActionResult(
                outputs={
                    "extracted_tasks": [],
                    "todo_refresh_extraction_prompt_available": False,
                }
            )

        llm_client = request.environment.llm_client
        model = request.environment.model
        if not llm_client:
            self._logger.warning("[todo_refresh] No LLM client for extraction")
            return WorkflowActionResult(outputs={"extracted_tasks": []})

        try:
            llm_response = llm_client.generate(
                prompt=extraction_prompt.text,
                context=[
                    {
                        "role": "system",
                        "content": extraction_system_prompt.text,
                    },
                ],
                model=model,
            )
        except Exception as exc:
            self._logger.warning("[todo_refresh] LLM extraction failed: %s", exc)
            return WorkflowActionResult(outputs={"extracted_tasks": []})

        # Parse the JSON array from the response.
        extracted: list[dict[str, Any]] = []
        try:
            import json as _json

            text = (
                llm_response.strip()
                if isinstance(llm_response, str)
                else str(llm_response).strip()
            )
            # Strip markdown code fences if present.
            if text.startswith("```"):
                lines = text.split("\n")
                text = "\n".join(
                    lines[1:-1] if lines[-1].strip() == "```" else lines[1:]
                )
            parsed = _json.loads(text)
            if isinstance(parsed, list):
                for item in parsed:
                    if isinstance(item, dict) and item.get("title"):
                        extracted.append(
                            {
                                "title": str(item["title"]),
                                "description": str(item.get("description", "")),
                                "source_email_index": item.get("source_email_index"),
                            }
                        )
        except Exception as exc:
            self._logger.warning(
                "[todo_refresh] Failed to parse extracted tasks: %s", exc
            )

        # Log to aux_llm_calls for observability.
        aux_log = data.get("aux_llm_calls")
        if isinstance(aux_log, list):
            aux_log.append(
                {
                    "type": "todo_refresh.extract_tasks",
                    "model": model,
                    "email_count": len(raw_messages),
                    "extracted_count": len(extracted),
                }
            )

        self._logger.info(
            "[todo_refresh] Extracted %d tasks from %d emails",
            len(extracted),
            len(raw_messages),
        )
        return WorkflowActionResult(outputs={"extracted_tasks": extracted})

    def _action_todo_refresh_prioritise(self, request: Any) -> WorkflowActionResult:
        """Assign priority (low/medium/high/critical) to extracted tasks.

        If there are ≤3 tasks, uses a simple heuristic (all medium).
        For larger batches, calls the LLM to assign priorities
        contextually.
        """
        data = request.data
        extracted: list[dict[str, Any]] = data.get("extracted_tasks") or []

        if not extracted:
            return WorkflowActionResult(outputs={"prioritised_tasks": []})

        # Simple heuristic for small batches - avoids an LLM call.
        if len(extracted) <= 3:
            for task in extracted:
                task.setdefault("priority", "medium")
            return WorkflowActionResult(outputs={"prioritised_tasks": extracted})

        # Use LLM for larger batches.
        import json as _json

        task_summaries = _json.dumps(
            [
                {
                    "index": i,
                    "title": t["title"],
                    "description": t.get("description", ""),
                }
                for i, t in enumerate(extracted)
            ],
            indent=2,
        )
        prioritise_prompt = self._render_authoritative_prompt(
            self._TODO_REFRESH_PRIORITISE_PROMPTS,
            variables={"task_summaries": task_summaries},
            max_chars=8000,
            error_context="todo_refresh_prioritise",
            required=False,
        )
        prioritise_system_prompt = self._render_authoritative_prompt(
            self._TODO_REFRESH_PRIORITISE_SYSTEM_PROMPTS,
            variables={},
            max_chars=2000,
            error_context="todo_refresh_prioritise_system",
            required=False,
        )
        if prioritise_prompt is None or prioritise_system_prompt is None:
            return WorkflowActionResult(
                outputs={
                    "prioritised_tasks": extracted,
                    "todo_refresh_prioritisation_prompt_available": False,
                }
            )

        llm_client = request.environment.llm_client
        model = request.environment.model

        try:
            llm_response = llm_client.generate(
                prompt=prioritise_prompt.text,
                context=[
                    {
                        "role": "system",
                        "content": prioritise_system_prompt.text,
                    },
                ],
                model=model,
            )
            text = (
                llm_response.strip()
                if isinstance(llm_response, str)
                else str(llm_response).strip()
            )
            if text.startswith("```"):
                lines = text.split("\n")
                text = "\n".join(
                    lines[1:-1] if lines[-1].strip() == "```" else lines[1:]
                )
            parsed = _json.loads(text)
            if isinstance(parsed, list):
                priority_map = {}
                for item in parsed:
                    if isinstance(item, dict):
                        idx = item.get("index")
                        prio = item.get("priority", "medium")
                        if isinstance(idx, int) and prio in (
                            "low",
                            "medium",
                            "high",
                            "critical",
                        ):
                            priority_map[idx] = prio
                for i, task in enumerate(extracted):
                    task["priority"] = priority_map.get(i, "medium")
        except Exception as exc:
            self._logger.warning(
                "[todo_refresh] LLM prioritisation failed: %s - defaulting to medium",
                exc,
            )
            for task in extracted:
                task.setdefault("priority", "medium")

        return WorkflowActionResult(outputs={"prioritised_tasks": extracted})

    def _action_todo_refresh_summarise(self, request: Any) -> WorkflowActionResult:
        """Persist prioritised tasks via the task management service and
        produce a human-readable summary.

        Creates each task as a ``#V#task_specification`` concept with the
        appropriate priority and assignee.  Skips tasks whose titles match
        an existing pending task for this user (deduplication).
        """
        from ...services.task_management_service import (
            create_task,
            get_tasks_for_user,
        )

        data = request.data
        prioritised: list[dict[str, Any]] = data.get("prioritised_tasks") or []
        user_ns = data.get("user_namespace") or getattr(
            request.environment, "user_namespace", None
        )

        if not prioritised:
            return WorkflowActionResult(
                outputs={
                    "persisted_tasks": [],
                    "todo_summary": "No new tasks found from recent emails.",
                }
            )

        # Deduplicate against existing pending tasks.
        existing_titles: set[str] = set()
        if user_ns:
            try:
                existing = get_tasks_for_user(user_ns, status_filter="pending")
                existing_titles = {
                    (t.get("title") or "").strip().lower() for t in existing
                }
            except Exception:
                pass

        persisted: list[dict[str, Any]] = []
        skipped = 0
        for task in prioritised:
            title = (task.get("title") or "").strip()
            if not title:
                continue
            if title.lower() in existing_titles:
                skipped += 1
                continue

            try:
                result = create_task(
                    title=title,
                    description=task.get("description") or title,
                    priority=task.get("priority", "medium"),
                    assignee_concept_id=user_ns,
                    created_by_concept_id=user_ns,
                )
                persisted.append(result)
                existing_titles.add(title.lower())
            except Exception as exc:
                self._logger.warning(
                    "[todo_refresh] Failed to create task '%s': %s",
                    title,
                    exc,
                )

        # Build human-readable summary.
        summary_lines = [f"Refreshed to-do list: {len(persisted)} new task(s) created"]
        if skipped:
            summary_lines[0] += f", {skipped} duplicate(s) skipped"
        summary_lines[0] += "."
        for t in persisted:
            prio = t.get("priority", "medium")
            summary_lines.append(f"  • [{prio.upper()}] {t.get('title', 'Untitled')}")

        summary = "\n".join(summary_lines)
        self._logger.info(
            "[todo_refresh] Persisted %d tasks, skipped %d duplicates",
            len(persisted),
            skipped,
        )

        return WorkflowActionResult(
            outputs={
                "persisted_tasks": persisted,
                "todo_summary": summary,
            }
        )

    # ------------------------------------------------------------------
    # Tool-calling workflow handlers (JVNAUTOSCI-922 Phase 2)
    #
    # These handlers implement the retained explicit
    # ``#V#tool_calling_workflow``.  They operate on a shared ``data`` dict
    # (the workflow context) and return outputs that drive its state
    # transitions; they are not the ordinary-turn controller.
    #
    # Key data-dict fields consumed/produced:
    #   prompt, augmented_context (mutable list), policy_state,
    #   registry_snapshot, user/org_concept_id, model_for_stage (callable),
    #   record_llm_call (callable), emit_progress / emit_phase_transition /
    #   check_cancellation (callables), aux_llm_calls / llm_calls (mutable
    #   lists), invocations / tool_messages (mutable lists),
    #   tool_calls, tool_calls_present, iteration_count, final_response,
    #   orchestrator_result (pre-built OrchestratorResult for error exits).
    # ------------------------------------------------------------------

    def _resolve_method_catalogue_for_workflow_data(
        self,
        data: Mapping[str, Any] | MutableMapping[str, Any],
    ) -> Mapping[str, Any] | None:
        method_catalogue = data.get("method_catalogue")
        if not isinstance(method_catalogue, Mapping):
            try:
                method_catalogue = self._gateway.describe_methods()
            except Exception:
                method_catalogue = None
        if isinstance(method_catalogue, Mapping):
            if isinstance(data, MutableMapping):
                data["method_catalogue"] = method_catalogue
            return method_catalogue
        return None

    def _selected_gmail_profile_for_workflow_data(
        self,
        data: Mapping[str, Any],
        environment: Any,
    ) -> str | None:
        for candidate in (
            data.get("gmail_profile"),
            getattr(environment, "default_gmail_profile", None),
            getattr(self, "_default_gmail_profile", None),
        ):
            if isinstance(candidate, str) and candidate.strip():
                profile = candidate.strip()
                if is_unresolved_tool_argument_placeholder(profile):
                    continue
                return profile
        return None

    def _action_tool_calling_preflight_requirements(
        self, request: Any
    ) -> WorkflowActionResult:
        """Materialise workflow-owned prompt requirements before tool planning."""

        data = request.data
        prompt_for_requirements = data.get("prompt_for_requirements")
        if (
            not isinstance(prompt_for_requirements, str)
            or not prompt_for_requirements.strip()
        ):
            prompt_for_requirements = data.get("prompt")
        prompt_text = (
            prompt_for_requirements.strip()
            if isinstance(prompt_for_requirements, str)
            else ""
        )

        method_catalogue = self._resolve_method_catalogue_for_workflow_data(data)

        augmented_context = data.get("augmented_context")
        context_messages = (
            cast(Sequence[Mapping[str, Any]], augmented_context)
            if isinstance(augmented_context, Sequence)
            and not isinstance(augmented_context, (str, bytes, bytearray))
            else None
        )

        url_requirement = {
            "required": False,
            "url": None,
            "tool": None,
            "reason": "workflow_llm_owns_url_reading_decision",
        }
        prompt_requirements = self._evaluate_prompt_requirements(
            prompt_text=prompt_text,
            method_catalogue=(
                method_catalogue if isinstance(method_catalogue, Mapping) else None
            ),
            context_messages=context_messages,
            tool_invocations=(),
            url_requirement=url_requirement,
        )
        explicit_required_tools = tuple(prompt_requirements.required_tools)
        prompt_requirements = self._augment_prompt_requirements_with_turn_contract(
            evaluation=prompt_requirements,
            turn_expected_outcome_contract=self._build_turn_expected_outcome_contract_object(
                data
            ),
            method_catalogue=(
                method_catalogue if isinstance(method_catalogue, Mapping) else None
            ),
            tool_invocations=(),
        )
        contract_required_tools = [
            tool_name
            for tool_name in prompt_requirements.required_tools
            if tool_name not in explicit_required_tools
        ]

        self._store_prompt_requirement_evaluation(data, prompt_requirements)
        data["prompt_requirement_url_policy"] = dict(url_requirement)
        aux_log = data.get("aux_llm_calls")
        if isinstance(aux_log, list):
            try:
                aux_log.append(
                    annotate_python_decision_event(
                        {
                            "type": "prompt_tool_requirements_preflight",
                            "stage": "tool_plan",
                            "explicit_required_tools": list(explicit_required_tools),
                            "contract_required_tools": list(contract_required_tools),
                            "required_tools": list(prompt_requirements.required_tools),
                            "required_url_extraction_tool": (
                                prompt_requirements.required_url_extraction_tool
                            ),
                            "required_url_extraction_url": (
                                prompt_requirements.required_url_extraction_url
                            ),
                            "missing_tools": list(prompt_requirements.missing_tools),
                            "url_requirement": dict(url_requirement),
                        },
                        stage="tool_plan",
                        component="internal_mcp_orchestrator",
                        function="_action_tool_calling_preflight_requirements",
                        decision_class="prompt_requirement_inference",
                        decision_source="prompt_plus_turn_contract",
                        changed_outcome=bool(prompt_requirements.required_tools),
                        reason_code=(
                            "prompt_or_turn_contract_tool_requirement_detected"
                            if prompt_requirements.required_tools
                            else "no_prompt_or_turn_contract_tool_requirement"
                        ),
                        possible_inappropriate_python_code_use=False,
                    )
                )
            except Exception:
                pass

        outputs: dict[str, Any] = {
            "prompt_requirement_url_policy": dict(url_requirement),
            "required_prompt_tools": list(prompt_requirements.required_tools),
            "required_prompt_url_extraction_tool": (
                prompt_requirements.required_url_extraction_tool
            ),
            "required_prompt_url_extraction_url": (
                prompt_requirements.required_url_extraction_url
            ),
            "required_prompt_fetch_concept_ids": list(
                prompt_requirements.required_fetch_concept_ids
            ),
            "required_prompt_read_file_copy_ids": list(
                prompt_requirements.required_read_file_copy_ids
            ),
            "required_prompt_scholarly_representation_for_file_copy_ids": list(
                prompt_requirements.required_scholarly_representation_file_copy_ids
            ),
            "required_prompt_create_type_name": (
                prompt_requirements.required_create_type_name
            ),
            "missing_prompt_tools": list(prompt_requirements.missing_tools),
            "missing_prompt_fetch_concept_ids": list(
                prompt_requirements.missing_fetch_concept_ids
            ),
            "missing_prompt_read_file_copy_ids": list(
                prompt_requirements.missing_read_file_copy_ids
            ),
            "missing_prompt_scholarly_representation_for_file_copy_ids": list(
                prompt_requirements.missing_scholarly_representation_file_copy_ids
            ),
            "missing_tool_call_retry_reason_override": (
                prompt_requirements.missing_retry_reason
            ),
            "prompt_requirements_preflight_completed": True,
            "result": True,
        }
        if isinstance(method_catalogue, Mapping):
            outputs["method_catalogue"] = method_catalogue
        if isinstance(aux_log, list):
            outputs["aux_llm_calls"] = aux_log
        return WorkflowActionResult(outputs=outputs)

    @staticmethod
    def _merge_action_outputs_into_workflow_data(
        data: MutableMapping[str, Any],
        outputs: Mapping[str, Any],
    ) -> None:
        for key, value in outputs.items():
            if isinstance(key, str):
                data[key] = value

    def _materialise_tool_calling_orchestrator_result(
        self,
        data: MutableMapping[str, Any],
        orchestrator_result: Any,
    ) -> None:
        if not isinstance(orchestrator_result, OrchestratorResult):
            return
        data["final_response"] = orchestrator_result.response_text
        data["current_response"] = orchestrator_result.response_text

        invocations = data.get("invocations")
        if isinstance(invocations, list):
            invocations.extend(
                dict(item)
                for item in orchestrator_result.tool_invocations
                if isinstance(item, Mapping)
            )
        else:
            data["invocations"] = [
                dict(item)
                for item in orchestrator_result.tool_invocations
                if isinstance(item, Mapping)
            ]

        tool_messages = data.get("tool_messages")
        if isinstance(tool_messages, list):
            tool_messages.extend(
                dict(item)
                for item in orchestrator_result.extra_messages
                if isinstance(item, Mapping)
            )
        else:
            data["tool_messages"] = [
                dict(item)
                for item in orchestrator_result.extra_messages
                if isinstance(item, Mapping)
            ]

        aux_llm_calls = data.get("aux_llm_calls")
        if isinstance(aux_llm_calls, list):
            aux_llm_calls.extend(
                dict(item)
                for item in orchestrator_result.aux_llm_calls
                if isinstance(item, Mapping)
            )
        else:
            data["aux_llm_calls"] = [
                dict(item)
                for item in orchestrator_result.aux_llm_calls
                if isinstance(item, Mapping)
            ]

        llm_calls = data.get("llm_calls")
        if isinstance(llm_calls, list):
            llm_calls.extend(
                dict(item)
                for item in orchestrator_result.llm_calls
                if isinstance(item, Mapping)
            )
        else:
            data["llm_calls"] = [
                dict(item)
                for item in orchestrator_result.llm_calls
                if isinstance(item, Mapping)
            ]

    @staticmethod
    def _build_tool_calling_state_outputs(
        data: Mapping[str, Any],
        **extra_outputs: Any,
    ) -> dict[str, Any]:
        outputs: dict[str, Any] = {
            "final_response": data.get("final_response"),
            "current_response": data.get("current_response")
            or data.get("final_response"),
            "iteration_count": data.get("iteration_count"),
        }
        invocations = data.get("invocations")
        if isinstance(invocations, list):
            outputs["invocations"] = [
                dict(item) for item in invocations if isinstance(item, Mapping)
            ]
        tool_messages = data.get("tool_messages")
        if isinstance(tool_messages, list):
            outputs["tool_messages"] = [
                dict(item) for item in tool_messages if isinstance(item, Mapping)
            ]
        aux_llm_calls = data.get("aux_llm_calls")
        if isinstance(aux_llm_calls, list):
            outputs["aux_llm_calls"] = [
                dict(item) for item in aux_llm_calls if isinstance(item, Mapping)
            ]
        llm_calls = data.get("llm_calls")
        if isinstance(llm_calls, list):
            outputs["llm_calls"] = [
                dict(item) for item in llm_calls if isinstance(item, Mapping)
            ]
        for key in (
            "required_prompt_tools",
            "required_prompt_fetch_concept_ids",
            "required_prompt_read_file_copy_ids",
            "required_prompt_scholarly_representation_for_file_copy_ids",
            "missing_prompt_tools",
            "missing_prompt_fetch_concept_ids",
            "missing_prompt_read_file_copy_ids",
            "missing_prompt_scholarly_representation_for_file_copy_ids",
            "llm_allowed_tools",
            "tool_call_validation_errors",
            "tool_call_validation_warnings",
            "tool_call_validation_unavailable_tools",
            "tool_call_validation_diagnostics",
            "tool_call_validation_failed_tools",
            "tool_call_validation_required_failed_tools",
            "tool_call_validation_required_tool_errors",
            "tool_call_repaired_calls",
            "tool_payload_support_events",
        ):
            value = data.get(key)
            if isinstance(value, list):
                outputs[key] = list(value)
        for key in (
            "prompt_requirement_url_policy",
            "tool_plan_context_lineage",
            "tool_follow_up_context_lineage",
            "tool_call_repair_decision",
            "workflow_step_output_contract",
        ):
            value = data.get(key)
            if isinstance(value, Mapping):
                outputs[key] = {
                    str(item_key): item_value
                    for item_key, item_value in value.items()
                    if isinstance(item_key, str)
                }
        for key in (
            "required_prompt_url_extraction_tool",
            "required_prompt_url_extraction_url",
            "required_prompt_create_type_name",
            "missing_tool_call_retry_reason_override",
            "raw_tool_plan_text",
            "tool_call_repair_outcome",
            "tool_call_repair_stop_reason",
        ):
            value = data.get(key)
            if isinstance(value, str) and value.strip():
                outputs[key] = value
        for key in (
            "tool_call_repair_required",
            "tool_call_validation_error_pending",
            "tool_call_repair_attempted",
            "tool_call_repair_succeeded",
        ):
            if isinstance(data.get(key), bool):
                outputs[key] = bool(data.get(key))
        for key in (
            "tool_call_repair_attempts",
            "tool_call_repair_budget",
            "tool_call_repair_remaining",
        ):
            value = data.get(key)
            if isinstance(value, int):
                outputs[key] = int(value)
        if isinstance(data.get("prompt_requirements_preflight_completed"), bool):
            outputs["prompt_requirements_preflight_completed"] = bool(
                data.get("prompt_requirements_preflight_completed")
            )
        for key, value in extra_outputs.items():
            outputs[key] = value
        return outputs

    def _action_tool_calling_respond(self, request: Any) -> WorkflowActionResult:
        """Run the authoritative composite tool-calling contract in one action."""

        data = request.data

        plan_result = self._action_tool_calling_plan(request)
        self._merge_action_outputs_into_workflow_data(data, plan_result.outputs)
        orchestrator_result = data.get("orchestrator_result")
        if isinstance(orchestrator_result, OrchestratorResult):
            self._materialise_tool_calling_orchestrator_result(
                data, orchestrator_result
            )
            return WorkflowActionResult(
                outputs=self._build_tool_calling_state_outputs(
                    data,
                    orchestrator_result=orchestrator_result,
                    tool_calls_present=False,
                    direct_response=True,
                    result=False,
                )
            )
        if not plan_result.ok:
            return plan_result
        if bool(data.get("direct_response")) or not bool(
            data.get("tool_calls_present")
        ):
            return WorkflowActionResult(
                outputs=self._build_tool_calling_state_outputs(
                    data,
                    tool_calls_present=bool(data.get("tool_calls_present")),
                    direct_response=bool(data.get("direct_response")),
                    result=data.get("result"),
                )
            )

        while True:
            validate_result = self._action_tool_calling_validate(request)
            self._merge_action_outputs_into_workflow_data(data, validate_result.outputs)
            orchestrator_result = data.get("orchestrator_result")
            if isinstance(orchestrator_result, OrchestratorResult):
                self._materialise_tool_calling_orchestrator_result(
                    data,
                    orchestrator_result,
                )
                return WorkflowActionResult(
                    outputs=self._build_tool_calling_state_outputs(
                        data,
                        orchestrator_result=orchestrator_result,
                        tool_calls_present=False,
                        direct_response=True,
                        result=False,
                    )
                )
            if not validate_result.ok:
                return validate_result
            if bool(data.get("tool_call_repair_required")):
                repair_result = self._action_tool_calling_repair(request)
                self._merge_action_outputs_into_workflow_data(
                    data,
                    repair_result.outputs,
                )
                orchestrator_result = data.get("orchestrator_result")
                if isinstance(orchestrator_result, OrchestratorResult):
                    self._materialise_tool_calling_orchestrator_result(
                        data,
                        orchestrator_result,
                    )
                    return WorkflowActionResult(
                        outputs=self._build_tool_calling_state_outputs(
                            data,
                            orchestrator_result=orchestrator_result,
                            tool_calls_present=False,
                            direct_response=True,
                            result=False,
                        )
                    )
                if not repair_result.ok:
                    return repair_result
                continue
            if not bool(data.get("tool_calls_validated")):
                return WorkflowActionResult(
                    status="failed",
                    error="tool_calls_not_validated",
                    outputs={"result": False},
                )

            execute_result = self._action_tool_calling_execute(request)
            self._merge_action_outputs_into_workflow_data(data, execute_result.outputs)
            if not execute_result.ok:
                return execute_result

            synthesiser_context_result = self._run_synthesiser_context_prep_stage(
                request
            )
            if not synthesiser_context_result.ok:
                return synthesiser_context_result

            backfill_result = self._action_tool_calling_backfill(request)
            self._merge_action_outputs_into_workflow_data(data, backfill_result.outputs)
            if not backfill_result.ok:
                return backfill_result
            if bool(data.get("more_tool_calls")):
                continue
            return WorkflowActionResult(
                outputs=self._build_tool_calling_state_outputs(
                    data,
                    tool_calls_present=bool(data.get("tool_calls_present")),
                    direct_response=bool(data.get("direct_response")),
                    result=data.get("result"),
                )
            )

    def _run_synthesiser_context_prep_stage(
        self,
        request: Any,
    ) -> WorkflowActionResult:
        """Run the registered synthesiser prep action for composite callers."""

        data = request.data
        if not isinstance(data, dict):
            return WorkflowActionResult(
                status="failed",
                error="synthesiser_context_prep_requires_mutable_workflow_data",
                outputs={"result": False},
            )

        registry = getattr(self, "_action_registry", None)
        if not isinstance(registry, ActionRegistry) or not registry.has(
            SYNTHESISER_CONTEXT_PREP_ACTION_ID
        ):
            registry = get_shared_durable_action_registry()

        return registry.execute(
            SYNTHESISER_CONTEXT_PREP_ACTION_ID,
            inputs={},
            context=data,
            env=request.environment,
            prompt_contract={
                "validation_policy": "fail",
                "requested_prompt_concept_ids": [
                    SYNTHESISER_CONTEXT_FRAMING_PROMPT_CONCEPT_ID
                ],
                "resolved_prompt_concept_id": (
                    SYNTHESISER_CONTEXT_FRAMING_PROMPT_CONCEPT_ID
                ),
                "metadata": {
                    "prompt_source": "composite_tool_calling_runtime",
                    "workflow_id": TOOL_CALLING_WORKFLOW_ID,
                    "state_id": "synthesiser_context_prep",
                },
            },
            workflow_id=TOOL_CALLING_WORKFLOW_ID,
            workflow_state_id="synthesiser_context_prep",
        )

    def _action_tool_calling_plan(self, request: Any) -> WorkflowActionResult:
        """Phase 1 of tool calling: initial LLM call + missing-tool-call recovery.

        Determines structured vs legacy path, makes the LLM call, interprets
        the response, and runs the missing-tool-call recovery workflow if no
        valid tool calls are found.

        Outputs:
            tool_calls_present (bool): True if tool calls were extracted.
            direct_response (bool): True if no tools needed (plain text).
            response (str): The raw LLM response text.
            tool_calls (list | None): Extracted tool-call dicts.
            use_structured (bool): Whether structured calling was used.
            orchestrator_result (OrchestratorResult | None): Pre-built error
                result if a parse error terminates the flow early.
        """
        data = cast(MutableMapping[str, Any], request.data)
        env = request.environment
        llm_client = env.llm_client
        prompt = data["prompt"]
        augmented_context = data["augmented_context"]
        policy_state = data["policy_state"]
        registry_snapshot = data.get("registry_snapshot")
        user_concept_id = data.get("user_concept_id")
        org_concept_id = data.get("org_concept_id")
        model_for_stage = data["model_for_stage"]

        def _data_sequence_or_none(key: str) -> Sequence[Any] | None:
            value = data.get(key)
            if isinstance(value, Sequence) and not isinstance(
                value, (str, bytes, bytearray)
            ):
                return value
            return None

        def _data_list(key: str) -> list[Any]:
            value = data.get(key)
            return value.copy() if isinstance(value, list) else []

        record_llm_call = data["record_llm_call"]
        emit_progress_raw = data.get("emit_progress")
        emit_progress_cb: Callable[[Mapping[str, Any]], None] | None = (
            cast(Callable[[Mapping[str, Any]], None], emit_progress_raw)
            if callable(emit_progress_raw)
            else None
        )
        emit_phase_transition = data.get("emit_phase_transition")
        aux_llm_calls = data["aux_llm_calls"]
        llm_calls = data["llm_calls"]
        repeat_iteration = bool(data.get("completion_gate_repeat_iteration"))
        if repeat_iteration:
            repeat_attempt = self._coerce_non_negative_int(
                data.get("completion_gate_loop_attempts"),
                default=0,
                max_value=20,
            )
            repeat_max_attempts = self._coerce_non_negative_int(
                data.get("completion_gate_loop_max_attempts"),
                default=int(getattr(self, "_completion_gate_loop_max_attempts", 1)),
                max_value=20,
            )
            repeat_reason = data.get("completion_gate_loop_retry_reason")
            repeat_reason_text = (
                str(repeat_reason).strip() if isinstance(repeat_reason, str) else ""
            )
            if isinstance(augmented_context, list):
                loop_note = (
                    "Previous tool-calling iteration did not satisfy required effects. "
                    f"Repeat attempt {repeat_attempt} of {repeat_max_attempts}. "
                    "Use this context to execute remaining actions and avoid repeating "
                    "no-op or already-failed calls."
                )
                if repeat_reason_text:
                    loop_note = f"{loop_note} Prior gate reason: {repeat_reason_text}"
                augmented_context.append({"role": "system", "content": loop_note})
            if isinstance(aux_llm_calls, list):
                try:
                    aux_llm_calls.append(
                        {
                            "type": "completion_gate_repeat_iteration",
                            "attempt": repeat_attempt,
                            "max_attempts": repeat_max_attempts,
                            "retry_reason": repeat_reason_text,
                        }
                    )
                except Exception:
                    pass
            # Consume repeat marker for this planning pass.
            data["completion_gate_repeat_iteration"] = False
        missing_tool_call_retry_attempts = self._coerce_non_negative_int(
            data.get("missing_tool_call_retry_attempts"),
            default=0,
            max_value=20,
        )
        missing_tool_call_retry_budget = self._coerce_non_negative_int(
            data.get("missing_tool_call_retry_budget"),
            default=self._max_missing_tool_call_retries_per_turn,
            max_value=20,
        )
        missing_tool_call_retry_suppressed = bool(
            data.get("missing_tool_call_retry_suppressed")
        )
        missing_tool_call_retry_stop_reason = (
            str(data.get("missing_tool_call_retry_stop_reason")).strip()
            if isinstance(data.get("missing_tool_call_retry_stop_reason"), str)
            else None
        )
        missing_tool_call_recovery_outcome = (
            str(data.get("missing_tool_call_recovery_outcome")).strip()
            if isinstance(data.get("missing_tool_call_recovery_outcome"), str)
            else None
        )
        agent_test_plan_result = self._agent_test_local_relation_plan_result(
            request=request,
            data=data,
            missing_tool_call_retry_attempts=missing_tool_call_retry_attempts,
            missing_tool_call_retry_budget=missing_tool_call_retry_budget,
            missing_tool_call_retry_suppressed=missing_tool_call_retry_suppressed,
            missing_tool_call_retry_stop_reason=missing_tool_call_retry_stop_reason,
            missing_tool_call_recovery_outcome=missing_tool_call_recovery_outcome,
        )
        if agent_test_plan_result is not None:
            return agent_test_plan_result
        method_catalogue_for_requirements = (
            self._resolve_method_catalogue_for_workflow_data(data)
        )
        selected_gmail_profile_for_retry = (
            self._selected_gmail_profile_for_workflow_data(data, env)
        )
        invocations_for_requirements = cast(
            Sequence[Mapping[str, Any]], _data_sequence_or_none("invocations") or ()
        )

        tool_plan_stage_messages = self._build_turn_expected_outcome_stage_messages(
            data=data,
            stage="tool_call",
        )
        tool_plan_context, tool_plan_context_telemetry = self._build_stage_llm_context(
            base_context=augmented_context,
            stage="tool_call",
            base_context_source="augmented_context",
            stage_messages=tool_plan_stage_messages,
        )
        self._attach_memory_context_lineage(
            tool_plan_context_telemetry,
            turn_memory_context_state=self._copy_string_key_mapping(
                data.get("turn_memory_context_state")
            ),
        )

        allowed_tool_names = {
            str(tool_name).strip().lower()
            for tool_name in (data.get("llm_allowed_tools") or [])
            if isinstance(tool_name, str) and str(tool_name).strip()
        }

        prompt_for_requirements = data.get("prompt_for_requirements")
        if (
            not isinstance(prompt_for_requirements, str)
            or not prompt_for_requirements.strip()
        ):
            prompt_for_requirements = prompt
        prompt_requirement_url_policy = data.get("prompt_requirement_url_policy")

        prompt_requirements = self._evaluate_prompt_requirements(
            prompt_text=prompt_for_requirements,
            method_catalogue=(
                method_catalogue_for_requirements
                if isinstance(method_catalogue_for_requirements, Mapping)
                else None
            ),
            context_messages=tool_plan_context,
            tool_invocations=invocations_for_requirements,
            url_requirement=(
                prompt_requirement_url_policy
                if isinstance(prompt_requirement_url_policy, Mapping)
                else None
            ),
        )
        allowed_tools_sequence = _data_sequence_or_none("llm_allowed_tools")
        allowed_tools_tuple = (
            tuple(allowed_tools_sequence)
            if allowed_tools_sequence is not None
            else None
        )
        prompt_requirements = self._augment_prompt_requirements_with_turn_contract(
            evaluation=prompt_requirements,
            turn_expected_outcome_contract=self._build_turn_expected_outcome_contract_object(
                data
            ),
            method_catalogue=(
                method_catalogue_for_requirements
                if isinstance(method_catalogue_for_requirements, Mapping)
                else None
            ),
            allowed_tools=allowed_tools_tuple,
            tool_invocations=invocations_for_requirements,
        )
        prompt_requirements = self._merge_prompt_requirements_with_existing_tool_policy(
            data=data,
            evaluation=prompt_requirements,
            method_catalogue=(
                method_catalogue_for_requirements
                if isinstance(method_catalogue_for_requirements, Mapping)
                else None
            ),
            tool_invocations=invocations_for_requirements,
        )
        self._store_prompt_requirement_evaluation(data, prompt_requirements)
        allowed_tool_names = {
            str(tool_name).strip().lower()
            for tool_name in (data.get("llm_allowed_tools") or [])
            if isinstance(tool_name, str) and str(tool_name).strip()
        }
        required_prompt_tools = list(prompt_requirements.required_tools)
        missing_required_tools_for_retry = self._missing_required_tools_for_retry(
            required_tools=required_prompt_tools,
            missing_tools=_data_list("missing_prompt_tools"),
            tool_invocations=invocations_for_requirements,
        )
        data["tool_plan_context_lineage"] = dict(tool_plan_context_telemetry)

        # Emit planning phase.
        if callable(emit_phase_transition):
            emit_phase_transition(
                self.PHASE_TOOL_PLAN,
            )

        # Determine structured vs legacy calling.
        use_structured = (
            hasattr(llm_client, "generate_with_tools")
            and hasattr(llm_client, "_should_use_structured_calling")
            and llm_client._should_use_structured_calling()
        )
        if policy_state.enabled and policy_state.policy:
            use_structured = True

        response = ""
        tool_calls = None
        has_valid_tool_call = False
        tool_call_parse_error: ToolCallParsingError | None = None
        interpretation = None
        structured_tool_continuation: Mapping[str, Any] | None = None
        timeout_override_sec = _conversation_turn_llm_timeout_override_sec_from_data(
            data
        )
        requested_model_parameters = (
            dict(data["requested_model_parameters"])
            if isinstance(data.get("requested_model_parameters"), Mapping)
            else None
        )

        if use_structured:
            self._logger.debug("[mcp_orchestrator] Using structured tool calling path")
            try:
                tool_call_model = model_for_stage("tool_call")
                tool_definitions = self._convert_mcp_tools_to_structured_definitions(
                    method_catalogue=(
                        method_catalogue_for_requirements
                        if isinstance(method_catalogue_for_requirements, Mapping)
                        else None
                    )
                )
                if allowed_tool_names:
                    tool_definitions = [
                        definition
                        for definition in tool_definitions
                        if isinstance(getattr(definition, "name", None), str)
                        and getattr(definition, "name").strip().lower()
                        in allowed_tool_names
                    ]
                llm_response, tool_call_model, _ = self._run_llm_with_tools_fallbacks(
                    stage="tool_call",
                    prompt=prompt,
                    context=tool_plan_context,
                    tool_definitions=tool_definitions,
                    default_client=llm_client,
                    default_model=tool_call_model,
                    default_model_parameters=requested_model_parameters,
                    policy_state=policy_state,
                    registry_snapshot=registry_snapshot,
                    user_concept_id=user_concept_id,
                    org_concept_id=org_concept_id,
                    llm_calls_log=llm_calls,
                    aux_log=aux_llm_calls,
                    record_llm_call=record_llm_call,
                    emit_progress=emit_progress_cb,
                    workflow_action_id=request.action_id,
                    method_catalogue=(
                        method_catalogue_for_requirements
                        if isinstance(method_catalogue_for_requirements, Mapping)
                        else None
                    ),
                    required_prompt_tools=required_prompt_tools,
                    context_telemetry=tool_plan_context_telemetry,
                    authored_tool_names=(
                        tuple(sorted(allowed_tool_names))
                        if request.action_id == "llm.action"
                        else ()
                    ),
                    prefer_default_model=bool(data.get("prefer_default_model")),
                    timeout_override_sec=timeout_override_sec,
                    workflow_stage_id="tool_plan",
                    workflow_id=(
                        request.workflow_id
                        if isinstance(getattr(request, "workflow_id", None), str)
                        else None
                    ),
                )
                if llm_response.tool_calls:
                    if llm_response.continuation is not None:
                        structured_tool_continuation = (
                            llm_response.continuation.to_mapping()
                        )
                    response = llm_response.text_response or ""
                    tool_calls = [
                        {
                            self._ACTION_FIELD: self._CALL_ACTION,
                            self._TOOL_FIELD: tc.tool_name,
                            self._PAYLOAD_FIELD: tc.payload,
                            "_call_id": tc.call_id,
                        }
                        for tc in llm_response.tool_calls
                    ]
                    has_valid_tool_call = True
                else:
                    response = llm_response.text_response
                    tool_calls = None
                    has_valid_tool_call = False
            except StructuredToolTransportError:
                # A known transport mismatch is an inspectable support-layer
                # blocker.  Dropping tools and entering the legacy planner
                # would hide the real failure and repeat doomed work.
                raise
            except Exception as exc:
                self._logger.warning(
                    "[mcp_orchestrator] Structured calling failed, falling back to legacy: %s",
                    exc,
                )
                use_structured = False

        if not use_structured:
            tool_call_model = model_for_stage("tool_call")
            response, tool_call_model, _ = self._run_llm_with_fallbacks(
                stage="tool_call",
                prompt=prompt,
                context=tool_plan_context,
                default_client=llm_client,
                default_model=tool_call_model,
                default_model_parameters=requested_model_parameters,
                policy_state=policy_state,
                registry_snapshot=registry_snapshot,
                user_concept_id=user_concept_id,
                org_concept_id=org_concept_id,
                llm_calls_log=llm_calls,
                aux_log=aux_llm_calls,
                record_llm_call=record_llm_call,
                emit_progress=emit_progress_cb,
                context_telemetry=tool_plan_context_telemetry,
                prefer_default_model=bool(data.get("prefer_default_model")),
                timeout_override_sec=timeout_override_sec,
                workflow_stage_id="tool_plan",
            )
            tool_calls = None
            has_valid_tool_call = False

        # Interpret response (legacy path only).
        if not use_structured:
            interpretation = self._interpret_model_turn(response)
            response = interpretation.response_text
            tool_calls = interpretation.tool_calls
            tool_call_parse_error = interpretation.tool_call_parse_error
            has_valid_tool_call = bool(tool_calls)

        # Missing-tool-call recovery.
        if not has_valid_tool_call:
            recovery_data = self._run_missing_tool_call_recovery_workflow(
                request=request,
                environment=env,
                data=data,
                response_text=(
                    response if isinstance(response, str) else str(response)
                ),
                interpretation=interpretation,
                use_structured=use_structured,
                tool_call_parse_error=tool_call_parse_error,
                tool_calls=tool_calls,
                default_model=tool_call_model,
            )
            if recovery_data is not None:
                recovery_aux_llm_calls = recovery_data.get("aux_llm_calls")
                if (
                    isinstance(aux_llm_calls, list)
                    and isinstance(recovery_aux_llm_calls, list)
                    and recovery_aux_llm_calls is not aux_llm_calls
                ):
                    aux_llm_calls.extend(
                        entry
                        for entry in recovery_aux_llm_calls
                        if isinstance(entry, Mapping)
                    )
                response = recovery_data.get("response_text", response)
                interpretation = recovery_data.get("interpretation", interpretation)
                tool_calls = recovery_data.get("tool_calls", tool_calls)
                tool_call_parse_error = recovery_data.get(
                    "tool_call_parse_error", tool_call_parse_error
                )
                missing_tool_call_retry_attempts = self._coerce_non_negative_int(
                    recovery_data.get(
                        "missing_tool_call_retry_attempts",
                        missing_tool_call_retry_attempts,
                    ),
                    default=missing_tool_call_retry_attempts,
                    max_value=20,
                )
                missing_tool_call_retry_budget = self._coerce_non_negative_int(
                    recovery_data.get(
                        "missing_tool_call_retry_budget",
                        missing_tool_call_retry_budget,
                    ),
                    default=missing_tool_call_retry_budget,
                    max_value=20,
                )
                missing_tool_call_retry_suppressed = bool(
                    recovery_data.get("missing_tool_call_retry_suppressed")
                )
                missing_tool_call_retry_stop_reason = (
                    str(
                        recovery_data.get("missing_tool_call_retry_stop_reason")
                    ).strip()
                    if isinstance(
                        recovery_data.get("missing_tool_call_retry_stop_reason"), str
                    )
                    else None
                )
                missing_tool_call_recovery_outcome = (
                    str(recovery_data.get("missing_tool_call_recovery_outcome")).strip()
                    if isinstance(
                        recovery_data.get("missing_tool_call_recovery_outcome"), str
                    )
                    else None
                )
                has_valid_tool_call = bool(tool_calls)
            if not has_valid_tool_call:
                parent_forced_tool_calls = self._infer_missing_tool_call_retry_tool_calls(
                    tool_plan_context,
                    user_prompt=prompt,
                    turn_expected_outcome_contract=(
                        self._build_turn_expected_outcome_contract_object(data)
                    ),
                    workflow_required_effects_contract=(
                        data.get("workflow_required_effects_contract")
                        if isinstance(
                            data.get("workflow_required_effects_contract"), Mapping
                        )
                        else None
                    ),
                    workflow_required_effects_contract_source=(
                        str(
                            data.get("workflow_required_effects_contract_source")
                        ).strip()
                        if isinstance(
                            data.get("workflow_required_effects_contract_source"), str
                        )
                        and str(
                            data.get("workflow_required_effects_contract_source")
                        ).strip()
                        else None
                    ),
                    missing_required_tools=missing_required_tools_for_retry,
                    missing_required_fetch_concept_ids=_data_list(
                        "missing_prompt_fetch_concept_ids"
                    ),
                    missing_required_read_file_copy_ids=_data_list(
                        "missing_prompt_read_file_copy_ids"
                    ),
                    missing_required_scholarly_representation_file_copy_ids=_data_list(
                        "missing_prompt_scholarly_representation_for_file_copy_ids"
                    ),
                    required_create_type_name=(
                        str(data.get("required_prompt_create_type_name")).strip()
                        if isinstance(data.get("required_prompt_create_type_name"), str)
                        and str(data.get("required_prompt_create_type_name")).strip()
                        else None
                    ),
                    required_url_extraction_url=(
                        str(data.get("required_prompt_url_extraction_url")).strip()
                        if isinstance(
                            data.get("required_prompt_url_extraction_url"), str
                        )
                        and str(data.get("required_prompt_url_extraction_url")).strip()
                        else None
                    ),
                    user_concept_id=(
                        str(data.get("user_concept_id")).strip()
                        if isinstance(data.get("user_concept_id"), str)
                        and str(data.get("user_concept_id")).strip()
                        else None
                    ),
                    tool_argument_defaults=(
                        data.get("tool_argument_defaults")
                        if isinstance(data.get("tool_argument_defaults"), Mapping)
                        else None
                    ),
                    workflow_discovery_result=(
                        data.get("workflow_discovery_result")
                        if isinstance(data.get("workflow_discovery_result"), Mapping)
                        else None
                    ),
                    workflow_execute_inputs=self._build_turn_launchability_probe_inputs(
                        prompt_text=str(
                            data.get("user_prompt") or data.get("prompt") or ""
                        ).strip(),
                        augmented_context=tool_plan_context,
                        workflow_discovery_result=(
                            data.get("workflow_discovery_result")
                            if isinstance(
                                data.get("workflow_discovery_result"), Mapping
                            )
                            else None
                        ),
                        continuation_context=(
                            data.get("continuation_context")
                            if isinstance(data.get("continuation_context"), Mapping)
                            else None
                        ),
                        user_namespace=getattr(env, "user_namespace", None),
                        user_concept_id=(
                            str(data.get("user_concept_id")).strip()
                            if isinstance(data.get("user_concept_id"), str)
                            and str(data.get("user_concept_id")).strip()
                            else None
                        ),
                        org_concept_id=(
                            str(data.get("org_concept_id")).strip()
                            if isinstance(data.get("org_concept_id"), str)
                            and str(data.get("org_concept_id")).strip()
                            else None
                        ),
                        gmail_profile=(
                            str(data.get("gmail_profile")).strip()
                            if isinstance(data.get("gmail_profile"), str)
                            and str(data.get("gmail_profile")).strip()
                            else None
                        ),
                        base_data=data if isinstance(data, Mapping) else None,
                    ),
                    method_catalogue=(
                        method_catalogue_for_requirements
                        if isinstance(method_catalogue_for_requirements, Mapping)
                        else None
                    ),
                    selected_gmail_profile=selected_gmail_profile_for_retry,
                    user_namespace=getattr(env, "user_namespace", None),
                    conversation_session_id=(
                        str(data.get("conversation_session_id")).strip()
                        if isinstance(data.get("conversation_session_id"), str)
                        and str(data.get("conversation_session_id")).strip()
                        else None
                    ),
                    turn_id=(
                        str(data.get("turn_id")).strip()
                        if isinstance(data.get("turn_id"), str)
                        and str(data.get("turn_id")).strip()
                        else None
                    ),
                )
                if parent_forced_tool_calls:
                    import json

                    public_parent_forced_tool_calls = (
                        self._strip_retry_tool_call_internal_metadata(
                            parent_forced_tool_calls
                        )
                    )
                    retry_binding_sources = (
                        self._summarise_retry_tool_call_binding_sources(
                            parent_forced_tool_calls
                        )
                    )
                    tool_calls = public_parent_forced_tool_calls
                    tool_call_parse_error = None
                    response = (
                        json.dumps(public_parent_forced_tool_calls[0])
                        if len(public_parent_forced_tool_calls) == 1
                        else json.dumps(public_parent_forced_tool_calls)
                    )
                    missing_tool_call_retry_suppressed = False
                    missing_tool_call_retry_stop_reason = None
                    missing_tool_call_recovery_outcome = (
                        "retry_succeeded_parent_fallback"
                    )
                    has_valid_tool_call = True
                    if isinstance(aux_llm_calls, list):
                        try:
                            aux_llm_calls.append(
                                annotate_python_decision_event(
                                    {
                                        "type": "missing_tool_call_retry",
                                        "path": (
                                            "structured" if use_structured else "legacy"
                                        ),
                                        "mechanism": "structured_parent_fallback",
                                        "stage": "response",
                                        "retry_reason": (
                                            data.get("missing_tool_call_retry_reason")
                                            or ""
                                        ),
                                        "response_preview": (
                                            response[:800]
                                            if isinstance(response, str)
                                            else str(response)[:800]
                                        ),
                                        "retry_binding_sources": retry_binding_sources,
                                    },
                                    stage="missing_tool_recovery",
                                    component="internal_mcp_orchestrator",
                                    function="_action_tool_calling_plan",
                                    decision_class="missing_tool_call_retry",
                                    decision_source="structured_retry_parent_fallback",
                                    changed_outcome=True,
                                    reason_code="structured_tool_call_replayed",
                                    possible_inappropriate_python_code_use=False,
                                )
                            )
                        except Exception:
                            pass

        data_updates = cast(MutableMapping[str, Any], data)
        data_updates["missing_tool_call_retry_attempts"] = (
            missing_tool_call_retry_attempts
        )
        data_updates["missing_tool_call_retry_budget"] = missing_tool_call_retry_budget
        data_updates["missing_tool_call_retry_suppressed"] = (
            missing_tool_call_retry_suppressed
        )
        data_updates["missing_tool_call_retry_stop_reason"] = (
            missing_tool_call_retry_stop_reason
        )
        data_updates["missing_tool_call_recovery_outcome"] = (
            missing_tool_call_recovery_outcome
        )
        missing_tool_call_retry_remaining = max(
            0, missing_tool_call_retry_budget - missing_tool_call_retry_attempts
        )

        # Determine next state.
        if has_valid_tool_call:
            return WorkflowActionResult(
                outputs={
                    "tool_calls_present": True,
                    "direct_response": False,
                    "response": response,
                    "tool_calls": tool_calls,
                    "use_structured": use_structured,
                    "tool_call_model": tool_call_model,
                    "structured_tool_continuation": structured_tool_continuation,
                    "missing_tool_call_retry_attempts": missing_tool_call_retry_attempts,
                    "missing_tool_call_retry_budget": missing_tool_call_retry_budget,
                    "missing_tool_call_retry_remaining": missing_tool_call_retry_remaining,
                    "missing_tool_call_retry_suppressed": missing_tool_call_retry_suppressed,
                    "missing_tool_call_retry_stop_reason": missing_tool_call_retry_stop_reason,
                    "missing_tool_call_recovery_outcome": missing_tool_call_recovery_outcome,
                    "result": True,
                }
            )

        # No tool calls — direct response or error.
        if tool_call_parse_error is not None:
            build_error = data.get("build_parse_error_result")
            if callable(build_error):
                error_result = build_error(tool_call_parse_error)
                return WorkflowActionResult(
                    outputs={
                        "tool_calls_present": False,
                        "direct_response": True,
                        "orchestrator_result": error_result,
                        "missing_tool_call_retry_attempts": missing_tool_call_retry_attempts,
                        "missing_tool_call_retry_budget": missing_tool_call_retry_budget,
                        "missing_tool_call_retry_remaining": missing_tool_call_retry_remaining,
                        "missing_tool_call_retry_suppressed": missing_tool_call_retry_suppressed,
                        "missing_tool_call_retry_stop_reason": missing_tool_call_retry_stop_reason,
                        "missing_tool_call_recovery_outcome": missing_tool_call_recovery_outcome,
                        "result": False,
                    }
                )

        safe_direct_response = self._sanitise_user_visible_action_output(
            response if isinstance(response, str) else str(response),
            aux_log=aux_llm_calls if isinstance(aux_llm_calls, list) else None,
            source_stage="tool_calling.plan",
        )
        return WorkflowActionResult(
            outputs={
                "tool_calls_present": False,
                "direct_response": True,
                "final_response": safe_direct_response,
                "missing_tool_call_retry_attempts": missing_tool_call_retry_attempts,
                "missing_tool_call_retry_budget": missing_tool_call_retry_budget,
                "missing_tool_call_retry_remaining": missing_tool_call_retry_remaining,
                "missing_tool_call_retry_suppressed": missing_tool_call_retry_suppressed,
                "missing_tool_call_retry_stop_reason": missing_tool_call_retry_stop_reason,
                "missing_tool_call_recovery_outcome": missing_tool_call_recovery_outcome,
                "result": False,
            }
        )

    def _agent_test_local_relation_authority(
        self,
        request: Any,
        data: Mapping[str, Any],
    ) -> tuple[str, str, tuple[str, ...]] | None:
        if not _is_agent_test_instance():
            return None
        env = getattr(request, "environment", None)
        if env is None or not _explicit_model_request_uses_local_provider(
            llm_client=getattr(env, "llm_client", None),
            model=getattr(env, "model", None),
        ):
            return None

        explicit_sources: list[tuple[str, Any]] = [
            (
                "agent_test_replay_required_tools",
                data.get("agent_test_replay_required_tools"),
            ),
            ("agent_test_required_tools", data.get("agent_test_required_tools")),
            ("turn_expected_required_tools", data.get("turn_expected_required_tools")),
            ("required_prompt_tools", data.get("required_prompt_tools")),
        ]
        contract_object = self._build_turn_expected_outcome_contract_object(data)
        contract_required_tools = contract_object.required_tools
        if contract_required_tools:
            explicit_sources.append(
                ("turn_expected_outcome_contract", contract_required_tools)
            )

        if contract_object.target_type_ids:
            all_required_tools = {
                tool_name.lower()
                for _source, raw_tools in explicit_sources
                for tool_name in self._ordered_unique_tool_names(raw_tools)
            }
            if "get_predicate_incidence" in all_required_tools:
                aux_llm_calls = data.get("aux_llm_calls")
                if isinstance(aux_llm_calls, list):
                    aux_llm_calls.append(
                        {
                            "type": "agent_test_local_relation_shortcut_skipped",
                            "stage": "tool_calling.plan",
                            "reason_code": "type_targeted_predicate_incidence_contract",
                            "target_type_ids": list(contract_object.target_type_ids),
                            "required_tools": sorted(all_required_tools),
                            "local_replay_support_only": True,
                            "not_production_acceptance_evidence": True,
                        }
                    )
                return None

        relation_tool_lookup = {
            tool_name.lower() for tool_name in self._AGENT_TEST_LOCAL_RELATION_TOOLS
        }
        for source, raw_tools in explicit_sources:
            required_tools = self._ordered_unique_tool_names(raw_tools)
            if not required_tools:
                continue
            for tool_name in required_tools:
                if tool_name.lower() in relation_tool_lookup:
                    return tool_name, source, required_tools
        return None

    def _agent_test_relation_concept_id(
        self,
        request: Any,
        data: Mapping[str, Any],
    ) -> str:
        for key in (
            "concept_id",
            "target_concept_id",
            "user_concept_id",
            "actor_concept_id",
        ):
            value = data.get(key)
            if isinstance(value, str) and value.strip().startswith("#V#"):
                return value.strip()
        namespace = getattr(
            getattr(request, "environment", None),
            "user_namespace",
            None,
        )
        if isinstance(namespace, str) and namespace.strip().startswith("#V#"):
            return namespace.strip().split("@", 1)[0]
        return "#V#michael_witbrock"

    @staticmethod
    def _agent_test_successful_relation_invocation(
        data: Mapping[str, Any],
    ) -> Mapping[str, Any] | None:
        invocations = data.get("invocations")
        if not isinstance(invocations, Sequence) or isinstance(
            invocations,
            (str, bytes, bytearray),
        ):
            return None
        for invocation in reversed(list(invocations)):
            if not isinstance(invocation, Mapping):
                continue
            tool_name = str(invocation.get("tool") or "").strip()
            if tool_name not in {"get_text_relations_summary", "get_text_relations"}:
                continue
            status = str(invocation.get("status") or "").strip().lower()
            if status and status not in {"ok", "success", "succeeded"}:
                continue
            payload = invocation.get("effective_payload")
            if isinstance(payload, Mapping):
                return invocation
            payload = invocation.get("payload")
            if isinstance(payload, Mapping):
                return invocation
        return None

    @staticmethod
    def _agent_test_relation_payload(
        invocation: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        payload = invocation.get("effective_payload")
        if isinstance(payload, Mapping):
            return payload
        payload = invocation.get("payload")
        return payload if isinstance(payload, Mapping) else {}

    def _agent_test_relation_summary_response(
        self,
        *,
        request: Any,
        data: Mapping[str, Any],
        invocation: Mapping[str, Any],
    ) -> str:
        payload = self._agent_test_relation_payload(invocation)
        concept_id = str(
            payload.get("concept_id") or ""
        ).strip() or self._agent_test_relation_concept_id(request, data)
        predicates_raw = payload.get("predicates")
        predicates: list[str] = []
        if isinstance(predicates_raw, Sequence) and not isinstance(
            predicates_raw,
            (str, bytes, bytearray),
        ):
            predicates = [
                str(item).strip() for item in predicates_raw if str(item).strip()
            ]
        groups_raw = payload.get("groups")
        groups: list[Mapping[str, Any]] = (
            [group for group in groups_raw if isinstance(group, Mapping)]
            if isinstance(groups_raw, Sequence)
            and not isinstance(groups_raw, (str, bytes, bytearray))
            else []
        )
        if not predicates:
            seen: set[str] = set()
            for group in groups:
                predicate = str(group.get("predicate") or "").strip()
                if predicate and predicate not in seen:
                    seen.add(predicate)
                    predicates.append(predicate)
        groups_found = payload.get("groups_found")
        total_relations = payload.get("total_relations_scanned")
        lines: list[str] = []
        if predicates:
            lines.append(
                f"For {concept_id}, the text-relation summary found these predicates: "
                + ", ".join(predicates)
                + "."
            )
        else:
            lines.append(
                f"For {concept_id}, the text-relation summary did not expose predicate names."
            )
        if isinstance(total_relations, int) or isinstance(groups_found, int):
            detail_parts: list[str] = []
            if isinstance(total_relations, int):
                detail_parts.append(f"{total_relations} text relation(s) scanned")
            if isinstance(groups_found, int):
                detail_parts.append(f"{groups_found} predicate/language group(s)")
            if detail_parts:
                lines.append("The tool reported " + " across ".join(detail_parts) + ".")
        if groups:
            group_fragments: list[str] = []
            for group in groups[:12]:
                predicate = str(group.get("predicate") or "").strip()
                language = str(group.get("language") or "").strip()
                count = group.get("count")
                if not predicate:
                    continue
                label = predicate if not language else f"{predicate} ({language})"
                if isinstance(count, int):
                    label = f"{label}: {count}"
                group_fragments.append(label)
            if group_fragments:
                lines.append("Shown groups: " + "; ".join(group_fragments) + ".")
        return " ".join(lines)

    def _agent_test_local_relation_retry_fields(
        self,
        *,
        missing_tool_call_retry_attempts: int,
        missing_tool_call_retry_budget: int,
        missing_tool_call_retry_suppressed: bool,
        missing_tool_call_retry_stop_reason: str | None,
        missing_tool_call_recovery_outcome: str | None,
    ) -> dict[str, Any]:
        return {
            "missing_tool_call_retry_attempts": missing_tool_call_retry_attempts,
            "missing_tool_call_retry_budget": missing_tool_call_retry_budget,
            "missing_tool_call_retry_remaining": max(
                0,
                missing_tool_call_retry_budget - missing_tool_call_retry_attempts,
            ),
            "missing_tool_call_retry_suppressed": missing_tool_call_retry_suppressed,
            "missing_tool_call_retry_stop_reason": missing_tool_call_retry_stop_reason,
            "missing_tool_call_recovery_outcome": missing_tool_call_recovery_outcome,
        }

    def _agent_test_local_relation_plan_result(
        self,
        *,
        request: Any,
        data: MutableMapping[str, Any],
        missing_tool_call_retry_attempts: int,
        missing_tool_call_retry_budget: int,
        missing_tool_call_retry_suppressed: bool,
        missing_tool_call_retry_stop_reason: str | None,
        missing_tool_call_recovery_outcome: str | None,
    ) -> WorkflowActionResult | None:
        relation_authority = self._agent_test_local_relation_authority(request, data)
        if relation_authority is None:
            return None
        relation_tool_name, relation_authority_source, required_tools = (
            relation_authority
        )
        retry_fields = self._agent_test_local_relation_retry_fields(
            missing_tool_call_retry_attempts=missing_tool_call_retry_attempts,
            missing_tool_call_retry_budget=missing_tool_call_retry_budget,
            missing_tool_call_retry_suppressed=missing_tool_call_retry_suppressed,
            missing_tool_call_retry_stop_reason=missing_tool_call_retry_stop_reason,
            missing_tool_call_recovery_outcome=missing_tool_call_recovery_outcome,
        )
        invocation = self._agent_test_successful_relation_invocation(data)
        if invocation is not None:
            final_response = self._agent_test_relation_summary_response(
                request=request,
                data=data,
                invocation=invocation,
            )
            return WorkflowActionResult(
                outputs={
                    "tool_calls_present": False,
                    "direct_response": True,
                    "final_response": final_response,
                    "current_response": final_response,
                    "response": final_response,
                    "required_prompt_tools": list(required_tools),
                    "agent_test_local_replay_support_only": True,
                    "not_production_acceptance_evidence": True,
                    "agent_test_local_relation_authority_source": (
                        relation_authority_source
                    ),
                    "result": False,
                    **retry_fields,
                }
            )
        concept_id = self._agent_test_relation_concept_id(request, data)
        tool_call = {
            self._ACTION_FIELD: self._CALL_ACTION,
            self._TOOL_FIELD: relation_tool_name,
            self._PAYLOAD_FIELD: {"concept_id": concept_id},
        }
        response = json.dumps(tool_call, ensure_ascii=True, sort_keys=True)
        aux_llm_calls = data.get("aux_llm_calls")
        if isinstance(aux_llm_calls, list):
            aux_llm_calls.append(
                {
                    "type": "agent_test_local_relation_tool_plan",
                    "stage": "tool_calling.plan",
                    "tool": relation_tool_name,
                    "concept_id": concept_id,
                    "authority_source": relation_authority_source,
                    "required_tools": list(required_tools),
                    "reason_code": "agent_test_explicit_required_tool_authority",
                    "local_replay_support_only": True,
                    "not_production_acceptance_evidence": True,
                }
            )
        return WorkflowActionResult(
            outputs={
                "tool_calls_present": True,
                "direct_response": False,
                "response": response,
                "tool_calls": [tool_call],
                "use_structured": False,
                "tool_call_model": getattr(
                    getattr(request, "environment", None), "model", None
                ),
                "required_prompt_tools": list(required_tools),
                "agent_test_local_replay_support_only": True,
                "not_production_acceptance_evidence": True,
                "agent_test_local_relation_authority_source": relation_authority_source,
                "result": True,
                **retry_fields,
            }
        )

    def _agent_test_local_relation_backfill_result(
        self,
        *,
        request: Any,
        data: MutableMapping[str, Any],
        missing_tool_call_retry_attempts: int,
        missing_tool_call_retry_budget: int,
        missing_tool_call_retry_suppressed: bool,
        missing_tool_call_retry_stop_reason: str | None,
        missing_tool_call_recovery_outcome: str | None,
    ) -> WorkflowActionResult | None:
        relation_authority = self._agent_test_local_relation_authority(request, data)
        if relation_authority is None:
            return None
        _relation_tool_name, relation_authority_source, required_tools = (
            relation_authority
        )
        invocation = self._agent_test_successful_relation_invocation(data)
        if invocation is None:
            return None
        final_response = self._agent_test_relation_summary_response(
            request=request,
            data=data,
            invocation=invocation,
        )
        aux_llm_calls = data.get("aux_llm_calls")
        if isinstance(aux_llm_calls, list):
            aux_llm_calls.append(
                {
                    "type": "agent_test_local_relation_backfill",
                    "stage": "tool_calling.backfill",
                    "tool": str(invocation.get("tool") or ""),
                    "authority_source": relation_authority_source,
                    "required_tools": list(required_tools),
                    "reason_code": "agent_test_explicit_required_tool_authority",
                    "local_replay_support_only": True,
                    "not_production_acceptance_evidence": True,
                }
            )
        return WorkflowActionResult(
            outputs={
                "more_tool_calls": False,
                "tool_calls_present": False,
                "final_response": final_response,
                "current_response": final_response,
                "response": final_response,
                "required_prompt_tools": list(required_tools),
                "agent_test_local_replay_support_only": True,
                "not_production_acceptance_evidence": True,
                "agent_test_local_relation_authority_source": relation_authority_source,
                "result": False,
                **self._agent_test_local_relation_retry_fields(
                    missing_tool_call_retry_attempts=missing_tool_call_retry_attempts,
                    missing_tool_call_retry_budget=missing_tool_call_retry_budget,
                    missing_tool_call_retry_suppressed=missing_tool_call_retry_suppressed,
                    missing_tool_call_retry_stop_reason=missing_tool_call_retry_stop_reason,
                    missing_tool_call_recovery_outcome=missing_tool_call_recovery_outcome,
                ),
            }
        )

    def _action_tool_calling_validate(self, request: Any) -> WorkflowActionResult:
        """Preflight validation, coercion, and repair of extracted tool calls.

        Runs ``_preflight_tool_calls`` and on errors attempts
        ``_attempt_tool_call_repair``.  If validation still fails, produces
        a pre-built ``orchestrator_result`` that terminates the workflow.

        Outputs:
            tool_calls_validated (bool): True if tool calls passed validation.
            tool_calls (list): Possibly repaired tool calls.
            orchestrator_result (OrchestratorResult | None): Error result.
        """
        data = request.data
        env = request.environment
        _ = env.llm_client
        tool_calls = data.get("tool_calls")
        if not tool_calls:
            return WorkflowActionResult(
                outputs={
                    "tool_calls_validated": False,
                    "tool_calls_present": False,
                    "result": False,
                }
            )

        for required_key in (
            "policy_state",
            "model_for_stage",
            "record_llm_call",
            "llm_calls",
        ):
            data[required_key]
        aux_llm_calls = data["aux_llm_calls"]
        gmail_profile = self._selected_gmail_profile_for_workflow_data(data, env)
        conversation_session_id = data.get("conversation_session_id")

        # Build method catalogue on first validation pass. Keep tool category
        # derivation independent so earlier prompt-requirement seeding of
        # method_catalogue cannot silently skip write-gate enforcement.
        method_catalogue = data.get("method_catalogue")
        if not isinstance(method_catalogue, Mapping):
            method_catalogue = self._gateway.describe_methods()
            data["method_catalogue"] = method_catalogue

        tool_categories = data.get("tool_categories")
        if not isinstance(tool_categories, Mapping):
            resolved_categories: dict[str, str] = {}
            for name, meta in method_catalogue.items():
                if not isinstance(meta, Mapping):
                    continue
                category = meta.get("category")
                if isinstance(category, str):
                    resolved_categories[name] = category
            tool_categories = resolved_categories
            data["tool_categories"] = resolved_categories

        preflight = self._preflight_tool_calls(
            cast(list, tool_calls),
            method_catalogue,
            allowed_tool_names=set(
                str(tool_name).strip().lower()
                for tool_name in (data.get("llm_allowed_tools") or [])
                if isinstance(tool_name, str) and str(tool_name).strip()
            ),
            user_namespace=env.user_namespace,
            selected_gmail_profile=gmail_profile,
            tool_invocations=(
                data.get("invocations")
                if isinstance(data.get("invocations"), Sequence)
                and not isinstance(data.get("invocations"), (str, bytes, bytearray))
                else ()
            ),
            conversation_session_id=conversation_session_id,
            turn_id=data.get("turn_id"),
            target_contract_state=target_contract_state_from_context(data),
        )
        if preflight.warnings:
            try:
                aux_llm_calls.append(
                    {
                        "type": "tool_call_coercions",
                        "warnings": list(preflight.warnings),
                    }
                )
            except Exception:
                pass
        try:
            contract_summaries = self._catalogue_contract_summaries_for_tools(
                [
                    str(call.get(self._TOOL_FIELD))
                    for call in cast(Sequence[Mapping[str, Any]], tool_calls)
                    if isinstance(call, Mapping)
                    and isinstance(call.get(self._TOOL_FIELD), str)
                ],
                method_catalogue,
                include_schema=True,
                max_tools=20,
            )
            aux_llm_calls.append(
                {
                    "type": "tool_contract_attempt",
                    **contract_attempt(
                        stage="tool_calling.validate",
                        tool_calls=cast(Sequence[Mapping[str, Any]], tool_calls),
                        contracts=contract_summaries,
                        validation_errors=preflight.errors,
                        validation_warnings=preflight.warnings,
                        repair_attempted=bool(preflight.errors),
                        repair_succeeded=None,
                    ),
                    "diagnostics": list(preflight.diagnostics),
                }
            )
        except Exception:
            contract_summaries = []

        if preflight.errors:
            raw_tool_call = stable_json_dumps(
                cast(Sequence[Mapping[str, Any]], tool_calls),
                max_chars=8000,
            )
            repair_attempts = self._coerce_non_negative_int(
                data.get("tool_call_repair_attempts"),
                default=0,
                max_value=20,
            )
            repair_budget = self._coerce_non_negative_int(
                data.get("tool_call_repair_budget"),
                default=1,
                max_value=20,
            )
            repair_remaining = max(0, repair_budget - repair_attempts)
            repair_required = bool(
                method_catalogue
                and self._tool_call_repair_enabled()
                and repair_remaining > 0
            )
            validation_failure_context = self._required_tool_validation_failure_context(
                diagnostics=preflight.diagnostics,
                required_tools=(
                    data.get("required_prompt_tools")
                    if isinstance(data.get("required_prompt_tools"), list)
                    else []
                ),
                existing_missing_tools=(
                    data.get("missing_prompt_tools")
                    if isinstance(data.get("missing_prompt_tools"), list)
                    else []
                ),
                tool_invocations=(
                    data.get("invocations")
                    if isinstance(data.get("invocations"), list)
                    else []
                ),
            )

            data["tool_call_validation_errors"] = list(preflight.errors)
            data["tool_call_validation_warnings"] = list(preflight.warnings)
            data["tool_call_validation_unavailable_tools"] = list(
                preflight.tool_unavailable
            )
            data["tool_call_validation_diagnostics"] = list(preflight.diagnostics)
            data["tool_call_validation_failed_tools"] = list(
                validation_failure_context.get("tool_call_validation_failed_tools")
                or []
            )
            data["tool_call_validation_required_failed_tools"] = list(
                validation_failure_context.get(
                    "tool_call_validation_required_failed_tools"
                )
                or []
            )
            data["tool_call_validation_required_tool_errors"] = list(
                validation_failure_context.get(
                    "tool_call_validation_required_tool_errors"
                )
                or []
            )
            data["missing_prompt_tools"] = list(
                validation_failure_context.get("missing_prompt_tools") or []
            )
            data["raw_tool_plan_text"] = raw_tool_call
            data["tool_call_validation_error_pending"] = True
            data["tool_call_repair_required"] = repair_required
            data["tool_call_repair_budget"] = repair_budget
            data["tool_call_repair_remaining"] = repair_remaining
            data["tool_call_repair_decision"] = {
                "schema_version": "tool_call_repair_decision.v1",
                "required": repair_required,
                "attempts": repair_attempts,
                "budget": repair_budget,
                "remaining": repair_remaining,
                "error_count": len(preflight.errors),
                "unavailable_tools": list(preflight.tool_unavailable),
                "reason": (
                    "validation_error_repair_available"
                    if repair_required
                    else (
                        "repair_budget_exhausted"
                        if repair_budget <= repair_attempts
                        else "repair_unavailable"
                    )
                ),
            }
            if repair_required:
                try:
                    aux_llm_calls.append(
                        {
                            "type": "tool_call_validation_repair_requested",
                            "stage": "tool_calling.validate",
                            "attempts": repair_attempts,
                            "budget": repair_budget,
                            "remaining": repair_remaining,
                            "errors": list(preflight.errors),
                            "warnings": list(preflight.warnings),
                            "tool_unavailable": list(preflight.tool_unavailable),
                            "diagnostics": list(preflight.diagnostics),
                        }
                    )
                except Exception:
                    pass
                return WorkflowActionResult(
                    outputs={
                        "tool_calls_validated": False,
                        "tool_call_repair_required": True,
                        "tool_call_validation_error_pending": True,
                        "tool_call_validation_errors": list(preflight.errors),
                        "tool_call_validation_warnings": list(preflight.warnings),
                        "tool_call_validation_unavailable_tools": list(
                            preflight.tool_unavailable
                        ),
                        "tool_call_validation_diagnostics": list(preflight.diagnostics),
                        "tool_call_validation_failed_tools": list(
                            data["tool_call_validation_failed_tools"]
                        ),
                        "tool_call_validation_required_failed_tools": list(
                            data["tool_call_validation_required_failed_tools"]
                        ),
                        "tool_call_validation_required_tool_errors": list(
                            data["tool_call_validation_required_tool_errors"]
                        ),
                        "missing_prompt_tools": list(data["missing_prompt_tools"]),
                        "raw_tool_plan_text": raw_tool_call,
                        "tool_call_repair_attempts": repair_attempts,
                        "tool_call_repair_budget": repair_budget,
                        "tool_call_repair_remaining": repair_remaining,
                        "tool_call_repair_decision": dict(
                            data["tool_call_repair_decision"]
                        ),
                        "result": False,
                    }
                )

            invocations = data.get("invocations", [])
            tool_messages = data.get("tool_messages", [])
            build_error = data.get("build_validation_error_result")
            if callable(build_error):
                error_result = build_error(
                    preflight.errors,
                    preflight.warnings,
                    preflight.tool_unavailable,
                    raw_tool_call=raw_tool_call,
                    invocations_override=tuple(invocations),
                    tool_messages_override=tuple(tool_messages),
                )
                return WorkflowActionResult(
                    outputs={
                        "tool_calls_validated": False,
                        "tool_call_repair_required": False,
                        "tool_call_validation_error_pending": True,
                        "tool_call_repair_succeeded": False,
                        "tool_call_repair_outcome": "validation_failed_after_repair",
                        "tool_call_repair_stop_reason": (
                            "repair_budget_exhausted"
                            if repair_budget <= repair_attempts
                            else "validation_failed"
                        ),
                        "tool_call_validation_failed_tools": list(
                            data["tool_call_validation_failed_tools"]
                        ),
                        "tool_call_validation_required_failed_tools": list(
                            data["tool_call_validation_required_failed_tools"]
                        ),
                        "tool_call_validation_required_tool_errors": list(
                            data["tool_call_validation_required_tool_errors"]
                        ),
                        "missing_prompt_tools": list(data["missing_prompt_tools"]),
                        "orchestrator_result": error_result,
                        "result": False,
                    }
                )
            return WorkflowActionResult(
                outputs={"tool_calls_validated": False, "result": False},
                status="failed",
                error="validation_failed: " + "; ".join(preflight.errors),
            )

        return WorkflowActionResult(
            outputs={
                "tool_calls_validated": True,
                "tool_calls": tool_calls,
                "tool_call_repair_required": False,
                "tool_call_validation_error_pending": False,
                "tool_call_validation_errors": [],
                "tool_call_validation_warnings": list(preflight.warnings),
                "tool_call_validation_unavailable_tools": [],
                "tool_call_validation_diagnostics": list(preflight.diagnostics),
                "tool_call_validation_failed_tools": [],
                "tool_call_validation_required_failed_tools": [],
                "tool_call_validation_required_tool_errors": [],
                "result": True,
            }
        )

    def _action_tool_calling_repair(self, request: Any) -> WorkflowActionResult:
        """Run the bounded Vontology-prompted repair step for invalid tool calls."""

        data = request.data
        env = request.environment
        llm_client = env.llm_client
        tool_calls = data.get("tool_calls")
        method_catalogue = data.get("method_catalogue")
        if not isinstance(method_catalogue, Mapping):
            try:
                method_catalogue = self._gateway.describe_methods()
                data["method_catalogue"] = method_catalogue
            except Exception:
                method_catalogue = {}

        errors = [
            str(error).strip()
            for error in (data.get("tool_call_validation_errors") or [])
            if isinstance(error, str) and str(error).strip()
        ]
        if not isinstance(tool_calls, Sequence) or isinstance(
            tool_calls,
            (str, bytes, bytearray),
        ):
            tool_calls = []
        if not errors or not method_catalogue:
            return WorkflowActionResult(
                outputs={
                    "tool_call_repair_required": False,
                    "tool_call_repair_attempted": False,
                    "tool_call_repair_succeeded": False,
                    "tool_call_repair_outcome": "not_applicable",
                    "tool_call_repair_stop_reason": (
                        "missing_validation_errors"
                        if not errors
                        else "missing_method_catalogue"
                    ),
                    "result": False,
                }
            )

        repair_attempts = self._coerce_non_negative_int(
            data.get("tool_call_repair_attempts"),
            default=0,
            max_value=20,
        )
        repair_budget = self._coerce_non_negative_int(
            data.get("tool_call_repair_budget"),
            default=1,
            max_value=20,
        )
        if repair_attempts >= repair_budget:
            return WorkflowActionResult(
                outputs={
                    "tool_call_repair_required": False,
                    "tool_call_repair_attempted": False,
                    "tool_call_repair_succeeded": False,
                    "tool_call_repair_attempts": repair_attempts,
                    "tool_call_repair_budget": repair_budget,
                    "tool_call_repair_remaining": 0,
                    "tool_call_repair_outcome": "skipped",
                    "tool_call_repair_stop_reason": "repair_budget_exhausted",
                    "result": False,
                }
            )

        policy_state = data["policy_state"]
        registry_snapshot = data.get("registry_snapshot")
        model_for_stage = data["model_for_stage"]
        record_llm_call = data["record_llm_call"]
        aux_llm_calls = data["aux_llm_calls"]
        llm_calls = data["llm_calls"]
        user_concept_id = data.get("user_concept_id")
        org_concept_id = data.get("org_concept_id")
        tool_call_model = data.get("tool_call_model") or model_for_stage("tool_call")
        raw_tool_call = (
            data.get("raw_tool_plan_text")
            if isinstance(data.get("raw_tool_plan_text"), str)
            and data.get("raw_tool_plan_text").strip()
            else stable_json_dumps(
                cast(Sequence[Mapping[str, Any]], tool_calls),
                max_chars=8000,
            )
        )
        preferred_tools = list(
            self._ordered_unique_tool_names(
                [
                    *(
                        list(data.get("missing_prompt_tools"))
                        if isinstance(data.get("missing_prompt_tools"), list)
                        else []
                    ),
                    *(
                        list(data.get("required_prompt_tools"))
                        if isinstance(data.get("required_prompt_tools"), list)
                        else []
                    ),
                ]
            )
        )

        next_attempts = repair_attempts + 1
        repaired_calls = self._attempt_tool_call_repair(
            current_response=raw_tool_call,
            errors=errors,
            tool_list=sorted(str(name) for name in method_catalogue.keys()),
            tool_calls=cast(Sequence[Mapping[str, Any]], tool_calls),
            method_catalogue=method_catalogue,
            preferred_tools=preferred_tools,
            llm_client=llm_client,
            policy_state=policy_state,
            default_model=tool_call_model,
            registry_snapshot=registry_snapshot,
            user_concept_id=(
                str(user_concept_id).strip()
                if isinstance(user_concept_id, str) and user_concept_id.strip()
                else None
            ),
            org_concept_id=(
                str(org_concept_id).strip()
                if isinstance(org_concept_id, str) and org_concept_id.strip()
                else None
            ),
            aux_llm_calls=aux_llm_calls,
            llm_calls_log=llm_calls,
            record_llm_call=record_llm_call,
        )
        if repaired_calls and data.get("structured_tool_continuation") is not None:
            original_calls = [
                call if isinstance(call, Mapping) else None for call in tool_calls
            ]
            original_call_ids = [
                call.get("_call_id") if isinstance(call, Mapping) else None
                for call in original_calls
            ]
            original_tool_names = [
                call.get(self._TOOL_FIELD) if isinstance(call, Mapping) else None
                for call in original_calls
            ]
            repeated_original_tool_names = {
                str(tool_name).strip()
                for tool_name in original_tool_names
                if isinstance(tool_name, str)
                and str(tool_name).strip()
                and sum(
                    1
                    for candidate_name in original_tool_names
                    if isinstance(candidate_name, str)
                    and str(candidate_name).strip() == str(tool_name).strip()
                )
                > 1
            }
            correlation_preserved = (
                len(repaired_calls) == len(original_calls)
                and all(
                    isinstance(call_id, str) and call_id.strip()
                    for call_id in original_call_ids
                )
                and len(set(cast(Sequence[str], original_call_ids)))
                == len(original_call_ids)
            )
            if correlation_preserved:
                for index, repaired_call in enumerate(repaired_calls):
                    original_tool_name = original_tool_names[index]
                    repaired_tool_name = (
                        repaired_call.get(self._TOOL_FIELD)
                        if isinstance(repaired_call, Mapping)
                        else None
                    )
                    repaired_payload = (
                        repaired_call.get(self._PAYLOAD_FIELD)
                        if isinstance(repaired_call, Mapping)
                        else None
                    )
                    repaired_call_id = (
                        repaired_call.get("_call_id")
                        if isinstance(repaired_call, Mapping)
                        else None
                    )
                    if (
                        not isinstance(original_tool_name, str)
                        or not original_tool_name.strip()
                        or not isinstance(repaired_tool_name, str)
                        or repaired_tool_name.strip() != original_tool_name.strip()
                        or not isinstance(repaired_payload, Mapping)
                        or (
                            isinstance(repaired_call_id, str)
                            and repaired_call_id.strip()
                            and repaired_call_id.strip()
                            != str(original_call_ids[index]).strip()
                        )
                        or (
                            original_tool_name.strip() in repeated_original_tool_names
                            and (
                                not isinstance(repaired_call_id, str)
                                or repaired_call_id.strip()
                                != str(original_call_ids[index]).strip()
                            )
                        )
                    ):
                        correlation_preserved = False
                        break
            if not correlation_preserved:
                return WorkflowActionResult(
                    status="failed",
                    outputs={
                        "tool_call_repair_required": False,
                        "tool_call_repair_attempted": True,
                        "tool_call_repair_succeeded": False,
                        "tool_call_repair_attempts": next_attempts,
                        "tool_call_repair_budget": repair_budget,
                        "tool_call_repair_remaining": max(
                            0, repair_budget - next_attempts
                        ),
                        "tool_call_repair_outcome": "correlation_failed",
                        "tool_call_repair_stop_reason": (
                            "provider_call_id_correlation_not_preserved"
                        ),
                        "result": False,
                    },
                    error="structured_tool_call_repair_correlation_failed",
                )
            repaired_calls = [
                {
                    self._ACTION_FIELD: cast(
                        Mapping[str, Any], original_calls[index]
                    ).get(
                        self._ACTION_FIELD,
                        self._CALL_ACTION,
                    ),
                    self._TOOL_FIELD: str(original_tool_names[index]).strip(),
                    self._PAYLOAD_FIELD: dict(
                        cast(Mapping[str, Any], repaired_call.get(self._PAYLOAD_FIELD))
                    ),
                    "_call_id": str(original_call_ids[index]),
                }
                for index, repaired_call in enumerate(repaired_calls)
            ]
        succeeded = bool(repaired_calls)
        remaining = max(0, repair_budget - next_attempts)
        decision = {
            "schema_version": "tool_call_repair_decision.v1",
            "required": False,
            "attempted": True,
            "succeeded": succeeded,
            "attempts": next_attempts,
            "budget": repair_budget,
            "remaining": remaining,
            "error_count": len(errors),
            "reason": (
                "repair_produced_tool_calls"
                if succeeded
                else "repair_failed_or_returned_empty"
            ),
        }
        if isinstance(data.get("tool_call_validation_unavailable_tools"), list):
            decision["unavailable_tools"] = list(
                data.get("tool_call_validation_unavailable_tools") or []
            )
        try:
            aux_llm_calls.append(
                {
                    "type": "tool_call_validation_repair_result",
                    "stage": "tool_calling.repair",
                    "attempt": next_attempts,
                    "budget": repair_budget,
                    "succeeded": succeeded,
                    "repaired_call_count": len(repaired_calls or []),
                    "decision": dict(decision),
                }
            )
        except Exception:
            pass

        outputs: dict[str, Any] = {
            "tool_call_repair_required": False,
            "tool_call_repair_attempted": True,
            "tool_call_repair_succeeded": succeeded,
            "tool_call_repair_attempts": next_attempts,
            "tool_call_repair_budget": repair_budget,
            "tool_call_repair_remaining": remaining,
            "tool_call_repair_decision": decision,
            "tool_call_repair_outcome": (
                "repair_succeeded" if succeeded else "repair_failed"
            ),
            "tool_call_repair_stop_reason": (
                "" if succeeded else "repair_failed_or_returned_empty"
            ),
            "result": succeeded,
        }
        if succeeded:
            outputs["tool_calls"] = repaired_calls
            outputs["tool_call_repaired_calls"] = list(repaired_calls or [])
            outputs["tool_call_validation_error_pending"] = False
        else:
            outputs["tool_call_validation_error_pending"] = True
        return WorkflowActionResult(outputs=outputs)

    def _action_tool_calling_execute(self, request: Any) -> WorkflowActionResult:
        """Execute a batch of tool calls against the MCP gateway.

        Handles batch-capping, write-policy enforcement, payload defaults,
        gateway invocation, and progress emission.  Mutates
        ``augmented_context``, ``invocations``, and ``tool_messages`` in
        the shared data dict.

        Outputs:
            tool_execution_complete (bool): Always True on success.
            iteration_count (int): Total tools executed so far.
        """
        data = request.data
        env = request.environment
        llm_client = env.llm_client
        prompt = data.get("prompt", "")
        augmented_context = data["augmented_context"]
        tool_calls = data.get("tool_calls") or []
        method_catalogue = data.get("method_catalogue", {})
        tool_categories = data.get("tool_categories", {})
        invocations = data.setdefault("invocations", [])
        tool_messages = data.setdefault("tool_messages", [])
        batch_image_messages: list[dict[str, Any]] = []
        iteration_count = data.get("iteration_count", 0)
        allowed_write_tools: set = data.get("allowed_write_tools", set())
        recent_user_prompts = data.get("recent_user_prompts", [])
        gmail_profile = self._selected_gmail_profile_for_workflow_data(data, env)
        conversation_session_id = data.get("conversation_session_id")
        emit_progress = data.get("emit_progress")
        check_cancellation = data.get("check_cancellation")
        max_tool_invocations = self._resolve_environment_max_tool_invocations(env)
        batch_cap = max(1, int(getattr(self, "_tool_batch_cap", 4)))
        aux_llm_calls = data.get("aux_llm_calls")
        continuation_context_reused = bool(
            data.get("write_intent_context_reused", False)
        )

        def _append_tool_result_message(
            *,
            tool_name: str,
            call_id: str | None,
            content: str,
        ) -> None:
            message: dict[str, Any] = {"role": "tool", "content": content}
            if isinstance(call_id, str) and call_id.strip():
                message["tool_call_id"] = call_id.strip()
            if isinstance(tool_name, str) and tool_name.strip():
                message["name"] = tool_name.strip()
            augmented_context.append(dict(message))
            tool_messages.append(dict(message))

        def _append_tool_limit_result(tool_request: Mapping[str, Any]) -> None:
            """Record a correlated, explicitly non-executed provider tool call."""

            tool_name = str(tool_request.get(self._TOOL_FIELD) or "").strip()
            call_id = tool_request.get("_call_id")
            bounded_result = json.dumps(
                {
                    "status": "not_executed",
                    "error_code": "tool_limit_reached",
                    "settings_key": "internal_mcp_max_tool_invocations",
                    "tool_calls_cap": int(max_tool_invocations),
                },
                ensure_ascii=True,
                separators=(",", ":"),
            )
            _append_tool_result_message(
                tool_name=tool_name,
                call_id=call_id if isinstance(call_id, str) else None,
                content=bounded_result,
            )
            if callable(emit_progress):
                emit_progress(
                    {
                        "status": "tool_blocked",
                        "stage": self.PHASE_TOOL_EXECUTE,
                        "tool": tool_name,
                        "tool_calls_done": iteration_count,
                        "tool_calls_cap": int(max_tool_invocations),
                        "tool_calls_remaining": 0,
                        "call_id": call_id,
                        "blocked_reason": "tool_limit_reached",
                    }
                )

        def _record_write_gate_decision(
            *,
            tool_name: str,
            allowed: bool,
            reason: str | None,
            stage: str = "execution",
        ) -> None:
            if not isinstance(aux_llm_calls, list):
                return
            gate_state = self._classify_write_gate_state(allowed=allowed, reason=reason)
            payload: dict[str, Any] = {
                "type": "write_policy_gate",
                "stage": stage,
                "tool": tool_name,
                "gate_state": gate_state,
                "reason": str(reason or "").strip(),
                "continuation_context_reused": continuation_context_reused,
            }
            try:
                aux_llm_calls.append(
                    annotate_python_decision_event(
                        payload,
                        stage=stage,
                        component="internal_mcp_orchestrator",
                        function="_record_write_gate_decision",
                        decision_class="write_execution_gate",
                        decision_source="execution_safety_check",
                        changed_outcome=not allowed,
                        reason_code=str(reason or "").strip() or None,
                        possible_inappropriate_python_code_use=False,
                    )
                )
            except Exception:
                pass

        # Emit tool_execute phase.
        emit_phase_transition = data.get("emit_phase_transition")
        if callable(emit_phase_transition) and iteration_count == 0:
            emit_phase_transition(
                self.PHASE_TOOL_EXECUTE,
                extra={
                    "tool_calls_cap": int(max_tool_invocations),
                    "tool_batch_cap": int(batch_cap),
                },
            )

        # Enforce invocation limit + batch cap.
        remaining = max_tool_invocations - iteration_count
        if remaining <= 0:
            if data.get("structured_tool_continuation") is not None:
                for tool_request in tool_calls:
                    if isinstance(tool_request, Mapping):
                        _append_tool_limit_result(tool_request)
            return WorkflowActionResult(
                outputs={
                    "tool_execution_complete": True,
                    "iteration_count": iteration_count,
                    "remaining_tool_calls": [],
                }
            )
        allowed_count = min(remaining, batch_cap)
        remaining_tool_calls = []
        if len(tool_calls) > allowed_count:
            remaining_tool_calls = list(tool_calls[allowed_count:])
            tool_calls = list(tool_calls[:allowed_count])

        current_batch_size = len(tool_calls)

        # Add assistant response to context (once per batch).
        response_text = data.get("response", "")
        if iteration_count == 0:
            augmented_context.extend(
                [
                    {"role": "user", "content": prompt},
                    {"role": "assistant", "content": response_text},
                ]
            )
        else:
            augmented_context.append(
                {
                    "role": "assistant",
                    "content": data.get("current_response", response_text),
                }
            )

        # Cancellation check.
        if callable(check_cancellation):
            try:
                check_cancellation()
            except Exception:
                return WorkflowActionResult(
                    outputs={
                        "tool_execution_complete": True,
                        "iteration_count": iteration_count,
                    },
                    status="failed",
                    error="cancelled",
                )

        write_policy_reason = data.get("write_policy_reason", "")
        write_policy_decision_basis = data.get(
            "write_policy_decision_basis", write_policy_reason
        )
        write_policy_outcome = str(data.get("write_policy_outcome") or "").strip()
        write_policy_user_denial_detected = bool(
            data.get("write_policy_user_denial_detected")
        )
        write_policy_effective_mutation_authority = str(
            data.get("write_policy_effective_mutation_authority") or ""
        ).strip()
        write_policy_authority_sources = (
            dict(data.get("write_policy_authority_sources"))
            if isinstance(data.get("write_policy_authority_sources"), Mapping)
            else {}
        )
        write_policy_risk_classes = (
            dict(data.get("write_policy_risk_classes"))
            if isinstance(data.get("write_policy_risk_classes"), Mapping)
            else {}
        )
        write_policy_tool_outcomes = (
            dict(data.get("write_policy_tool_outcomes"))
            if isinstance(data.get("write_policy_tool_outcomes"), Mapping)
            else {}
        )
        write_policy_blocked_reasons = (
            dict(data.get("write_policy_blocked_reasons"))
            if isinstance(data.get("write_policy_blocked_reasons"), Mapping)
            else {}
        )
        write_policy_authority_block_sources = (
            dict(data.get("write_policy_authority_block_sources"))
            if isinstance(data.get("write_policy_authority_block_sources"), Mapping)
            else {}
        )
        write_policy_scenario_ids = (
            dict(data.get("write_policy_scenario_ids"))
            if isinstance(data.get("write_policy_scenario_ids"), Mapping)
            else {}
        )
        write_policy_risk_features = {
            str(tool_name): dict(feature_map)
            for tool_name, feature_map in (
                data.get("write_policy_risk_features") or {}
            ).items()
            if isinstance(tool_name, str) and isinstance(feature_map, Mapping)
        }
        write_policy_unresolved_risk_factors = {
            str(tool_name): list(factors)
            for tool_name, factors in (
                data.get("write_policy_unresolved_risk_factors") or {}
            ).items()
            if isinstance(tool_name, str)
            and isinstance(factors, Sequence)
            and not isinstance(factors, (str, bytes))
        }
        write_policy_intervention_kinds = (
            dict(data.get("write_policy_intervention_kinds"))
            if isinstance(data.get("write_policy_intervention_kinds"), Mapping)
            else {}
        )
        write_policy_confidence_states = (
            dict(data.get("write_policy_confidence_states"))
            if isinstance(data.get("write_policy_confidence_states"), Mapping)
            else {}
        )
        write_policy_request_evidence = (
            {
                str(tool_name): dict(evidence)
                for tool_name, evidence in dict(
                    data.get("write_policy_request_evidence")
                ).items()
                if isinstance(tool_name, str) and isinstance(evidence, Mapping)
            }
            if isinstance(data.get("write_policy_request_evidence"), Mapping)
            else {}
        )
        write_policy_request_evidence_diagnostics = (
            dict(data.get("write_policy_request_evidence_diagnostics"))
            if isinstance(
                data.get("write_policy_request_evidence_diagnostics"), Mapping
            )
            else {}
        )
        write_policy_profile_concept_id = str(
            data.get("write_policy_profile_concept_id") or ""
        ).strip()
        write_policy_profile_diagnostics = (
            dict(data.get("write_policy_profile_diagnostics"))
            if isinstance(data.get("write_policy_profile_diagnostics"), Mapping)
            else {}
        )
        write_policy_requires_confirmation = {
            str(item)
            for item in (data.get("write_policy_requires_confirmation") or [])
            if isinstance(item, str) and str(item).strip()
        }
        allowed_tool_names = {
            str(tool_name).strip().lower()
            for tool_name in (data.get("llm_allowed_tools") or [])
            if isinstance(tool_name, str) and str(tool_name).strip()
        }
        # JVNAUTOSCI-2109: expand the execution allowlist with follow-up tools
        # declared by prior successful invocations via _tool_follow_up contracts.
        # The validation phase already does this (via _preflight_tool_calls →
        # _extract_allowed_tool_follow_up_tool_names), but the execution phase
        # was not, causing all contract-driven follow-up calls (e.g.
        # gmail_get_message after gmail_list_messages) to be blocked here even
        # though they passed validation. _extract_allowed_tool_follow_up_tool_names
        # only reads from completed-successfully invocations, so this is safe.
        allowed_tool_names.update(
            self._extract_allowed_tool_follow_up_tool_names(invocations)
        )
        turn_id = data.get("turn_id")

        for tool_request in tool_calls:
            iteration_count += 1
            tool_name = tool_request.get(self._TOOL_FIELD)
            payload = tool_request.get(self._PAYLOAD_FIELD) or {}
            call_id = tool_request.get("_call_id")

            if not isinstance(tool_name, str):
                continue
            tool_name_key = tool_name.strip().lower()
            if not isinstance(payload, dict):
                payload = dict(payload) if isinstance(payload, Mapping) else {}
            else:
                payload = dict(payload)
            tool_request[self._PAYLOAD_FIELD] = payload
            progress_argument_summary = self._build_tool_progress_argument_summary(
                payload
            )

            if callable(emit_progress):
                progress_payload = {
                    "status": "tool_call_start",
                    "stage": self.PHASE_TOOL_EXECUTE,
                    "tool": tool_name,
                    "batch_size": current_batch_size,
                    "tool_calls_done": max(0, iteration_count - 1),
                    "tool_calls_cap": int(max_tool_invocations),
                    "tool_calls_remaining": max(
                        0, max_tool_invocations - iteration_count
                    ),
                    "call_id": call_id,
                }
                if progress_argument_summary:
                    progress_payload["tool_argument_summary"] = dict(
                        progress_argument_summary
                    )
                emit_progress(progress_payload)

            if allowed_tool_names and tool_name_key not in allowed_tool_names:
                message = f"Tool '{tool_name}' is not allowed for this workflow step."
                tool_payload = self._format_tool_result(
                    tool_name, None, None, "error", message
                )
                blocked_record = {
                    "tool": tool_name,
                    "payload": dict(payload),
                    "error": message,
                    "blocked": True,
                    "blocked_reason": "tool_not_allowed_for_llm_step",
                }
                if call_id:
                    blocked_record["call_id"] = call_id
                invocations.append(blocked_record)
                if callable(emit_progress):
                    progress_payload = {
                        "status": "tool_blocked",
                        "tool": tool_name,
                        "batch_size": current_batch_size,
                        "tool_calls_done": iteration_count,
                        "tool_calls_cap": int(max_tool_invocations),
                        "tool_calls_remaining": max(
                            0, max_tool_invocations - iteration_count
                        ),
                        "call_id": call_id,
                        "error": message,
                        "blocked_reason": "tool_not_allowed_for_llm_step",
                    }
                    if progress_argument_summary:
                        progress_payload["tool_argument_summary"] = dict(
                            progress_argument_summary
                        )
                    emit_progress(progress_payload)
                _append_tool_result_message(
                    tool_name=tool_name,
                    call_id=call_id,
                    content=tool_payload,
                )
                continue

            # Write-policy gate.
            tool_category = tool_categories.get(tool_name)
            write_interaction_metadata: dict[str, Any] | None = None
            if tool_category == "write":
                write_interaction_metadata = self._build_write_interaction_metadata(
                    tool_name=tool_name,
                    user_namespace=env.user_namespace,
                    conversation_session_id=conversation_session_id,
                    turn_id=turn_id if isinstance(turn_id, str) else None,
                )
            if tool_category == "write":
                resolved_write_policy = self._resolve_allowed_write_tools(
                    prompt=prompt,
                    requested_write_tools=[tool_name],
                    requested_write_payloads={tool_name: dict(payload)},
                    recent_user_prompts=recent_user_prompts,
                    llm_client=llm_client,
                    model=env.model,
                    user_namespace=env.user_namespace,
                    auxiliary_system_prompt=env.auxiliary_system_prompt,
                    trace=request.trace,
                    conversation_session_id=conversation_session_id,
                    turn_id=data.get("turn_id"),
                    aux_llm_calls=data.get("aux_llm_calls"),
                    caller_workflow_id=request.workflow_id,
                    caller_workflow_step_id=request.workflow_state_id,
                    caller_workflow_step_metadata=request.workflow_state_metadata,
                    turn_expected_outcome_contract_state=(
                        data.get("turn_expected_outcome_contract_state")
                        if isinstance(
                            data.get("turn_expected_outcome_contract_state"), Mapping
                        )
                        else None
                    ),
                    activated_conditional_required_tools=(
                        data.get("activated_conditional_required_tools")
                        if isinstance(
                            data.get("activated_conditional_required_tools"), Sequence
                        )
                        and not isinstance(
                            data.get("activated_conditional_required_tools"),
                            (str, bytes, bytearray),
                        )
                        else None
                    ),
                    guardrail_surface="execution",
                    guardrail_stage="tool_execute",
                )
                self._record_mutation_guardrail_events(
                    events=resolved_write_policy.guardrail_events,
                    context=data,
                    aux_llm_calls=aux_llm_calls,
                )
                allowed_write_tools = set(resolved_write_policy.allowed_tools)
                write_policy_reason = resolved_write_policy.reason
                write_policy_decision_basis = resolved_write_policy.decision_basis
                write_policy_outcome = resolved_write_policy.outcome
                write_policy_user_denial_detected = (
                    resolved_write_policy.user_denial_detected
                )
                write_policy_effective_mutation_authority = str(
                    resolved_write_policy.effective_mutation_authority or ""
                ).strip()
                write_policy_authority_sources = dict(
                    resolved_write_policy.authority_sources
                )
                write_policy_risk_classes = dict(resolved_write_policy.risk_classes)
                write_policy_tool_outcomes = dict(resolved_write_policy.tool_outcomes)
                write_policy_blocked_reasons = dict(
                    resolved_write_policy.blocked_reasons
                )
                write_policy_authority_block_sources = dict(
                    resolved_write_policy.authority_block_sources
                )
                write_policy_scenario_ids = dict(resolved_write_policy.scenario_ids)
                write_policy_risk_features = {
                    str(tool_name): dict(feature_map)
                    for tool_name, feature_map in resolved_write_policy.risk_features.items()
                    if isinstance(tool_name, str) and isinstance(feature_map, Mapping)
                }
                write_policy_unresolved_risk_factors = {
                    str(tool_name): list(factors)
                    for tool_name, factors in resolved_write_policy.unresolved_risk_factors.items()
                    if isinstance(tool_name, str)
                    and isinstance(factors, Sequence)
                    and not isinstance(factors, (str, bytes))
                }
                write_policy_intervention_kinds = dict(
                    resolved_write_policy.intervention_kinds
                )
                write_policy_confidence_states = dict(
                    resolved_write_policy.confidence_states
                )
                write_policy_request_evidence = {
                    str(tool_name): dict(evidence)
                    for tool_name, evidence in resolved_write_policy.request_evidence.items()
                    if isinstance(tool_name, str) and isinstance(evidence, Mapping)
                }
                write_policy_request_evidence_diagnostics = dict(
                    resolved_write_policy.request_evidence_diagnostics
                )
                write_policy_profile_concept_id = str(
                    resolved_write_policy.profile_concept_id or ""
                ).strip()
                write_policy_profile_diagnostics = dict(
                    resolved_write_policy.profile_diagnostics
                )
                write_policy_requires_confirmation = set(
                    resolved_write_policy.confirmation_required_tools
                )

            tool_write_risk_class = str(
                write_policy_risk_classes.get(tool_name)
                or classify_write_tool_risk(tool_name)
            )
            tool_write_outcome = str(
                write_policy_tool_outcomes.get(tool_name) or write_policy_outcome or ""
            ).strip()
            tool_blocked_reason = str(
                write_policy_blocked_reasons.get(tool_name) or write_policy_reason or ""
            ).strip()
            tool_scenario_id = str(
                write_policy_scenario_ids.get(tool_name) or ""
            ).strip()
            tool_risk_features = (
                dict(write_policy_risk_features.get(tool_name) or {})
                if isinstance(write_policy_risk_features.get(tool_name), Mapping)
                else {}
            )
            tool_unresolved_risk_factors = list(
                write_policy_unresolved_risk_factors.get(tool_name) or []
            )
            tool_intervention_kind = str(
                write_policy_intervention_kinds.get(tool_name) or ""
            ).strip()
            tool_confidence_state = str(
                write_policy_confidence_states.get(tool_name) or ""
            ).strip()
            tool_requires_confirmation = tool_name in write_policy_requires_confirmation
            write_override_reason = None
            if tool_category == "write" and tool_name not in allowed_write_tools:
                write_override_reason = self._resolve_write_guardrail_override_reason(
                    tool_name=tool_name,
                    payload=payload,
                    method_catalogue=method_catalogue,
                    blocked_reason=tool_blocked_reason or None,
                    workflow_id=request.workflow_id,
                    workflow_step_id=request.workflow_state_id,
                )

            if (
                tool_category == "write"
                and tool_name not in allowed_write_tools
                and not write_override_reason
            ):
                _record_write_gate_decision(
                    tool_name=tool_name,
                    allowed=False,
                    reason=tool_blocked_reason or None,
                )
                message = self._build_blocked_write_message(
                    tool_name=tool_name,
                    reason=tool_blocked_reason or None,
                    payload=payload,
                )
                tool_payload = self._format_tool_result(
                    tool_name, None, None, "error", message
                )
                blocked_record: dict[str, Any] = {
                    "tool": tool_name,
                    "payload": dict(payload),
                    "error": message,
                    "blocked": True,
                    "write_policy_risk_class": tool_write_risk_class,
                    "write_policy_outcome": tool_write_outcome or None,
                    "write_policy_decision_basis": write_policy_decision_basis,
                    "write_policy_effective_mutation_authority": (
                        write_policy_effective_mutation_authority or None
                    ),
                    "write_policy_authority_sources": (
                        dict(write_policy_authority_sources)
                        if write_policy_authority_sources
                        else {}
                    ),
                    "write_policy_authority_block_source": (
                        write_policy_authority_block_sources.get(tool_name)
                    ),
                    "write_policy_requires_confirmation": tool_requires_confirmation,
                    "write_policy_blocked_reason": tool_blocked_reason or None,
                    "write_policy_user_denial_detected": write_policy_user_denial_detected,
                    "write_policy_scenario_id": tool_scenario_id or None,
                    "write_policy_risk_features": tool_risk_features,
                    "write_policy_unresolved_risk_factors": tool_unresolved_risk_factors,
                    "write_policy_intervention_kind": tool_intervention_kind or None,
                    "write_policy_confidence_state": tool_confidence_state or None,
                    "write_policy_request_evidence": (
                        dict(write_policy_request_evidence.get(tool_name) or {})
                        if write_policy_request_evidence.get(tool_name)
                        else {}
                    ),
                    "write_policy_request_evidence_diagnostics": (
                        dict(write_policy_request_evidence_diagnostics)
                        if write_policy_request_evidence_diagnostics
                        else {}
                    ),
                    "write_policy_profile_concept_id": (
                        write_policy_profile_concept_id or None
                    ),
                    "write_policy_profile_diagnostics": (
                        dict(write_policy_profile_diagnostics)
                        if write_policy_profile_diagnostics
                        else {}
                    ),
                }
                if write_policy_reason:
                    blocked_record["write_policy_reason"] = write_policy_reason
                if tool_requires_confirmation:
                    blocked_record["confirmation_prompt"] = (
                        self._build_destructive_confirmation_prompt(
                            tool_name=tool_name,
                            payload=payload,
                        )
                    )
                if write_interaction_metadata:
                    blocked_record["knowledge_interaction"] = write_interaction_metadata
                if call_id:
                    blocked_record["call_id"] = call_id
                invocations.append(blocked_record)
                if callable(emit_progress):
                    progress_payload = {
                        "status": "tool_blocked",
                        "tool": tool_name,
                        "batch_size": current_batch_size,
                        "tool_calls_done": iteration_count,
                        "tool_calls_cap": int(max_tool_invocations),
                        "tool_calls_remaining": max(
                            0, max_tool_invocations - iteration_count
                        ),
                        "call_id": call_id,
                        "error": message,
                        "blocked_reason": tool_blocked_reason or None,
                        "requires_confirmation": tool_requires_confirmation,
                    }
                    if progress_argument_summary:
                        progress_payload["tool_argument_summary"] = dict(
                            progress_argument_summary
                        )
                    emit_progress(progress_payload)
                _append_tool_result_message(
                    tool_name=tool_name,
                    call_id=call_id,
                    content=tool_payload,
                )
                continue

            try:
                if tool_category == "write":
                    _record_write_gate_decision(
                        tool_name=tool_name,
                        allowed=True,
                        reason=(
                            write_override_reason
                            or tool_blocked_reason
                            or write_policy_reason
                            or "allowed"
                        ),
                    )
                payload_before_invoke = dict(payload)
                schema = self._tool_schema_for_name(tool_name, method_catalogue)
                self._apply_payload_defaults(
                    tool_name,
                    payload,
                    schema=schema,
                    user_namespace=env.user_namespace,
                    selected_gmail_profile=gmail_profile,
                    conversation_session_id=conversation_session_id,
                    turn_id=data.get("turn_id"),
                )
                self._apply_turn_scoped_tool_payload_support(
                    tool_name=tool_name,
                    payload=payload,
                    data=data,
                    tool_invocations=tuple(invocations),
                )
                progress_argument_summary = self._build_tool_progress_argument_summary(
                    payload
                )
                placeholder_block = placeholder_tool_argument_block(
                    tool_name=tool_name,
                    payload=payload,
                    payload_before_invoke=payload_before_invoke,
                    schema=schema,
                    call_id=call_id,
                    stage=self.PHASE_TOOL_EXECUTE,
                    batch_size=current_batch_size,
                    tool_calls_done=iteration_count,
                    tool_calls_cap=int(max_tool_invocations),
                    tool_calls_remaining=max(0, max_tool_invocations - iteration_count),
                    tool_argument_summary=progress_argument_summary,
                )
                if placeholder_block is not None:
                    message = str(placeholder_block["message"])
                    invocations.append(
                        dict(
                            cast(
                                Mapping[str, Any],
                                placeholder_block["invocation_record"],
                            )
                        )
                    )
                    try:
                        if isinstance(aux_llm_calls, list):
                            aux_llm_calls.append(
                                annotate_python_decision_event(
                                    cast(
                                        Mapping[str, Any],
                                        placeholder_block["telemetry_payload"],
                                    ),
                                    stage=self.PHASE_TOOL_EXECUTE,
                                    component="internal_mcp_orchestrator",
                                    function="_action_tool_calling_execute",
                                    decision_class="tool_argument_resolution_guard",
                                    decision_source="gateway_pre_dispatch_validation",
                                    changed_outcome=True,
                                    reason_code=(
                                        "unresolved_placeholder_tool_argument"
                                    ),
                                    possible_inappropriate_python_code_use=False,
                                )
                            )
                    except Exception:
                        pass
                    tool_payload = self._format_tool_result(
                        tool_name, None, None, "error", message
                    )
                    if callable(emit_progress):
                        emit_progress(
                            cast(
                                Mapping[str, Any],
                                placeholder_block["progress_payload"],
                            )
                        )
                    _append_tool_result_message(
                        tool_name=tool_name,
                        call_id=call_id,
                        content=tool_payload,
                    )
                    continue

                invocation_context = nullcontext()
                if request.workflow_id and request.workflow_state_id:
                    from ...workflows.workflow_mcp_tool_actions import (
                        _ontology_invocation_context,
                    )

                    # Carry the same admitted, actor-bound effect provenance as
                    # deterministic workflow tool steps. The canonical authority
                    # resolver still checks live target/scope permissions.
                    invocation_context = _ontology_invocation_context(
                        request=request,
                        resolved_tool_name=tool_name,
                        invocation_id=call_id or str(iteration_count),
                    )
                with invocation_context:
                    result = self._gateway.invoke(tool_name, payload)
                if (
                    isinstance(result.payload, Mapping)
                    and result.payload.get("success") is not False
                    and result.payload.get("image_attachments")
                ):
                    batch_image_messages.append({
                        "role": "user",
                        "content": "Retrieved source image evidence from " + tool_name,
                        "image_attachments": result.payload["image_attachments"],
                    })
                if tool_name_key == "workflow_execute" and isinstance(
                    aux_llm_calls, list
                ):
                    try:
                        workflow_execute_aux_entry = (
                            _build_awaited_workflow_execute_aux_entry(
                                tool_payload=payload,
                                tool_result_payload=result.payload,
                                parent_data=data,
                                user_namespace=env.user_namespace,
                            )
                        )
                    except Exception:
                        # Telemetry projection must never change the already
                        # completed tool call's semantics. Keep the failure
                        # bounded and observable without exposing child data.
                        workflow_execute_aux_entry = {
                            "type": "workflow_execute_result_snapshot",
                            "source": "workflow_execute_tool",
                            "status": "not_recorded",
                            "workflow_id": _workflow_execute_snapshot_text(
                                payload.get("workflow_id")
                            ),
                            "reason_code": (
                                "workflow_execute_snapshot_projection_failed"
                            ),
                        }
                    if isinstance(call_id, str) and call_id.strip():
                        workflow_execute_aux_entry["call_id"] = call_id.strip()
                    aux_llm_calls.append(workflow_execute_aux_entry)
                auto_retry_details: dict[str, Any] | None = None
                if tool_name == "add_relationship" and isinstance(
                    result.payload, Mapping
                ):
                    retry_payload, retry_context = (
                        self._retry_add_relationship_on_missing_reference(
                            payload=payload,
                            result_payload=cast(Mapping[str, Any], result.payload),
                        )
                    )
                    if retry_payload is not None and retry_context is not None:
                        auto_retry_details = dict(retry_context)
                        if callable(emit_progress):
                            emit_progress(
                                {
                                    "status": "tool_retry",
                                    "tool": tool_name,
                                    "batch_size": current_batch_size,
                                    "tool_calls_done": iteration_count,
                                    "tool_calls_cap": int(max_tool_invocations),
                                    "tool_calls_remaining": max(
                                        0, max_tool_invocations - iteration_count
                                    ),
                                    "call_id": call_id,
                                    "retry_reason": retry_context.get("reason"),
                                }
                            )
                        try:
                            retry_result = self._gateway.invoke(
                                tool_name, retry_payload
                            )
                        except Exception as retry_exc:
                            auto_retry_details["retry_error"] = str(retry_exc)
                        else:
                            result = retry_result
                            payload = retry_payload
                            tool_request[self._PAYLOAD_FIELD] = payload
                            auto_retry_details["retry_success"] = bool(
                                isinstance(result.payload, Mapping)
                                and result.payload.get("success")
                            )
                logical_error, logical_error_code = (
                    self._extract_logical_tool_error_details(result.payload)
                )
                tool_payload = self._format_tool_result(
                    tool_name,
                    result.payload,
                    result.duration_ms,
                    "ok",
                )
                result_summary = self._extract_result_summary(tool_name, result.payload)

                invocation_record: dict[str, Any] = {
                    "tool": tool_name,
                    "payload": payload_before_invoke,
                    "duration_ms": result.duration_ms,
                }
                transport_metadata_fn = getattr(result, "telemetry_metadata", None)
                transport_metadata = (
                    transport_metadata_fn() if callable(transport_metadata_fn) else None
                )
                if isinstance(transport_metadata, Mapping):
                    invocation_record["transport"] = dict(transport_metadata)
                    for transport_key in (
                        "execution_id",
                        "queue_duration_ms",
                        "handler_duration_ms",
                        "handler_elapsed_ms",
                        "transport_overhead_ms",
                        "timeout_sec",
                        "advisory_timeout_sec",
                        "advisory_budget_exceeded",
                        "timeout_phase",
                    ):
                        if transport_key in transport_metadata:
                            invocation_record[transport_key] = transport_metadata.get(
                                transport_key
                            )
                if isinstance(result.payload, Mapping):
                    invocation_record["effective_payload"] = dict(result.payload)
                if payload != payload_before_invoke:
                    invocation_record["effective_arguments"] = dict(payload)
                elif payload_before_invoke:
                    invocation_record["effective_arguments"] = dict(
                        payload_before_invoke
                    )
                if auto_retry_details:
                    invocation_record["auto_retry"] = auto_retry_details
                if write_interaction_metadata:
                    invocation_record["knowledge_interaction"] = (
                        write_interaction_metadata
                    )
                if tool_category == "write":
                    invocation_record["write_policy_risk_class"] = tool_write_risk_class
                    invocation_record["write_policy_outcome"] = (
                        tool_write_outcome or None
                    )
                    invocation_record["write_policy_decision_basis"] = (
                        write_policy_decision_basis
                    )
                    invocation_record["write_policy_effective_mutation_authority"] = (
                        write_policy_effective_mutation_authority or None
                    )
                    invocation_record["write_policy_authority_sources"] = (
                        dict(write_policy_authority_sources)
                        if write_policy_authority_sources
                        else {}
                    )
                    invocation_record["write_policy_scenario_id"] = (
                        tool_scenario_id or None
                    )
                    invocation_record["write_policy_risk_features"] = tool_risk_features
                    invocation_record["write_policy_unresolved_risk_factors"] = (
                        tool_unresolved_risk_factors
                    )
                    invocation_record["write_policy_intervention_kind"] = (
                        tool_intervention_kind or None
                    )
                    invocation_record["write_policy_confidence_state"] = (
                        tool_confidence_state or None
                    )
                    invocation_record["write_policy_request_evidence"] = (
                        dict(write_policy_request_evidence.get(tool_name) or {})
                        if write_policy_request_evidence.get(tool_name)
                        else {}
                    )
                    invocation_record["write_policy_request_evidence_diagnostics"] = (
                        dict(write_policy_request_evidence_diagnostics)
                        if write_policy_request_evidence_diagnostics
                        else {}
                    )
                    invocation_record["write_policy_profile_concept_id"] = (
                        write_policy_profile_concept_id or None
                    )
                    invocation_record["write_policy_profile_diagnostics"] = (
                        dict(write_policy_profile_diagnostics)
                        if write_policy_profile_diagnostics
                        else {}
                    )
                if call_id:
                    invocation_record["call_id"] = call_id
                if logical_error:
                    invocation_record["status"] = (
                        "timeout"
                        if isinstance(transport_metadata, Mapping)
                        and transport_metadata.get("outcome") == "timed_out"
                        else "error"
                    )
                    invocation_record["error"] = logical_error
                    if logical_error_code:
                        invocation_record["error_code"] = logical_error_code
                        if tool_category == "write" and isinstance(
                            result.payload, Mapping
                        ):
                            tool_surface_guardrail_event = (
                                self._build_tool_surface_guardrail_event(
                                    tool_name=tool_name,
                                    payload=cast(Mapping[str, Any], result.payload),
                                    stage="tool_execute",
                                    workflow_id=request.workflow_id,
                                    workflow_step_id=request.workflow_state_id,
                                    action_id=request.action_id,
                                    conversation_session_id=conversation_session_id,
                                    turn_id=(
                                        str(turn_id).strip()
                                        if isinstance(turn_id, str) and turn_id.strip()
                                        else None
                                    ),
                                    effective_mutation_authority=(
                                        write_policy_effective_mutation_authority
                                    ),
                                    authority_sources=write_policy_authority_sources,
                                )
                            )
                            if isinstance(tool_surface_guardrail_event, Mapping):
                                self._record_mutation_guardrail_events(
                                    events=(tool_surface_guardrail_event,),
                                    context=data,
                                    aux_llm_calls=aux_llm_calls,
                                )
                else:
                    invocation_record["status"] = "ok"
                if result_summary:
                    invocation_record["result_summary"] = result_summary
                invocations.append(invocation_record)

                progress_info: dict[str, Any] = {
                    "status": "tool_failed" if logical_error else "tool_invoked",
                    "tool": tool_name,
                    "batch_size": current_batch_size,
                    "tool_calls_done": iteration_count,
                    "tool_calls_cap": int(max_tool_invocations),
                    "tool_calls_remaining": max(
                        0, max_tool_invocations - iteration_count
                    ),
                    "call_id": call_id,
                }
                if result_summary:
                    progress_info["result_summary"] = result_summary
                if progress_argument_summary:
                    progress_info["tool_argument_summary"] = dict(
                        progress_argument_summary
                    )
                if logical_error:
                    progress_info["error"] = logical_error
                    if logical_error_code:
                        progress_info["error_code"] = logical_error_code
                if callable(emit_progress):
                    emit_progress(progress_info)

                self._logger.info(
                    "[mcp_orchestrator] Tool invocation #%d: tool=%s status=%s",
                    iteration_count,
                    tool_name,
                    "error" if logical_error else "ok",
                )
            except Exception as exc:
                tool_payload = self._format_tool_result(
                    tool_name, None, None, "error", str(exc)
                )
                error_record: dict[str, Any] = {
                    "tool": tool_name,
                    "payload": dict(payload),
                    "error": str(exc),
                }
                if write_interaction_metadata:
                    error_record["knowledge_interaction"] = write_interaction_metadata
                if call_id:
                    error_record["call_id"] = call_id
                invocations.append(error_record)
                if callable(emit_progress):
                    progress_payload = {
                        "status": "tool_failed",
                        "tool": tool_name,
                        "batch_size": current_batch_size,
                        "tool_calls_done": iteration_count,
                        "tool_calls_cap": int(max_tool_invocations),
                        "tool_calls_remaining": max(
                            0, max_tool_invocations - iteration_count
                        ),
                        "call_id": call_id,
                        "error": str(exc),
                    }
                    if progress_argument_summary:
                        progress_payload["tool_argument_summary"] = dict(
                            progress_argument_summary
                        )
                    emit_progress(progress_payload)
                self._logger.warning(
                    "[mcp_orchestrator] Tool %s failed: %s", tool_name, exc
                )

            _append_tool_result_message(
                tool_name=tool_name,
                call_id=call_id,
                content=tool_payload,
            )

        if (
            data.get("structured_tool_continuation") is not None
            and iteration_count >= max_tool_invocations
            and remaining_tool_calls
        ):
            for tool_request in remaining_tool_calls:
                if isinstance(tool_request, Mapping):
                    _append_tool_limit_result(tool_request)
            remaining_tool_calls = []

        # Keep provider tool-call responses intact; images are separate source
        # messages after the batch, hydrated and re-authorised at the provider.
        # The adaptive chat path already does this; durable llm.action uses this
        # execution path and otherwise receives only image descriptor JSON.
        augmented_context.extend(batch_image_messages)
        tool_messages.extend(batch_image_messages)

        # Store remaining overflow tool calls for the backfill handler.
        data["allowed_write_tools"] = allowed_write_tools
        data["write_policy_reason"] = write_policy_reason
        data["write_policy_decision_basis"] = write_policy_decision_basis
        data["write_policy_outcome"] = write_policy_outcome
        data["write_policy_effective_mutation_authority"] = (
            write_policy_effective_mutation_authority
        )
        data["write_policy_authority_sources"] = dict(write_policy_authority_sources)
        data["write_policy_risk_classes"] = dict(write_policy_risk_classes)
        data["write_policy_tool_outcomes"] = dict(write_policy_tool_outcomes)
        data["write_policy_blocked_reasons"] = dict(write_policy_blocked_reasons)
        data["write_policy_authority_block_sources"] = dict(
            write_policy_authority_block_sources
        )
        data["write_policy_scenario_ids"] = dict(write_policy_scenario_ids)
        data["write_policy_risk_features"] = {
            str(tool_name): dict(feature_map)
            for tool_name, feature_map in write_policy_risk_features.items()
            if isinstance(tool_name, str) and isinstance(feature_map, Mapping)
        }
        data["write_policy_unresolved_risk_factors"] = {
            str(tool_name): list(factors)
            for tool_name, factors in write_policy_unresolved_risk_factors.items()
            if isinstance(tool_name, str)
            and isinstance(factors, Sequence)
            and not isinstance(factors, (str, bytes))
        }
        data["write_policy_intervention_kinds"] = dict(write_policy_intervention_kinds)
        data["write_policy_confidence_states"] = dict(write_policy_confidence_states)
        data["write_policy_request_evidence"] = {
            str(tool_name): dict(evidence)
            for tool_name, evidence in write_policy_request_evidence.items()
            if isinstance(tool_name, str) and isinstance(evidence, Mapping)
        }
        data["write_policy_request_evidence_diagnostics"] = dict(
            write_policy_request_evidence_diagnostics
        )
        data["write_policy_profile_concept_id"] = (
            write_policy_profile_concept_id or None
        )
        data["write_policy_profile_diagnostics"] = dict(
            write_policy_profile_diagnostics
        )
        return WorkflowActionResult(
            outputs={
                "tool_execution_complete": True,
                "iteration_count": iteration_count,
                "remaining_tool_calls": remaining_tool_calls,
            }
        )

    def _workflow_step_backfill_prompt(
        self,
        data: Mapping[str, Any],
    ) -> tuple[str, bool, str | None]:
        output_contract = data.get("workflow_step_output_contract")
        if not isinstance(output_contract, Mapping):
            return (
                "Provide a final answer to the user now that the tool result is "
                "available. If the tool failed, explain the error. If you need to "
                "call another tool, you may do so.",
                False,
                None,
            )
        output_format = str(output_contract.get("output_format") or "").strip()
        if not output_format:
            return (
                "Provide a final answer to the user now that the tool result is "
                "available. If the tool failed, explain the error. If you need to "
                "call another tool, you may do so.",
                False,
                None,
            )

        authored_prompt = str(data.get("prompt") or "").strip()
        if len(authored_prompt) > 20_000:
            authored_prompt = authored_prompt[:20_000].rstrip() + "\n[truncated]"
        contract_summary = stable_json_dumps(output_contract, max_chars=6_000)
        rendered_prompt = self._render_authoritative_prompt(
            self._WORKFLOW_STEP_STRUCTURED_OUTPUT_BACKFILL_PROMPTS,
            variables={
                "output_format": output_format,
                "workflow_step_output_contract": contract_summary,
                "original_authoritative_workflow_step_instructions": authored_prompt,
            },
            max_chars=32_000,
            error_context="workflow_step_structured_output_backfill",
            required=True,
        )
        if rendered_prompt is None:  # pragma: no cover - required=True raises
            raise AuthoritativePromptUnavailableError(
                "workflow_step_structured_output_backfill_prompt_missing_or_empty"
            )
        return rendered_prompt.text, True, rendered_prompt.prompt_id

    def _action_tool_calling_backfill(self, request: Any) -> WorkflowActionResult:
        """Summariser LLM call after tool execution; detect chained tool calls.

        If there are remaining overflow tool calls (from batch capping),
        they are returned directly without an LLM call.  Otherwise a
        summariser call asks the LLM to produce a user-facing response or
        additional tool calls.

        Outputs:
            more_tool_calls (bool): True if chained tool calls were found.
            tool_calls (list | None): New tool calls (if any).
            tool_calls_present (bool): Same as more_tool_calls.
            final_response (str | None): Final text response (if done).
        """
        data = request.data
        env = request.environment
        llm_client = env.llm_client
        augmented_context = data["augmented_context"]
        policy_state = data["policy_state"]
        registry_snapshot = data.get("registry_snapshot")
        user_concept_id = data.get("user_concept_id")
        org_concept_id = data.get("org_concept_id")
        model_for_stage = data["model_for_stage"]
        record_llm_call = data["record_llm_call"]
        emit_progress_raw = data.get("emit_progress")
        emit_progress_cb: Callable[[Mapping[str, Any]], None] | None = (
            cast(Callable[[Mapping[str, Any]], None], emit_progress_raw)
            if callable(emit_progress_raw)
            else None
        )
        aux_llm_calls = data["aux_llm_calls"]
        llm_calls = data["llm_calls"]
        iteration_count = data.get("iteration_count", 0)
        max_tool_invocations = self._resolve_environment_max_tool_invocations(env)
        missing_tool_call_retry_attempts = self._coerce_non_negative_int(
            data.get("missing_tool_call_retry_attempts"),
            default=0,
            max_value=20,
        )
        missing_tool_call_retry_budget = self._coerce_non_negative_int(
            data.get("missing_tool_call_retry_budget"),
            default=self._max_missing_tool_call_retries_per_turn,
            max_value=20,
        )
        missing_tool_call_retry_suppressed = bool(
            data.get("missing_tool_call_retry_suppressed")
        )
        missing_tool_call_retry_stop_reason = (
            str(data.get("missing_tool_call_retry_stop_reason")).strip()
            if isinstance(data.get("missing_tool_call_retry_stop_reason"), str)
            else None
        )
        missing_tool_call_recovery_outcome = (
            str(data.get("missing_tool_call_recovery_outcome")).strip()
            if isinstance(data.get("missing_tool_call_recovery_outcome"), str)
            else None
        )
        agent_test_backfill_result = self._agent_test_local_relation_backfill_result(
            request=request,
            data=data,
            missing_tool_call_retry_attempts=missing_tool_call_retry_attempts,
            missing_tool_call_retry_budget=missing_tool_call_retry_budget,
            missing_tool_call_retry_suppressed=missing_tool_call_retry_suppressed,
            missing_tool_call_retry_stop_reason=missing_tool_call_retry_stop_reason,
            missing_tool_call_recovery_outcome=missing_tool_call_recovery_outcome,
        )
        if agent_test_backfill_result is not None:
            return agent_test_backfill_result

        # If there are overflow tool calls from batch capping, return them
        # directly as chained calls (no summariser LLM call needed).
        remaining = data.get("remaining_tool_calls") or []
        if remaining and iteration_count < max_tool_invocations:
            return WorkflowActionResult(
                outputs={
                    "more_tool_calls": True,
                    "tool_calls_present": True,
                    "tool_calls_validated": False,
                    "tool_calls": remaining,
                    "remaining_tool_calls": [],
                    "missing_tool_call_retry_attempts": missing_tool_call_retry_attempts,
                    "missing_tool_call_retry_budget": missing_tool_call_retry_budget,
                    "missing_tool_call_retry_remaining": max(
                        0,
                        missing_tool_call_retry_budget
                        - missing_tool_call_retry_attempts,
                    ),
                    "missing_tool_call_retry_suppressed": missing_tool_call_retry_suppressed,
                    "missing_tool_call_retry_stop_reason": missing_tool_call_retry_stop_reason,
                    "missing_tool_call_recovery_outcome": missing_tool_call_recovery_outcome,
                    "result": True,
                }
            )

        # Drain trusted tool-declared follow-up contracts before asking the
        # summariser to decide whether more tools are needed. This keeps
        # list/detail tool pairs generic while avoiding model-side re-planning
        # loops over the same list response.
        invocations_for_follow_up = cast(
            Sequence[Mapping[str, Any]], data.get("invocations") or []
        )
        pending_follow_up_tool_calls = self._extract_tool_follow_up_retry_tool_calls(
            missing_required_tools=(),
            tool_invocations=invocations_for_follow_up,
            require_missing_tool_match=False,
        )
        blocked_follow_up_tool_calls = (
            list(pending_follow_up_tool_calls or [])
            if pending_follow_up_tool_calls and iteration_count >= max_tool_invocations
            else []
        )
        if pending_follow_up_tool_calls and iteration_count < max_tool_invocations:
            import json

            current_response = (
                json.dumps(pending_follow_up_tool_calls[0])
                if len(pending_follow_up_tool_calls) == 1
                else json.dumps(pending_follow_up_tool_calls)
            )
            if isinstance(aux_llm_calls, list):
                try:
                    aux_llm_calls.append(
                        annotate_python_decision_event(
                            {
                                "type": "pending_tool_follow_up_contract",
                                "stage": "backfill",
                                "tool_call_count": len(pending_follow_up_tool_calls),
                                "tool_names": [
                                    str(call.get("tool"))
                                    for call in pending_follow_up_tool_calls
                                    if isinstance(call.get("tool"), str)
                                ],
                            },
                            stage="tool_follow_up_contract",
                            component="internal_mcp_orchestrator",
                            function="_action_tool_calling_backfill",
                            decision_class="tool_follow_up_contract",
                            decision_source="tool_result_metadata",
                            changed_outcome=True,
                            reason_code="pending_tool_declared_follow_up",
                            possible_inappropriate_python_code_use=False,
                        )
                    )
                except Exception:
                    pass
            return WorkflowActionResult(
                outputs={
                    "more_tool_calls": True,
                    "tool_calls_present": True,
                    "tool_calls_validated": False,
                    "tool_calls": pending_follow_up_tool_calls,
                    "current_response": current_response,
                    "remaining_tool_calls": [],
                    "missing_tool_call_retry_attempts": missing_tool_call_retry_attempts,
                    "missing_tool_call_retry_budget": missing_tool_call_retry_budget,
                    "missing_tool_call_retry_remaining": max(
                        0,
                        missing_tool_call_retry_budget
                        - missing_tool_call_retry_attempts,
                    ),
                    "missing_tool_call_retry_suppressed": missing_tool_call_retry_suppressed,
                    "missing_tool_call_retry_stop_reason": missing_tool_call_retry_stop_reason,
                    "missing_tool_call_recovery_outcome": missing_tool_call_recovery_outcome,
                    "result": True,
                }
            )

        # Summariser LLM call.
        (
            follow_up_prompt,
            preserve_workflow_step_output_contract,
            workflow_step_backfill_prompt_id,
        ) = self._workflow_step_backfill_prompt(data)
        if workflow_step_backfill_prompt_id and request.trace is not None:
            request.trace.record_prompt(
                prompt_id=workflow_step_backfill_prompt_id,
                resolved_prompt=follow_up_prompt,
                variables={
                    "workflow_step_output_contract": dict(
                        cast(Mapping[str, Any], data["workflow_step_output_contract"])
                    ),
                    "original_authoritative_workflow_step_instructions": str(
                        data.get("prompt") or ""
                    ),
                },
            )
        if preserve_workflow_step_output_contract and isinstance(aux_llm_calls, list):
            aux_llm_calls.append(
                annotate_python_decision_event(
                    {
                        "type": "workflow_step_output_contract_backfill",
                        "stage": "backfill",
                        "prompt_id": workflow_step_backfill_prompt_id,
                        "output_contract": dict(
                            cast(
                                Mapping[str, Any], data["workflow_step_output_contract"]
                            )
                        ),
                    },
                    stage="summariser",
                    component="internal_mcp_orchestrator",
                    function="_action_tool_calling_backfill",
                    decision_class="workflow_step_contract_preservation",
                    decision_source="authored_workflow_step_contract",
                    changed_outcome=True,
                    reason_code="structured_workflow_step_backfill",
                    possible_inappropriate_python_code_use=False,
                )
            )
        follow_up_context = self._build_follow_up_llm_context(
            augmented_context,
            max_chars=self._follow_up_context_chars,
        )

        def _backfill_prompt_requirement_state() -> dict[str, Any]:
            method_catalogue_for_requirements = (
                self._resolve_method_catalogue_for_workflow_data(data)
            )
            selected_gmail_profile_for_retry = (
                self._selected_gmail_profile_for_workflow_data(data, env)
            )
            prompt_for_requirements = data.get("prompt_for_requirements")
            if (
                not isinstance(prompt_for_requirements, str)
                or not prompt_for_requirements.strip()
            ):
                prompt_for_requirements = (
                    data.get("prompt") if isinstance(data.get("prompt"), str) else ""
                )

            invocations_for_requirements = cast(
                Sequence[Mapping[str, Any]], data.get("invocations") or []
            )
            prompt_requirement_url_policy = data.get("prompt_requirement_url_policy")
            prompt_requirements = self._evaluate_prompt_requirements(
                prompt_text=prompt_for_requirements,
                method_catalogue=(
                    method_catalogue_for_requirements
                    if isinstance(method_catalogue_for_requirements, Mapping)
                    else None
                ),
                context_messages=follow_up_context,
                tool_invocations=invocations_for_requirements,
                url_requirement=(
                    prompt_requirement_url_policy
                    if isinstance(prompt_requirement_url_policy, Mapping)
                    else None
                ),
            )
            prompt_requirements = self._augment_prompt_requirements_with_turn_contract(
                evaluation=prompt_requirements,
                turn_expected_outcome_contract=self._build_turn_expected_outcome_contract_object(
                    data
                ),
                method_catalogue=(
                    method_catalogue_for_requirements
                    if isinstance(method_catalogue_for_requirements, Mapping)
                    else None
                ),
                allowed_tools=(
                    tuple(data.get("llm_allowed_tools"))
                    if isinstance(data.get("llm_allowed_tools"), Sequence)
                    and not isinstance(
                        data.get("llm_allowed_tools"), (str, bytes, bytearray)
                    )
                    else None
                ),
                tool_invocations=invocations_for_requirements,
            )
            prompt_requirements = (
                self._merge_prompt_requirements_with_existing_tool_policy(
                    data=data,
                    evaluation=prompt_requirements,
                    method_catalogue=(
                        method_catalogue_for_requirements
                        if isinstance(method_catalogue_for_requirements, Mapping)
                        else None
                    ),
                    tool_invocations=invocations_for_requirements,
                )
            )
            required_prompt_tools = list(prompt_requirements.required_tools)
            missing_prompt_tools = list(prompt_requirements.missing_tools)
            missing_required_tools_for_retry = self._missing_required_tools_for_retry(
                required_tools=required_prompt_tools,
                missing_tools=missing_prompt_tools,
                tool_invocations=invocations_for_requirements,
            )
            missing_prompt_fetch_concept_ids = list(
                prompt_requirements.missing_fetch_concept_ids
            )
            missing_prompt_read_file_copy_ids = list(
                prompt_requirements.missing_read_file_copy_ids
            )
            missing_prompt_scholarly_representation_file_copy_ids = list(
                prompt_requirements.missing_scholarly_representation_file_copy_ids
            )
            self._store_prompt_requirement_evaluation(data, prompt_requirements)
            return {
                "method_catalogue_for_requirements": method_catalogue_for_requirements,
                "selected_gmail_profile_for_retry": selected_gmail_profile_for_retry,
                "prompt_for_requirements": prompt_for_requirements,
                "invocations_for_requirements": invocations_for_requirements,
                "prompt_requirements": prompt_requirements,
                "required_prompt_tools": required_prompt_tools,
                "missing_required_tools_for_retry": missing_required_tools_for_retry,
                "missing_prompt_fetch_concept_ids": missing_prompt_fetch_concept_ids,
                "missing_prompt_read_file_copy_ids": missing_prompt_read_file_copy_ids,
                "missing_prompt_scholarly_representation_file_copy_ids": (
                    missing_prompt_scholarly_representation_file_copy_ids
                ),
                "required_prompt_create_type_name": (
                    prompt_requirements.required_create_type_name
                ),
                "has_unmet_prompt_requirements": bool(
                    missing_required_tools_for_retry
                    or missing_prompt_fetch_concept_ids
                    or missing_prompt_read_file_copy_ids
                    or missing_prompt_scholarly_representation_file_copy_ids
                    or prompt_requirements.required_create_type_name
                ),
            }

        def _parent_forced_backfill_result(
            requirement_state: Mapping[str, Any],
            *,
            reason_code: str,
        ) -> WorkflowActionResult | None:
            if not bool(requirement_state.get("has_unmet_prompt_requirements")):
                return None
            prompt_requirements = requirement_state.get("prompt_requirements")
            if not isinstance(prompt_requirements, _PromptRequirementEvaluation):
                return None
            invocations_for_requirements = cast(
                Sequence[Mapping[str, Any]],
                requirement_state.get("invocations_for_requirements") or [],
            )
            parent_forced_tool_calls = self._infer_missing_tool_call_retry_tool_calls(
                follow_up_context,
                user_prompt=(
                    requirement_state.get("prompt_for_requirements")
                    if isinstance(requirement_state.get("prompt_for_requirements"), str)
                    else (
                        data.get("prompt")
                        if isinstance(data.get("prompt"), str)
                        else ""
                    )
                ),
                turn_expected_outcome_contract=(
                    self._build_turn_expected_outcome_contract_object(data)
                ),
                workflow_required_effects_contract=(
                    data.get("workflow_required_effects_contract")
                    if isinstance(
                        data.get("workflow_required_effects_contract"), Mapping
                    )
                    else None
                ),
                workflow_required_effects_contract_source=(
                    str(data.get("workflow_required_effects_contract_source")).strip()
                    if isinstance(
                        data.get("workflow_required_effects_contract_source"), str
                    )
                    and str(
                        data.get("workflow_required_effects_contract_source")
                    ).strip()
                    else None
                ),
                missing_required_tools=cast(
                    Sequence[str],
                    requirement_state.get("missing_required_tools_for_retry") or [],
                ),
                missing_required_fetch_concept_ids=cast(
                    Sequence[str],
                    requirement_state.get("missing_prompt_fetch_concept_ids") or [],
                ),
                missing_required_read_file_copy_ids=cast(
                    Sequence[str],
                    requirement_state.get("missing_prompt_read_file_copy_ids") or [],
                ),
                missing_required_scholarly_representation_file_copy_ids=cast(
                    Sequence[str],
                    requirement_state.get(
                        "missing_prompt_scholarly_representation_file_copy_ids"
                    )
                    or [],
                ),
                required_create_type_name=cast(
                    str | None,
                    requirement_state.get("required_prompt_create_type_name"),
                ),
                required_url_extraction_url=(
                    prompt_requirements.required_url_extraction_url
                ),
                tool_invocations=invocations_for_requirements,
                tool_argument_defaults=(
                    data.get("tool_argument_defaults")
                    if isinstance(data.get("tool_argument_defaults"), Mapping)
                    else None
                ),
                invoked_tool_names=(
                    self._extract_successful_tool_names(invocations_for_requirements)
                ),
                user_concept_id=(
                    str(data.get("user_concept_id")).strip()
                    if isinstance(data.get("user_concept_id"), str)
                    and str(data.get("user_concept_id")).strip()
                    else None
                ),
                workflow_discovery_result=(
                    data.get("workflow_discovery_result")
                    if isinstance(data.get("workflow_discovery_result"), Mapping)
                    else None
                ),
                workflow_execute_inputs=self._build_turn_launchability_probe_inputs(
                    prompt_text=str(
                        data.get("user_prompt") or data.get("prompt") or ""
                    ).strip(),
                    augmented_context=follow_up_context,
                    workflow_discovery_result=(
                        data.get("workflow_discovery_result")
                        if isinstance(data.get("workflow_discovery_result"), Mapping)
                        else None
                    ),
                    continuation_context=(
                        data.get("continuation_context")
                        if isinstance(data.get("continuation_context"), Mapping)
                        else None
                    ),
                    user_namespace=getattr(env, "user_namespace", None),
                    user_concept_id=(
                        str(data.get("user_concept_id")).strip()
                        if isinstance(data.get("user_concept_id"), str)
                        and str(data.get("user_concept_id")).strip()
                        else None
                    ),
                    org_concept_id=(
                        str(data.get("org_concept_id")).strip()
                        if isinstance(data.get("org_concept_id"), str)
                        and str(data.get("org_concept_id")).strip()
                        else None
                    ),
                    gmail_profile=(
                        str(data.get("gmail_profile")).strip()
                        if isinstance(data.get("gmail_profile"), str)
                        and str(data.get("gmail_profile")).strip()
                        else None
                    ),
                    base_data=data if isinstance(data, Mapping) else None,
                ),
                method_catalogue=(
                    requirement_state.get("method_catalogue_for_requirements")
                    if isinstance(
                        requirement_state.get("method_catalogue_for_requirements"),
                        Mapping,
                    )
                    else None
                ),
                selected_gmail_profile=(
                    str(
                        requirement_state.get("selected_gmail_profile_for_retry")
                    ).strip()
                    if isinstance(
                        requirement_state.get("selected_gmail_profile_for_retry"), str
                    )
                    and str(
                        requirement_state.get("selected_gmail_profile_for_retry")
                    ).strip()
                    else None
                ),
                user_namespace=getattr(env, "user_namespace", None),
                conversation_session_id=(
                    str(data.get("conversation_session_id")).strip()
                    if isinstance(data.get("conversation_session_id"), str)
                    and str(data.get("conversation_session_id")).strip()
                    else None
                ),
                turn_id=(
                    str(data.get("turn_id")).strip()
                    if isinstance(data.get("turn_id"), str)
                    and str(data.get("turn_id")).strip()
                    else None
                ),
            )
            if not parent_forced_tool_calls:
                return None

            import json

            public_parent_forced_tool_calls = (
                self._strip_retry_tool_call_internal_metadata(parent_forced_tool_calls)
            )
            retry_binding_sources = self._summarise_retry_tool_call_binding_sources(
                parent_forced_tool_calls
            )
            current_response = (
                json.dumps(public_parent_forced_tool_calls[0])
                if len(public_parent_forced_tool_calls) == 1
                else json.dumps(public_parent_forced_tool_calls)
            )
            if (
                isinstance(aux_llm_calls, list)
                and iteration_count < max_tool_invocations
            ):
                try:
                    aux_llm_calls.append(
                        annotate_python_decision_event(
                            {
                                "type": "missing_tool_call_retry",
                                "path": "legacy",
                                "mechanism": "structured_parent_fallback",
                                "stage": "backfill",
                                "retry_reason": (
                                    data.get("missing_tool_call_retry_reason") or ""
                                ),
                                "response_preview": current_response[:800],
                                "retry_binding_sources": retry_binding_sources,
                            },
                            stage="missing_tool_recovery",
                            component="internal_mcp_orchestrator",
                            function="_action_tool_calling_backfill",
                            decision_class="missing_tool_call_retry",
                            decision_source="structured_retry_parent_fallback",
                            changed_outcome=True,
                            reason_code=reason_code,
                            possible_inappropriate_python_code_use=False,
                        )
                    )
                except Exception:
                    pass
            return WorkflowActionResult(
                outputs={
                    "more_tool_calls": True,
                    "tool_calls_present": True,
                    "tool_calls_validated": False,
                    "tool_calls": public_parent_forced_tool_calls,
                    "current_response": current_response,
                    "remaining_tool_calls": [],
                    "missing_tool_call_retry_attempts": missing_tool_call_retry_attempts,
                    "missing_tool_call_retry_budget": missing_tool_call_retry_budget,
                    "missing_tool_call_retry_remaining": max(
                        0,
                        missing_tool_call_retry_budget
                        - missing_tool_call_retry_attempts,
                    ),
                    "missing_tool_call_retry_suppressed": False,
                    "missing_tool_call_retry_stop_reason": None,
                    "missing_tool_call_recovery_outcome": (
                        "retry_succeeded_parent_fallback"
                    ),
                    "result": True,
                }
            )

        pre_summariser_requirement_state = _backfill_prompt_requirement_state()
        pre_summariser_forced_result = _parent_forced_backfill_result(
            pre_summariser_requirement_state,
            reason_code="structured_tool_call_replayed_before_summariser",
        )
        if pre_summariser_forced_result is not None:
            if iteration_count < max_tool_invocations:
                return pre_summariser_forced_result
            missing_tool_call_retry_suppressed = True
            missing_tool_call_retry_stop_reason = "tool_invocation_budget_exhausted"
            missing_tool_call_recovery_outcome = "tool_invocation_budget_exhausted"
            forced_calls = pre_summariser_forced_result.outputs.get("tool_calls")
            if isinstance(forced_calls, Sequence) and not isinstance(
                forced_calls, (str, bytes, bytearray)
            ):
                for forced_call in forced_calls:
                    if (
                        isinstance(forced_call, Mapping)
                        and forced_call not in blocked_follow_up_tool_calls
                    ):
                        blocked_follow_up_tool_calls.append(dict(forced_call))

        follow_up_stage_messages = [
            *self._build_synthesiser_context_prep_stage_messages(data),
            *self._build_turn_expected_outcome_stage_messages(
                data=data,
                stage="summariser",
            ),
            *self._build_tool_follow_up_stage_messages(data=data),
        ]
        follow_up_context, follow_up_context_telemetry = self._build_stage_llm_context(
            base_context=follow_up_context,
            stage="summariser",
            base_context_source="follow_up_context",
            stage_messages=follow_up_stage_messages,
        )
        self._attach_memory_context_lineage(
            follow_up_context_telemetry,
            turn_memory_context_state=self._copy_string_key_mapping(
                data.get("turn_memory_context_state")
            ),
        )
        data["tool_follow_up_context_lineage"] = dict(follow_up_context_telemetry)

        raw_structured_continuation = data.get("structured_tool_continuation")
        structured_continuation = LLMContinuation.from_value(
            raw_structured_continuation
        )
        if raw_structured_continuation is not None and structured_continuation is None:
            raise StructuredToolProtocolError(
                "Stored structured continuation payload is malformed; refusing "
                "an uncorrelated follow-up after tool execution."
            )
        if structured_continuation is not None:
            allow_more_tool_calls = iteration_count < max_tool_invocations
            represented_call_ids = structured_continuation.transport_decision.get(
                "accepted_tool_call_ids"
            )
            if isinstance(represented_call_ids, Sequence) and not isinstance(
                represented_call_ids, (str, bytes, bytearray)
            ):
                expected_call_ids = {
                    str(call_id)
                    for call_id in represented_call_ids
                    if isinstance(call_id, str) and call_id.strip()
                }
            else:
                expected_call_ids = {
                    str(item.get("call_id"))
                    for item in structured_continuation.output_items
                    if item.get("type") == "function_call" and item.get("call_id")
                }
            correlated_results: dict[str, ToolResult] = {}
            for message in data.get("tool_messages") or []:
                if not isinstance(message, Mapping):
                    continue
                call_id = message.get("tool_call_id")
                if not isinstance(call_id, str) or call_id not in expected_call_ids:
                    continue
                correlated_results[call_id] = ToolResult(
                    call_id=call_id,
                    tool_name=(
                        str(message.get("name"))
                        if isinstance(message.get("name"), str)
                        else None
                    ),
                    output=message.get("content"),
                    status="ok",
                )

            method_catalogue = self._resolve_method_catalogue_for_workflow_data(data)
            continuation_tool_definitions = (
                self._convert_mcp_tools_to_structured_definitions(
                    method_catalogue=(
                        method_catalogue
                        if isinstance(method_catalogue, Mapping)
                        else None
                    )
                )
            )
            allowed_tool_names = {
                str(tool_name).strip().lower()
                for tool_name in (data.get("llm_allowed_tools") or [])
                if isinstance(tool_name, str) and str(tool_name).strip()
            }
            if allowed_tool_names:
                continuation_tool_definitions = [
                    definition
                    for definition in continuation_tool_definitions
                    if definition.name.strip().lower() in allowed_tool_names
                ]
            continuation_response, continuation_model, _ = (
                self._run_llm_with_tools_fallbacks(
                    stage="tool_follow_up",
                    prompt=follow_up_prompt,
                    context=follow_up_context,
                    tool_definitions=continuation_tool_definitions,
                    authored_tool_names=(
                        tuple(sorted(allowed_tool_names))
                        if request.action_id == "llm.action"
                        else ()
                    ),
                    default_client=llm_client,
                    default_model=structured_continuation.model,
                    policy_state=policy_state,
                    registry_snapshot=registry_snapshot,
                    user_concept_id=user_concept_id,
                    org_concept_id=org_concept_id,
                    llm_calls_log=llm_calls,
                    aux_log=aux_llm_calls,
                    record_llm_call=record_llm_call,
                    emit_progress=emit_progress_cb,
                    workflow_action_id=request.action_id,
                    method_catalogue=(
                        method_catalogue
                        if isinstance(method_catalogue, Mapping)
                        else None
                    ),
                    context_telemetry=follow_up_context_telemetry,
                    prefer_default_model=True,
                    workflow_stage_id="screen_backfill",
                    workflow_id=(
                        request.workflow_id
                        if isinstance(getattr(request, "workflow_id", None), str)
                        else None
                    ),
                    continuation=structured_continuation,
                    tool_results=list(correlated_results.values()),
                    tool_choice_override=(None if allow_more_tool_calls else "none"),
                )
            )
            if continuation_response.tool_calls:
                if not allow_more_tool_calls:
                    raise StructuredToolProtocolError(
                        "Structured continuation returned another tool call after the "
                        "configured tool invocation limit was reached.",
                        decision=(
                            dict(continuation_response.transport_metadata)
                            if isinstance(
                                continuation_response.transport_metadata, Mapping
                            )
                            else {}
                        ),
                    )
                next_continuation = continuation_response.continuation
                return WorkflowActionResult(
                    outputs={
                        "more_tool_calls": True,
                        "tool_calls_present": True,
                        "tool_calls_validated": False,
                        "tool_calls": [
                            {
                                self._ACTION_FIELD: self._CALL_ACTION,
                                self._TOOL_FIELD: call.tool_name,
                                self._PAYLOAD_FIELD: call.payload,
                                "_call_id": call.call_id,
                            }
                            for call in continuation_response.tool_calls
                        ],
                        "current_response": continuation_response.text_response,
                        "remaining_tool_calls": [],
                        "structured_tool_continuation": (
                            next_continuation.to_mapping()
                            if next_continuation is not None
                            else None
                        ),
                        "tool_call_model": continuation_model,
                        "result": True,
                    }
                )

            safe_continuation_response = self._sanitise_user_visible_action_output(
                continuation_response.text_response,
                aux_log=aux_llm_calls if isinstance(aux_llm_calls, list) else None,
                source_stage="tool_calling.structured_backfill",
            )
            if blocked_follow_up_tool_calls:
                if callable(emit_progress_cb):
                    emit_progress_cb(
                        {
                            "status": "tool_limit_reached",
                            "tool_calls_done": iteration_count,
                            "tool_calls_cap": int(max_tool_invocations),
                            "tool_calls_remaining": 0,
                            "pending_follow_up_tool_call_count": len(
                                blocked_follow_up_tool_calls
                            ),
                            "settings_key": "internal_mcp_max_tool_invocations",
                        }
                    )
                safe_continuation_response = self._ensure_tool_limit_notice(
                    safe_continuation_response,
                    tool_calls_done=int(iteration_count),
                    tool_calls_cap=int(max_tool_invocations),
                    pending_follow_up_tool_call_count=len(blocked_follow_up_tool_calls),
                )
                if isinstance(aux_llm_calls, list):
                    try:
                        aux_llm_calls.append(
                            annotate_python_decision_event(
                                {
                                    "type": "tool_limit_finalisation",
                                    "stage": "backfill",
                                    "tool_calls_done": int(iteration_count),
                                    "tool_calls_cap": int(max_tool_invocations),
                                    "pending_follow_up_tool_call_count": len(
                                        blocked_follow_up_tool_calls
                                    ),
                                    "settings_key": (
                                        "internal_mcp_max_tool_invocations"
                                    ),
                                    "response_preview": (
                                        safe_continuation_response[:800]
                                    ),
                                },
                                stage="tool_limit_finalisation",
                                component="internal_mcp_orchestrator",
                                function="_action_tool_calling_backfill",
                                decision_class=("tool_budget_exhausted_finalisation"),
                                decision_source="completed_tool_context",
                                changed_outcome=True,
                                reason_code=(
                                    "tool_invocation_budget_exhausted_with_"
                                    "pending_follow_up"
                                ),
                                possible_inappropriate_python_code_use=False,
                            )
                        )
                    except Exception:
                        pass
                return WorkflowActionResult(
                    outputs={
                        "more_tool_calls": False,
                        "tool_calls_present": False,
                        "final_response": safe_continuation_response,
                        "current_response": safe_continuation_response,
                        "structured_tool_continuation": None,
                        "tool_call_model": continuation_model,
                        "tool_limit_reached": True,
                        "tool_limit_settings_key": (
                            "internal_mcp_max_tool_invocations"
                        ),
                        "pending_follow_up_tool_call_count": len(
                            blocked_follow_up_tool_calls
                        ),
                        "missing_tool_call_retry_attempts": (
                            missing_tool_call_retry_attempts
                        ),
                        "missing_tool_call_retry_budget": (
                            missing_tool_call_retry_budget
                        ),
                        "missing_tool_call_retry_remaining": max(
                            0,
                            missing_tool_call_retry_budget
                            - missing_tool_call_retry_attempts,
                        ),
                        "missing_tool_call_retry_suppressed": (
                            missing_tool_call_retry_suppressed
                        ),
                        "missing_tool_call_retry_stop_reason": (
                            missing_tool_call_retry_stop_reason
                        ),
                        "missing_tool_call_recovery_outcome": (
                            missing_tool_call_recovery_outcome
                        ),
                        "result": False,
                    }
                )
            return WorkflowActionResult(
                outputs={
                    "more_tool_calls": False,
                    "tool_calls_present": False,
                    "final_response": safe_continuation_response,
                    "current_response": safe_continuation_response,
                    "structured_tool_continuation": None,
                    "tool_call_model": continuation_model,
                    "result": False,
                }
            )

        summariser_model = model_for_stage("summariser")
        if blocked_follow_up_tool_calls:
            if callable(emit_progress_cb):
                emit_progress_cb(
                    {
                        "status": "tool_limit_reached",
                        "tool_calls_done": iteration_count,
                        "tool_calls_cap": int(max_tool_invocations),
                        "tool_calls_remaining": 0,
                        "pending_follow_up_tool_call_count": len(
                            blocked_follow_up_tool_calls
                        ),
                        "settings_key": "internal_mcp_max_tool_invocations",
                    }
                )
            limit_finaliser_prompt = (
                "The configured tool invocation limit stopped this turn before "
                "all pending required or follow-up tool calls could run. Produce the best "
                "final answer using only the completed tool results already "
                "available in the conversation context. Do not call another tool. "
                f"Explicitly tell the user that the cause was reaching "
                f"`internal_mcp_max_tool_invocations={int(max_tool_invocations)}` "
                f"after {int(iteration_count)} tool call(s), with "
                f"{len(blocked_follow_up_tool_calls)} pending follow-up call(s) "
                "blocked by that setting. Tell them they can raise that setting "
                "or narrow the request. Then present any grounded partial answer "
                "supported by the completed tool calls."
            )
            current_response, summariser_model, _ = self._run_llm_with_fallbacks(
                stage="summariser",
                prompt=limit_finaliser_prompt,
                context=follow_up_context,
                default_client=llm_client,
                default_model=summariser_model,
                policy_state=policy_state,
                registry_snapshot=registry_snapshot,
                user_concept_id=user_concept_id,
                org_concept_id=org_concept_id,
                llm_calls_log=llm_calls,
                aux_log=aux_llm_calls,
                record_llm_call=record_llm_call,
                emit_progress=emit_progress_cb,
                context_telemetry=follow_up_context_telemetry,
                prefer_default_model=bool(data.get("prefer_default_model")),
                workflow_stage_id="screen_backfill",
            )
            current_response = self._ensure_tool_limit_notice(
                current_response if isinstance(current_response, str) else "",
                tool_calls_done=int(iteration_count),
                tool_calls_cap=int(max_tool_invocations),
                pending_follow_up_tool_call_count=len(blocked_follow_up_tool_calls),
            )
            if isinstance(aux_llm_calls, list):
                try:
                    aux_llm_calls.append(
                        annotate_python_decision_event(
                            {
                                "type": "tool_limit_finalisation",
                                "stage": "backfill",
                                "tool_calls_done": int(iteration_count),
                                "tool_calls_cap": int(max_tool_invocations),
                                "pending_follow_up_tool_call_count": len(
                                    blocked_follow_up_tool_calls
                                ),
                                "settings_key": "internal_mcp_max_tool_invocations",
                                "response_preview": (
                                    current_response[:800]
                                    if isinstance(current_response, str)
                                    else str(current_response)[:800]
                                ),
                            },
                            stage="tool_limit_finalisation",
                            component="internal_mcp_orchestrator",
                            function="_action_tool_calling_backfill",
                            decision_class="tool_budget_exhausted_finalisation",
                            decision_source="completed_tool_context",
                            changed_outcome=True,
                            reason_code=(
                                "tool_invocation_budget_exhausted_with_pending_follow_up"
                            ),
                            possible_inappropriate_python_code_use=False,
                        )
                    )
                except Exception:
                    pass
            safe_final_response = self._sanitise_user_visible_action_output(
                current_response,
                aux_log=aux_llm_calls if isinstance(aux_llm_calls, list) else None,
                source_stage="tool_calling.backfill",
            )
            return WorkflowActionResult(
                outputs={
                    "more_tool_calls": False,
                    "tool_calls_present": False,
                    "final_response": safe_final_response,
                    "current_response": safe_final_response,
                    "tool_limit_reached": True,
                    "tool_limit_settings_key": "internal_mcp_max_tool_invocations",
                    "pending_follow_up_tool_call_count": len(
                        blocked_follow_up_tool_calls
                    ),
                    "missing_tool_call_retry_attempts": missing_tool_call_retry_attempts,
                    "missing_tool_call_retry_budget": missing_tool_call_retry_budget,
                    "missing_tool_call_retry_remaining": max(
                        0,
                        missing_tool_call_retry_budget
                        - missing_tool_call_retry_attempts,
                    ),
                    "missing_tool_call_retry_suppressed": missing_tool_call_retry_suppressed,
                    "missing_tool_call_retry_stop_reason": missing_tool_call_retry_stop_reason,
                    "missing_tool_call_recovery_outcome": missing_tool_call_recovery_outcome,
                    "result": False,
                }
            )
        current_response, summariser_model, _ = self._run_llm_with_fallbacks(
            stage="summariser",
            prompt=follow_up_prompt,
            context=follow_up_context,
            default_client=llm_client,
            default_model=summariser_model,
            policy_state=policy_state,
            registry_snapshot=registry_snapshot,
            user_concept_id=user_concept_id,
            org_concept_id=org_concept_id,
            llm_calls_log=llm_calls,
            aux_log=aux_llm_calls,
            record_llm_call=record_llm_call,
            emit_progress=emit_progress_cb,
            context_telemetry=follow_up_context_telemetry,
            prefer_default_model=bool(data.get("prefer_default_model")),
            workflow_stage_id="screen_backfill",
        )

        # Check if the summariser response contains more tool calls.
        if iteration_count < max_tool_invocations:
            interpretation = self._interpret_model_turn(current_response)
            if interpretation.tool_calls:
                return WorkflowActionResult(
                    outputs={
                        "more_tool_calls": True,
                        "tool_calls_present": True,
                        "tool_calls_validated": False,
                        "tool_calls": interpretation.tool_calls,
                        "current_response": current_response,
                        "remaining_tool_calls": [],
                        "missing_tool_call_retry_attempts": missing_tool_call_retry_attempts,
                        "missing_tool_call_retry_budget": missing_tool_call_retry_budget,
                        "missing_tool_call_retry_remaining": max(
                            0,
                            missing_tool_call_retry_budget
                            - missing_tool_call_retry_attempts,
                        ),
                        "missing_tool_call_retry_suppressed": missing_tool_call_retry_suppressed,
                        "missing_tool_call_retry_stop_reason": missing_tool_call_retry_stop_reason,
                        "missing_tool_call_recovery_outcome": missing_tool_call_recovery_outcome,
                        "result": True,
                    }
                )

            method_catalogue_for_requirements = (
                self._resolve_method_catalogue_for_workflow_data(data)
            )
            selected_gmail_profile_for_retry = (
                self._selected_gmail_profile_for_workflow_data(data, env)
            )

            prompt_for_requirements = data.get("prompt_for_requirements")
            if (
                not isinstance(prompt_for_requirements, str)
                or not prompt_for_requirements.strip()
            ):
                prompt_for_requirements = (
                    data.get("prompt") if isinstance(data.get("prompt"), str) else ""
                )

            invocations_for_requirements = cast(
                Sequence[Mapping[str, Any]], data.get("invocations") or []
            )
            prompt_requirement_url_policy = data.get("prompt_requirement_url_policy")
            prompt_requirements = self._evaluate_prompt_requirements(
                prompt_text=prompt_for_requirements,
                method_catalogue=(
                    method_catalogue_for_requirements
                    if isinstance(method_catalogue_for_requirements, Mapping)
                    else None
                ),
                context_messages=follow_up_context,
                tool_invocations=invocations_for_requirements,
                url_requirement=(
                    prompt_requirement_url_policy
                    if isinstance(prompt_requirement_url_policy, Mapping)
                    else None
                ),
            )
            prompt_requirements = self._augment_prompt_requirements_with_turn_contract(
                evaluation=prompt_requirements,
                turn_expected_outcome_contract=self._build_turn_expected_outcome_contract_object(
                    data
                ),
                method_catalogue=(
                    method_catalogue_for_requirements
                    if isinstance(method_catalogue_for_requirements, Mapping)
                    else None
                ),
                allowed_tools=(
                    tuple(data.get("llm_allowed_tools"))
                    if isinstance(data.get("llm_allowed_tools"), Sequence)
                    and not isinstance(
                        data.get("llm_allowed_tools"), (str, bytes, bytearray)
                    )
                    else None
                ),
                tool_invocations=invocations_for_requirements,
            )
            prompt_requirements = (
                self._merge_prompt_requirements_with_existing_tool_policy(
                    data=data,
                    evaluation=prompt_requirements,
                    method_catalogue=(
                        method_catalogue_for_requirements
                        if isinstance(method_catalogue_for_requirements, Mapping)
                        else None
                    ),
                    tool_invocations=invocations_for_requirements,
                )
            )
            required_prompt_tools = list(prompt_requirements.required_tools)
            required_prompt_fetch_concept_ids = list(
                prompt_requirements.required_fetch_concept_ids
            )
            required_prompt_read_file_copy_ids = list(
                prompt_requirements.required_read_file_copy_ids
            )
            required_prompt_scholarly_representation_file_copy_ids = list(
                prompt_requirements.required_scholarly_representation_file_copy_ids
            )
            required_prompt_create_type_name = (
                prompt_requirements.required_create_type_name
            )
            missing_prompt_tools = list(prompt_requirements.missing_tools)
            missing_required_tools_for_retry = self._missing_required_tools_for_retry(
                required_tools=required_prompt_tools,
                missing_tools=missing_prompt_tools,
                tool_invocations=invocations_for_requirements,
            )
            missing_prompt_fetch_concept_ids = list(
                prompt_requirements.missing_fetch_concept_ids
            )
            missing_prompt_read_file_copy_ids = list(
                prompt_requirements.missing_read_file_copy_ids
            )
            missing_prompt_scholarly_representation_file_copy_ids = list(
                prompt_requirements.missing_scholarly_representation_file_copy_ids
            )
            self._store_prompt_requirement_evaluation(data, prompt_requirements)
            has_unmet_prompt_requirements = bool(
                missing_required_tools_for_retry
                or missing_prompt_fetch_concept_ids
                or missing_prompt_read_file_copy_ids
                or missing_prompt_scholarly_representation_file_copy_ids
                or required_prompt_create_type_name
            )

            if isinstance(aux_llm_calls, list) and required_prompt_tools:
                try:
                    aux_llm_calls.append(
                        annotate_python_decision_event(
                            {
                                "type": "prompt_tool_requirements",
                                "stage": "tool_execute",
                                "required_tools": list(required_prompt_tools),
                                "missing_tools": list(missing_required_tools_for_retry),
                                "required_fetch_concept_ids": list(
                                    required_prompt_fetch_concept_ids
                                ),
                                "missing_fetch_concept_ids": list(
                                    missing_prompt_fetch_concept_ids
                                ),
                                "required_read_file_copy_ids": list(
                                    required_prompt_read_file_copy_ids
                                ),
                                "missing_read_file_copy_ids": list(
                                    missing_prompt_read_file_copy_ids
                                ),
                                "required_scholarly_representation_for_file_copy_ids": list(
                                    required_prompt_scholarly_representation_file_copy_ids
                                ),
                                "missing_scholarly_representation_for_file_copy_ids": list(
                                    missing_prompt_scholarly_representation_file_copy_ids
                                ),
                                "required_create_type_name": (
                                    required_prompt_create_type_name
                                ),
                                "invoked_tools": [
                                    str(item.get("tool"))
                                    for item in invocations_for_requirements
                                    if isinstance(item.get("tool"), str)
                                ],
                            },
                            stage="tool_execute",
                            component="internal_mcp_orchestrator",
                            function="_action_tool_calling_respond",
                            decision_class="prompt_requirement_inference",
                            decision_source="explicit_identifier_parse",
                            changed_outcome=bool(missing_required_tools_for_retry),
                            reason_code=(
                                "explicit_prompt_tool_requirement_missing"
                                if missing_required_tools_for_retry
                                else "explicit_prompt_tool_requirement_satisfied"
                            ),
                            possible_inappropriate_python_code_use=False,
                        )
                    )
                except Exception:
                    pass

            exc = interpretation.tool_call_parse_error
            recovery_reason: str | None = None
            semantic_retry_reason_override: str | None = None
            override_retry_reason = data.get("missing_tool_call_retry_reason_override")
            has_override_retry_reason = isinstance(override_retry_reason, str) and bool(
                str(override_retry_reason).strip()
            )
            if exc is not None:
                recovery_reason = "parse_error"
            elif has_override_retry_reason:
                recovery_reason = "required_prompt_tools_missing"
            elif has_unmet_prompt_requirements:
                recovery_reason = "required_prompt_tools_missing"
